def _tf_token_to_ds(token: Any) -> str:
    t = clean(token)
    if not t:
        return ""
    if t.upper() in ("Đ", "D"):
        return "Đ"
    if t.upper() == "S":
        return "S"
    k = key_norm(t)
    if k in ["d", "đ", "dung", "đung", "đúng", "true", "t"]:
        return "Đ"
    if k in ["s", "sai", "false", "f"]:
        return "S"
    return ""


def parse_tf_values(value: Any) -> List[str]:
    """Chuẩn hóa đáp án Đ/S thành danh sách 4 phần tử (A,B,C,D)."""
    if isinstance(value, dict):
        mp = {"a": 0, "b": 1, "c": 2, "d": 3}
        out = ["", "", "", ""]
        for k, v in value.items():
            idx = mp.get(clean(k).lower()[:1])
            if idx is None:
                continue
            tok = _tf_token_to_ds(v)
            if tok:
                out[idx] = tok
        if sum(1 for x in out if x) >= 2:
            return out

    if isinstance(value, list):
        out = [_tf_token_to_ds(v) for v in value]
        while len(out) < 4:
            out.append("")
        return out[:4]

    raw = clean(value)
    if not raw:
        return ["", "", "", ""]

    # key_norm: Đúng → dung (strip_accents một mình để lại đung → regex không khớp)
    low = key_norm(raw)
    letter_hits = re.findall(
        r"(?:^|[\s;,|·]+)(?:[\[\(]?\s*([abcd])\s*[\]\)]?\s*[-.:=]?\s*)"
        r"(dung|d|sai|s|true|false)\b",
        low,
        re.I,
    )
    if len(letter_hits) >= 2:
        mp = {"a": 0, "b": 1, "c": 2, "d": 3}
        out = ["", "", "", ""]
        for letter, word in letter_hits:
            idx = mp.get(clean(letter).lower())
            if idx is None:
                continue
            tok = _tf_token_to_ds(word)
            if tok:
                out[idx] = tok
        if sum(1 for x in out if x) >= 2:
            return out

    parts = re.split(r"[,;|/\n]+", raw)
    if len(parts) >= 2:
        out = [_tf_token_to_ds(p) for p in parts]
        if sum(1 for x in out if x) >= 2:
            while len(out) < 4:
                out.append("")
            return out[:4]

    s = key_norm(raw).replace(" ", "")
    s = s.replace("dung", "d").replace("true", "d").replace("false", "s").replace("sai", "s")
    vals = re.findall(r"[ds]", s)[:4]
    out = ["Đ" if v == "d" else "S" for v in vals]
    while len(out) < 4:
        out.append("")
    return out[:4]


def format_tf_answer_display(q: Dict[str, Any], dapan: Any = None) -> str:
    vals = parse_tf_values(dapan if dapan is not None else q.get("DapAn"))
    bits = []
    for idx, L in enumerate(["A", "B", "C", "D"]):
        if not clean(q.get(L)):
            continue
        v = vals[idx] if idx < len(vals) else ""
        if v == "Đ":
            bits.append(f"{L}=Đúng")
        elif v == "S":
            bits.append(f"{L}=Sai")
    return " · ".join(bits) if bits else clean(dapan if dapan is not None else q.get("DapAn"))


def looks_like_dungsai_answer(value: Any) -> bool:
    """Đáp án có ≥2 mệnh đề Đ/S — không nhầm trắc nghiệm một chữ A/B/C/D."""
    if value is None or not clean(value):
        return False
    raw = strip_accents(clean(value).upper()).strip()
    if re.fullmatch(r"[ABCD]", raw):
        return False
    vals = parse_tf_values(value)
    filled = [v for v in vals if v in ("Đ", "S")]
    return len(filled) >= 2


def has_tf_statements(q: Dict[str, Any]) -> bool:
    count = 0
    for L in ["A", "B", "C", "D"]:
        if clean(q.get(L)):
            count += 1
    return count >= 2


def is_mcq_letter_answer(value: Any) -> bool:
    """Đáp án trắc nghiệm: đúng một chữ A/B/C/D."""
    raw = strip_accents(clean(value).upper()).strip()
    return bool(re.fullmatch(r"[ABCD]", raw))


def looks_like_short_answer(q: Dict[str, Any]) -> bool:
    """Đáp án là số hoặc chuỗi kết quả — không phải chọn A/B/C/D hay Đ/S."""
    dapan = clean(q.get("DapAn"))
    if not dapan:
        return False
    if is_mcq_letter_answer(dapan):
        return False
    if looks_like_dungsai_answer(dapan):
        return False
    if parse_float_vn(dapan) is not None:
        return True
    return len(dapan) <= 200



def question_dang(q: Dict[str, Any]) -> str:
    """Dạng câu chuẩn — luôn suy từ cột J/H + đáp án."""
    ed = effective_dang(q)
    if ed in ("Đúng sai", "Trắc nghiệm", "Trả lời ngắn", "Tự luận"):
        return ed
    return norm_dang(ed)


def dang_matches(q: Dict[str, Any], dang_filter: str) -> bool:
    if not clean(dang_filter):
        return True
    return question_dang(q) == norm_dang(dang_filter)


def dangbaitap_is_unclassified(q: Dict[str, Any]) -> bool:
    """Cột H trống hoặc mang giá trị placeholder — chưa phân loại dạng bài tập."""
    return _is_bad_dangbaitap_value(q.get("DangBaiTap", ""))


def dangbaitap_matches(q: Dict[str, Any], dbt_filter: str) -> bool:
    if not clean(dbt_filter):
        return True
    fn = clean(dbt_filter)
    if fn == DBT_FILTER_UNCLASSIFIED or key_norm(fn) in {
        key_norm("chua phan loai"),
        key_norm("chưa phân loại"),
        key_norm("chua gan"),
        key_norm("chưa gán"),
    }:
        return dangbaitap_is_unclassified(q)
    qv = one_line(q.get("DangBaiTap", ""))
    if not qv:
        return False
    qn = key_norm(qv)
    fn = key_norm(one_line(fn))
    return qn == fn or fn in qn or qn in fn


def dang_metadata_raw(q: Dict[str, Any]) -> str:
    """
    Chỉ lấy DẠNG CÂU từ cột Dang / _DangCol.
    KHÔNG lấy DangBaiTap vì DangBaiTap là dạng bài tập/chuyên đề,
    không phải loại câu Trắc nghiệm / Đúng sai.
    """
    for k in ("_DangCol", "Dang"):
        v = clean(q.get(k, ""))
        if v:
            return v
    return ""


def effective_dang(q: Dict[str, Any]) -> str:
    """
    Suy luận dạng câu chắc chắn:
    - Nếu đáp án là đúng 1 chữ A/B/C/D và có phương án -> Trắc nghiệm.
    - Nếu đáp án có nhiều Đ/S -> Đúng sai.
    - Nếu cột Dang ghi rõ Trắc nghiệm/Đúng sai/TLN/Tự luận -> dùng cột Dang.
    - Nếu đáp án là số/biểu thức -> Trả lời ngắn.

    Lưu ý: DangBaiTap là dạng bài tập/chuyên đề nên không được dùng để ép loại câu.
    Khi cột Dang có giá trị lạ (không nhận ra), gắn q["_DangWarn"] để log/cảnh báo.
    """
    dapan = q.get("DapAn")
    has_opts = has_tf_statements(q)

    # ƯU TIÊN CAO NHẤT: đáp án 1 chữ A/B/C/D + có phương án => Trắc nghiệm.
    # Như vậy AI không bị chuyển nhầm sang chốt Đúng/Sai.
    if is_mcq_letter_answer(dapan) and has_opts:
        return "Trắc nghiệm"

    # Đáp án kiểu Đ,S,S,Đ hoặc A=Đúng B=Sai => Đúng sai.
    if looks_like_dungsai_answer(dapan):
        return "Đúng sai"

    # Sau khi đã bắt chắc bằng đáp án, mới dùng cột Dang nếu có ghi rõ.
    raw_col = dang_metadata_raw(q)
    if raw_col:
        dang_col, dang_reason = norm_dang_explain(raw_col)
        if dang_col in DANG_GROUP_ORDER:
            # Gắn cảnh báo vào câu nếu Dang lạ (để api_sync / import có thể log)
            if "⚠" in dang_reason:
                q["_DangWarn"] = f"Dang '{raw_col}' → '{dang_col}' ({dang_reason})"
            return dang_col

    # Đáp án số/biểu thức => Trả lời ngắn.
    if looks_like_short_answer(q):
        return "Trả lời ngắn"

    return "Trắc nghiệm"


NANG_LUC_VAT_LY: Dict[str, str] = {
    "NLVL01": "Nhận biết và trình bày kiến thức vật lí",
    "NLVL02": "Phân tích, giải thích và phản biện vật lí",
    "NLVL03": "Đề xuất vấn đề và xây dựng giả thuyết",
    "NLVL04": "Lập kế hoạch và thực hiện tìm hiểu vật lí",
    "NLVL05": "Xử lí dữ liệu, kết luận và báo cáo",
    "NLVL06": "Vận dụng vật lí vào thực tiễn và đề xuất giải pháp",
}


def norm_nang_luc_vat_ly(value: Any) -> str:
    """Chuẩn hóa về đúng một mã NLVL01–NLVL06."""
    raw = clean(value).upper().replace(" ", "")
    m = re.search(r"NLVL0?([1-6])", raw)
    if m:
        return f"NLVL0{m.group(1)}"
    k = key_norm(value)
    if not k:
        return ""
    mapping = [
        ("NLVL01", ["nhan biet va trinh bay", "nhan biet", "trinh bay kien thuc"]),
        ("NLVL02", ["phan tich giai thich", "phan bien vat li", "giai thich va phan bien"]),
        ("NLVL03", ["xay dung gia thuyet", "de xuat van de", "du doan gia thuyet"]),
        ("NLVL04", ["lap ke hoach", "thuc hien tim hieu", "dung cu bien so quy trinh"]),
        ("NLVL05", ["xu li du lieu", "ket luan va bao cao", "bang so lieu do thi"]),
        ("NLVL06", ["van dung vat li vao thuc tien", "de xuat giai phap", "thiet ke ra quyet dinh"]),
    ]
    for code, phrases in mapping:
        if any(p in k for p in phrases):
            return code
    return ""


def nang_luc_vat_ly_name(value: Any) -> str:
    return NANG_LUC_VAT_LY.get(norm_nang_luc_vat_ly(value), "")


DANG_GROUP_ORDER = ["Trắc nghiệm", "Đúng sai", "Trả lời ngắn", "Tự luận"]
RANDOM_PRACTICE_SPEC: List[Tuple[str, int]] = [
    ("Trắc nghiệm", 18),
    ("Đúng sai", 4),
    ("Trả lời ngắn", 6),
]

QUESTION_REVIEW_APPROVED = frozenset(
    {"DA DUYET", "DADUYET", "DUYET", "OK", "1", "YES", "TRUE", "APPROVED", "XONG", "DONE"}
)
QUESTION_REVIEW_PENDING = frozenset(
    {"CHUA DUYET", "CHUADUYET", "PENDING", "NO", "0", "FALSE", "CAN DUYET", "CHUA KIEM"}
)
QUESTION_REVIEW_APPROVED_LABEL = "ĐÃ DUYỆT"
QUESTION_REVIEW_PENDING_LABEL = "CHƯA DUYỆT"


def strict_question_review() -> bool:
    """Khi bật: học sinh chỉ làm câu có cột TrangThai = ĐÃ DUYỆT."""
    return str(os.environ.get("STRICT_QUESTION_REVIEW", "0")).strip().lower() in ("1", "true", "yes")


def question_review_status(q: Dict[str, Any]) -> str:
    st = key_norm(q.get("TrangThai", ""))
    if not st:
        return "legacy" if not strict_question_review() else "pending"
    if st in QUESTION_REVIEW_APPROVED or "da duyet" in st or "approved" in st:
        return "approved"
    if st in QUESTION_REVIEW_PENDING or "chua duyet" in st or "pending" in st:
        return "pending"
    return "legacy" if not strict_question_review() else "pending"


def question_is_reviewed(q: Dict[str, Any]) -> bool:
    return question_review_status(q) == "approved"


def question_is_reviewed_sheet(q: Dict[str, Any]) -> bool:
    """Chỉ coi đã duyệt khi Sheet ghi rõ — dùng cho giao diện ADMIN."""
    st = key_norm(q.get("TrangThai", ""))
    if not st:
        return False
    if st in QUESTION_REVIEW_APPROVED or "da duyet" in st or "approved" in st:
        return True
    if st in QUESTION_REVIEW_PENDING or "chua duyet" in st or "pending" in st:
        return False
    return False


def question_is_student_visible(q: Dict[str, Any]) -> bool:
    if is_admin():
        return True
    return question_is_reviewed(q)


def filter_questions_for_students(qs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if is_admin():
        return list(qs or [])
    return [q for q in (qs or []) if question_is_student_visible(q)]


def question_solution_status(q: Dict[str, Any]) -> str:
    """Đánh giá lời giải Sheet: full (đủ tự học) | partial | none."""
    dap = clean(q.get("DapAn", ""))
    lg = clean(q.get("LoiGiai", ""))
    if not lg or len(lg) < 20:
        return "none" if not dap else "partial"
    if not dap:
        return "partial"
    dang = effective_dang(q)
    if dang == "Đúng sai":
        need = [L for L in "ABCD" if clean(q.get(L))]
        lg_map = _parse_loigiai_bodies_by_letter(lg)
        if len(need) >= 2:
            missing = [L for L in need if L not in lg_map or len(lg_map.get(L, "")) < 12]
            if not missing and len(lg) >= 50:
                return "full"
            return "partial" if lg_map else ("partial" if len(lg) >= 35 else "none")
        return "partial" if len(lg) >= 40 else "none"
    if dang == "Trắc nghiệm":
        if is_mcq_letter_answer(dap) and len(lg) >= 40:
            return "full"
        return "partial" if len(lg) >= 22 else "none"
    if dang == "Trả lời ngắn":
        return "full" if len(lg) >= 30 else ("partial" if len(lg) >= 18 else "none")
    if dang == "Tự luận":
        return "full" if len(lg) >= 70 else ("partial" if len(lg) >= 35 else "none")
    return "full" if len(lg) >= 45 else "partial"


def derive_khoi(lop: Any) -> str:
    """Suy Khối (10/11/12) từ cột Lớp — vd. 12QT1 → 12."""
    s = clean(lop)
    if not s:
        return ""
    m = re.match(r"^(\d{1,2})", s)
    if m:
        return m.group(1)
    m2 = re.search(r"\b(10|11|12)\b", s)
    return m2.group(1) if m2 else ""


def question_matches_pool_filter(
    q: Dict[str, Any],
    *,
    mon: str = "",
    khoi: str = "",
    lop: str = "",
    chuong: str = "",
    chuongs: Optional[List[str]] = None,
    baihoc: str = "",
    bode: str = "",
    level: str = "",
    sol_full_only: bool = False,
) -> bool:
    if mon and clean(q.get("Mon")) != mon:
        return False
    if khoi and derive_khoi(q.get("Lop", "")) != clean(khoi):
        return False
    if lop and clean(q.get("Lop")) != lop:
        return False
    ch_list = [clean(c) for c in (chuongs or []) if clean(c)]
    if ch_list:
        if clean(q.get("Chuong")) not in ch_list:
            return False
    elif chuong and clean(q.get("Chuong")) != chuong:
        return False
    if baihoc and clean(q.get("BaiHoc")) != baihoc:
        return False
    if bode and clean(q.get("BoDe")) != bode:
        return False
    lv = clean(level).upper()
    if lv and lv not in question_mucdo_parts(q) and lv not in clean(q.get("MucDo", "")).upper():
        return False
    if sol_full_only and question_solution_status(q) != "full":
        return False
    if is_trial() and access_level_from_text(q.get("QuyenTruyCap", "")) != "FREE":
        return False
    if not question_is_student_visible(q):
        return False
    return True


def keyword_search_normalize(s: Any) -> str:
    """Chuẩn hóa chuỗi để tìm từ khóa: hạ chữ thường + gộp khoảng trắng thừa."""
    return re.sub(r"\s+", " ", str(s or "")).strip().lower()


QUESTION_KEYWORD_SEARCH_FIELDS = ("ID", "CauHoi", "A", "B", "C", "D", "LoiGiai")


def question_matches_keyword(q: Dict[str, Any], keyword_norm: str) -> bool:
    """Kiểm tra từ khóa (đã chuẩn hóa) có xuất hiện trong ID/nội dung/phương án/lời giải."""
    if not keyword_norm:
        return True
    for field in QUESTION_KEYWORD_SEARCH_FIELDS:
        if keyword_norm in keyword_search_normalize(q.get(field, "")):
            return True
    return False


def pool_matrix_counts(pool: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Đếm câu trong phạm vi theo ma trận Dạng × Mức độ (NB/TH/VD/VDC)."""
    levels = ["NB", "TH", "VD", "VDC"]
    matrix: Dict[str, Dict[str, int]] = {d: {lv: 0 for lv in levels} for d in DANG_GROUP_ORDER}
    row_any: Dict[str, int] = {d: 0 for d in DANG_GROUP_ORDER}
    for q in pool:
        d = question_dang(q)
        if d not in matrix:
            matrix[d] = {lv: 0 for lv in levels}
            row_any[d] = 0
        row_any[d] = row_any.get(d, 0) + 1
        lv = _primary_mucdo(q)
        if lv and lv in matrix[d]:
            matrix[d][lv] += 1
    return {
        "matrix": matrix,
        "row_any": row_any,
        "total": len(pool),
        "levels": levels,
        "dangs": list(DANG_GROUP_ORDER),
    }


def pick_compose_questions(
    pool: List[Dict[str, Any]],
    items: List[Dict[str, Any]],
) -> Tuple[List[Dict[str, Any]], List[str]]:
    """Lấy câu theo ma trận {dang, level, count} — không trùng ID."""
    used: set = set()
    picked: List[Dict[str, Any]] = []
    shortages: List[str] = []

    def q_key(q: Dict[str, Any]) -> str:
        return clean(q.get("ID", "")) or f"row:{q.get('_row', '')}"

    for item in items or []:
        dang = norm_dang(clean(item.get("dang", "")))
        level = clean(item.get("level", "")).upper()
        try:
            need = int(item.get("count") or 0)
        except (TypeError, ValueError):
            need = 0
        if need <= 0 or not dang:
            continue
        candidates: List[Dict[str, Any]] = []
        for q in pool:
            k = q_key(q)
            if k in used:
                continue
            if question_dang(q) != dang:
                continue
            if level:
                parts = question_mucdo_parts(q)
                raw = clean(q.get("MucDo", "")).upper()
                if level not in parts and level not in raw:
                    continue
            candidates.append(q)
        if len(candidates) < need:
            shortages.append(
                f"{dang}" + (f" · {level}" if level else " · mọi mức")
                + f": cần {need}, có {len(candidates)}"
            )
            take = list(candidates)
        else:
            take = random.sample(candidates, need)
        for q in take:
            used.add(q_key(q))
            picked.append(q)
    return picked, shortages


MUCDO_GROUP_ORDER = ["NB", "TH", "VD", "VDC", ""]


def _primary_mucdo(q: Dict[str, Any]) -> str:
    parts = question_mucdo_parts(q)
    for lv in ("NB", "TH", "VD", "VDC"):
        if lv in parts:
            return lv
    raw = clean(q.get("MucDo", "")).upper()
    for lv in ("NB", "TH", "VD", "VDC"):
        if lv in raw:
            return lv
    return ""


def sort_questions_by_dang_groups(
    qs: List[Dict[str, Any]],
    *,
    shuffle_within: bool = False,
) -> List[Dict[str, Any]]:
    """Sắp xếp câu theo LOẠI CÂU בלבד: TN / Đúng-Sai / TLN / Tự luận.

    Không tách nhỏ theo NB/TH/VD/VDC nữa, vì các mức độ chỉ là màu trong
    cùng một dạng. Ví dụ: tất cả câu Trắc nghiệm nằm chung một nhóm;
    ô số câu vẫn tô màu theo cột I (NB/TH/VD/VDC).
    """
    buckets: Dict[str, List[Dict[str, Any]]] = {}
    for q in qs:
        d = question_dang(q)
        buckets.setdefault(d, []).append(q)

    out: List[Dict[str, Any]] = []
    known_dang = list(DANG_GROUP_ORDER)
    extra_dang = sorted([d for d in buckets.keys() if d not in known_dang], key=key_norm)
    for d in known_dang + extra_dang:
        chunk = list(buckets.get(d, []))
        if shuffle_within and len(chunk) > 1:
            random.shuffle(chunk)
        out.extend(chunk)
    return out


def norm_role(s: Any) -> str:
    k = key_norm(s).replace(".", "")
    # Chấp nhận nhiều cách ghi quyền quản trị trong sheet HOC_VIEN:
    # ADMIN, Admin, Quản trị viên, Quan tri vien, QuanTriVien...
    k_compact = re.sub(r"[^a-z0-9]+", "", k)
    if (
        "admin" in k
        or "quan tri" in k
        or "quantri" in k_compact
        or "quan ly" in k
        or "quanly" in k_compact
        or k_compact in {"qtv", "qtri", "administrator"}
    ):
        return "ADMIN"
    if "svip" in k or "s vip" in k or "super" in k:
        return "S.VIP"
    if "trial" in k or "dung thu" in k or "thu nghiem" in k:
        return "TRIAL"
    if (
        "vip" in k
        or "premium" in k
        or "co phi" in k
        or "tra phi" in k
        or "traphi" in k
        or "member" in k
        or "plus" in k
    ):
        return "VIP"
    if "free" in k or "mien phi" in k:
        return "FREE"
    return clean(s).upper() or "FREE"


def refresh_session_role_from_store() -> None:
    """Cập nhật role từ sheet HOC_VIEN (tránh session cũ ghi FREE trong khi sheet đã VIP)."""
    mahs = clean(session.get("mahs", ""))
    if not mahs:
        return
    try:
        st = get_store()
        st.ensure_users_loaded()
        user = st.users.get(mahs)
        if not user:
            for k, v in st.users.items():
                if key_norm(k) == key_norm(mahs):
                    user = v
                    break
        if user and user.get("role"):
            session["role"] = norm_role(user.get("role"))
    except Exception:
        log_swallow("refresh_session_role_from_store:2990")
        pass


def is_admin() -> bool:
    refresh_session_role_from_store()
    return norm_role(session.get("role", "")) == "ADMIN"


def is_svip() -> bool:
    refresh_session_role_from_store()
    return norm_role(session.get("role", "")) == "S.VIP"


def is_trial() -> bool:
    return session.get("role") == "TRIAL"


def can_use_5050() -> bool:
    # Học viên dùng thử KHÔNG dùng 50:50. Chỉ VIP/S.VIP/ADMIN.
    return session.get("role") in ["VIP", "S.VIP", "ADMIN"]


def can_view_solution_after_submit() -> bool:
    # FREE và TRIAL không xem đáp án/lời giải sau nộp.
    return session.get("role") in ["VIP", "S.VIP", "ADMIN"]


def can_view_solution_live() -> bool:
    """VIP/SVIP/ADMIN có quyền xem đáp án/lời giải khi làm bài (client: sau khi làm + chấm từng câu)."""
    refresh_session_role_from_store()
    return norm_role(session.get("role", "")) in ["VIP", "S.VIP", "ADMIN"]


def can_use_infographic() -> bool:
    """VIP/SVIP/ADMIN: tạo prompt infographic (VIP/SVIP phải trả lời đúng câu trước)."""
    refresh_session_role_from_store()
    return norm_role(session.get("role", "")) in ["VIP", "S.VIP", "ADMIN"]


def can_exact_hint() -> bool:
    role = session.get("role", "")
    return role in ["VIP", "S.VIP", "SVIP", "ADMIN"]


def is_vip_formula_hint() -> bool:
    """VIP/SVIP: gợi ý công thức thay số — không đưa đáp án cuối trong AI gợi ý."""
    refresh_session_role_from_store()
    r = norm_role(session.get("role", ""))
    return r in ["VIP", "S.VIP"]


def can_use_ai_hint() -> bool:
    """Chỉ VIP / SVIP / ADMIN được dùng Gợi ý AI."""
    if is_admin():
        return True
    refresh_session_role_from_store()
    return norm_role(session.get("role", "")) in ["VIP", "S.VIP"]




def can_use_quiz_ai_hint() -> bool:
    """Gợi ý AI trên màn làm bài — tắt theo FEATURE_QUIZ_AI_HINT."""
    if not FEATURE_QUIZ_AI_HINT:
        return False
    return can_use_ai_hint()


def can_use_quiz_similar() -> bool:
    if not FEATURE_QUIZ_SIMILAR:
        return False
    return can_use_ai_hint()


def can_use_quiz_retry() -> bool:
    return bool(FEATURE_QUIZ_RETRY)


