def sanitize_pyodide_model_code(code: Any) -> str:
    """Chuẩn hóa mã AI để chạy trên Pyodide (numpy + matplotlib)."""
    if isinstance(code, list):
        code = "\n".join(str(x) for x in code)
    s = str(code or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if not s:
        return ""
    # Gỡ fence markdown nếu AI bọc ngoài JSON
    s = re.sub(r"^```(?:python|py)?\s*\n?", "", s, flags=re.I)
    s = re.sub(r"\n?```\s*$", "", s)
    s = s.strip()
    # Thư viện không có trên Pyodide app
    banned = (
        "scipy", "pandas", "sympy", "sklearn", "tensorflow", "torch",
        "pygame", "tkinter", "PIL", "cv2", "requests", "seaborn", "plotly",
        "manim", "numba", "jax",
    )
    lines_out: List[str] = []
    for line in s.split("\n"):
        low = line.strip().lower()
        if low.startswith("import ") or low.startswith("from "):
            if any(re.search(rf"\b{re.escape(b)}\b", low) for b in banned):
                lines_out.append("# " + line + "  # không hỗ trợ trên app — đã bỏ")
                continue
        # plt.show() trên Agg không vẽ — app tự chụp figure
        line2 = re.sub(r"\bplt\.show\s*\(\s*\)", "pass  # app tự hiện đồ thị", line)
        line2 = re.sub(r"\bpyplot\.show\s*\(\s*\)", "pass  # app tự hiện đồ thị", line2)
        # chặn I/O nguy hiểm
        if re.search(r"\b(input|open|exec|eval|__import__)\s*\(", line2):
            lines_out.append("# " + line2 + "  # đã chặn trên app")
            continue
        lines_out.append(line2)
    out = "\n".join(lines_out).strip()
    if len(out) > MODEL_APP_CODE_MAX:
        out = out[:MODEL_APP_CODE_MAX]
    return out


def extract_model_code_from_ai_obj(raw: Dict[str, Any]) -> str:
    """Lấy mã Python từ nhiều kiểu JSON AI hay trả."""
    if not isinstance(raw, dict):
        return ""
    for key in ("code", "python", "source", "script", "py"):
        v = raw.get(key)
        if isinstance(v, list):
            joined = "\n".join(str(x) for x in v).strip()
            if joined:
                return sanitize_pyodide_model_code(joined)
        s = str(v or "").strip()
        if s:
            return sanitize_pyodide_model_code(s)
    # đôi khi nhét trong markdown field
    for key in ("content", "text", "answer"):
        s = str(raw.get(key) or "")
        m = re.search(r"```(?:python|py)?\s*([\s\S]+?)```", s, flags=re.I)
        if m:
            return sanitize_pyodide_model_code(m.group(1))
    return ""
DELETED_QIDS_FILE = os.path.join(APP_DIR, "data", "deleted_question_ids.json")
_DELETED_QIDS_LOCK = threading.Lock()
_DELETED_QIDS_CACHE: Optional[set] = None


def _ensure_deleted_qids_dir() -> None:
    try:
        os.makedirs(os.path.dirname(DELETED_QIDS_FILE), exist_ok=True)
    except Exception:
        log_swallow("_ensure_deleted_qids_dir")


def load_deleted_question_ids(force: bool = False) -> set:
    """ID câu đã xóa — dùng chung giữa các worker để câu không 'hiện lại' từ RAM cũ."""
    global _DELETED_QIDS_CACHE
    with _DELETED_QIDS_LOCK:
        if _DELETED_QIDS_CACHE is not None and not force:
            return set(_DELETED_QIDS_CACHE)
        ids: set = set()
        try:
            if os.path.isfile(DELETED_QIDS_FILE):
                with open(DELETED_QIDS_FILE, "r", encoding="utf-8") as f:
                    raw = json.load(f)
                if isinstance(raw, list):
                    ids = {clean(x) for x in raw if clean(x)}
                elif isinstance(raw, dict):
                    ids = {clean(x) for x in (raw.get("ids") or []) if clean(x)}
        except Exception:
            log_swallow("load_deleted_question_ids")
            ids = set()
        _DELETED_QIDS_CACHE = set(ids)
        return set(_DELETED_QIDS_CACHE)


def save_deleted_question_ids(ids) -> None:
    global _DELETED_QIDS_CACHE
    cleaned = sorted({clean(x) for x in (ids or []) if clean(x)})
    with _DELETED_QIDS_LOCK:
        _ensure_deleted_qids_dir()
        tmp = DELETED_QIDS_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"ids": cleaned, "updated_at": now_str()}, f, ensure_ascii=False, indent=2)
        os.replace(tmp, DELETED_QIDS_FILE)
        _DELETED_QIDS_CACHE = set(cleaned)


def mark_question_ids_deleted(ids) -> None:
    add = {clean(x) for x in (ids or []) if clean(x)}
    if not add:
        return
    cur = load_deleted_question_ids(force=True)
    cur |= add
    # Giữ tối đa 5000 ID gần nhất.
    if len(cur) > 5000:
        cur = set(sorted(cur)[-5000:])
    save_deleted_question_ids(cur)


def reconcile_deleted_question_ids_with_loaded(loaded_ids) -> None:
    """Sau khi nạp Sheet: bỏ tombstone của ID vẫn còn trên Sheet (xóa thất bại)."""
    loaded = {clean(x) for x in (loaded_ids or []) if clean(x)}
    cur = load_deleted_question_ids(force=True)
    if not cur:
        return
    # Chỉ giữ ID không còn trên Sheet — các worker khác vẫn lọc được.
    keep = {x for x in cur if x not in loaded}
    if keep != cur:
        save_deleted_question_ids(keep)



