def parse_similar_variant_tips(text: Any) -> Dict[str, Any]:
    """Tách mục «5. GỢI Ý BIẾN THỂ» thành gợi ý cho ADMIN tạo câu tránh trùng."""
    raw = clean(text)
    if not raw:
        return {}
    m = re.search(
        r"(?:^|\n)\s*5\.\s*GỢI\s*Ý\s*BIẾN\s*THỂ[^\n]*\n([\s\S]*?)(?=\n\s*\d+\.\s+[A-ZÀ-Ỹ]|\Z)",
        raw,
        flags=re.I,
    )
    if not m:
        m = re.search(
            r"(?:^|\n)\s*(?:GỢI\s*Ý\s*BIẾN\s*THỂ|ADMIN\s*[-–:]?\s*TRÁNH\s*TRÙNG)[^\n]*\n([\s\S]*?)(?=\n\s*\d+\.\s+[A-ZÀ-Ỹ]|\Z)",
            raw,
            flags=re.I,
        )
    block = clean(m.group(1)) if m else ""
    if not block:
        return {}

    def _field(labels: List[str]) -> str:
        for lab in labels:
            mm = re.search(
                rf"(?im)^\s*[-*+]?\s*{lab}\s*[:：]\s*(.+)$",
                block,
            )
            if mm:
                return clean(mm.group(1))
        return ""

    def _split_items(s: str) -> List[str]:
        s = clean(s)
        if not s:
            return []
        parts = re.split(r"\s*[;|•]\s*|\s+-\s+", s)
        out = [clean(x).strip(" .") for x in parts if clean(x)]
        return out[:6]

    ideas: List[str] = []
    im = re.search(
        r"(?is)Ý\s*tưởng\s*câu\s*tránh\s*trùng\s*[:：]?\s*(.+)$",
        block,
    )
    if im:
        for ln in re.split(r"[\n\r]+", im.group(1)):
            t = clean(re.sub(r"^\s*[-*+•]\s*", "", ln))
            if t and not re.match(
                r"^(Đại lượng|Có thể đổi|Nên đổi)", t, flags=re.I
            ):
                ideas.append(t)
            if len(ideas) >= 4:
                break

    tips = {
        "original_find": _field(
            [
                r"Đại\s*lượng\s*gốc\s*đang\s*tìm",
                r"Đang\s*tìm",
                r"Đại\s*lượng\s*cần\s*tìm\s*gốc",
            ]
        ),
        "suggest_find": _split_items(
            _field(
                [
                    r"Có\s*thể\s*đổi\s*sang\s*tìm",
                    r"Đổi\s*sang\s*tìm",
                    r"Nên\s*tìm\s*đại\s*lượng",
                ]
            )
        ),
        "suggest_change": _split_items(
            _field(
                [
                    r"Nên\s*đổi\s*số\s*liệu/?đại\s*lượng\s*nào",
                    r"Nên\s*đổi\s*số\s*liệu",
                    r"Nên\s*đổi\s*đại\s*lượng",
                    r"Đổi\s*số\s*liệu",
                ]
            )
        ),
        "ideas": ideas,
        "raw": block,
    }
    if not any(
        [
            tips["original_find"],
            tips["suggest_find"],
            tips["suggest_change"],
            tips["ideas"],
        ]
    ):
        tips["raw"] = block
    return tips


def strip_similar_variant_section(text: Any) -> str:
    """Ẩn mục gợi ý biến thể ADMIN khỏi phần hiển thị học sinh."""
    raw = clean(text)
    if not raw:
        return ""
    out = re.sub(
        r"(?:^|\n)\s*5\.\s*GỢI\s*Ý\s*BIẾN\s*THỂ[\s\S]*$",
        "",
        raw,
        flags=re.I,
    )
    out = re.sub(
        r"(?:^|\n)\s*(?:GỢI\s*Ý\s*BIẾN\s*THỂ|ADMIN\s*[-–:]?\s*TRÁNH\s*TRÙNG)[\s\S]*$",
        "",
        out,
        flags=re.I,
    )
    return clean(out)


def collect_similar_peer_briefs(
    qs: List[Dict[str, Any]], index: int, limit: int = 5
) -> List[str]:
    """Lấy vài câu cùng dạng BT để AI tránh viết trùng."""
    if not (0 <= index < len(qs)):
        return []
    q = qs[index]
    q_dang = key_norm(q.get("DangBaiTap"))
    if not q_dang:
        return []
    briefs: List[str] = []
    for i, oq in enumerate(qs):
        if i == index:
            continue
        if key_norm(oq.get("DangBaiTap")) != q_dang:
            continue
        t = clean(oq.get("CauHoi", ""))
        if not t:
            continue
        briefs.append(t[:220])
        if len(briefs) >= limit:
            break
    return briefs


def split_inline_abcd_options(text: Any) -> Dict[str, str]:
    """Tách «A. … B. … C. … D. …» (cùng dòng hoặc dồn vào một ô) thành 4 phương án."""
    raw = clean(text)
    if not raw:
        return {}
    marker = re.compile(
        r"(?:^|[\s;|·•]|(?<=[\]\)\}]))(?:\*\*|__|\*)?\(?([ABCD])\)?(?:\*\*|__|\*)?\s*[\.\)\:：]\s*",
        re.I,
    )
    matches = list(marker.finditer(raw))
    if len(matches) < 2:
        # Thử lại kiểu bắt đầu chuỗi: A. ... B. ...
        marker2 = re.compile(
            r"(?:^|\s)(?:\*\*|__|\*)?\(?([ABCD])\)?(?:\*\*|__|\*)?\s*[\.\)\:：]\s*",
            re.I,
        )
        matches = list(marker2.finditer(raw))
    if len(matches) < 2:
        return {}
    out: Dict[str, str] = {}
    # Nếu chuỗi bắt đầu bằng nội dung rồi mới tới B./C. → phần đầu là A
    first_L = (matches[0].group(1) or "").upper()
    if first_L != "A" and matches[0].start() > 0:
        lead = clean(raw[: matches[0].start()])
        lead = re.sub(r"^\*+\s*|\s*\*+$", "", lead)
        if lead:
            out["A"] = lead
    for i, m in enumerate(matches):
        L = (m.group(1) or "").upper()
        if L not in "ABCD" or L in out:
            continue
        start = m.end()
        end = matches[i + 1].start() if i + 1 < len(matches) else len(raw)
        val = clean(raw[start:end])
        val = re.sub(r"^\*+\s*|\s*\*+$", "", val)
        val = re.sub(r"[\s;|·•,]+$", "", val)
        # Bỏ tiền tố lặp «A.» nếu AI nhân đôi
        val = re.sub(rf"^\s*{L}\s*[\.\)\:：]\s*", "", val, flags=re.I)
        if val:
            out[L] = val
    return out if len(out) >= 2 else {}


def merge_abcd_options_from_text(choice_src: Any, existing: Optional[Dict[str, str]] = None) -> Dict[str, str]:
    """Ưu tiên tách cùng dòng; nếu chỉ có ô A chứa cả B/C/D thì bung ra 4 cột."""
    opts: Dict[str, str] = dict(existing or {})
    src = clean(choice_src)
    inline = split_inline_abcd_options(src)
    if len(inline) >= 2:
        return inline
    # Line-based: mỗi dòng một phương án
    for m in re.finditer(
        r"(?im)^\s*(?:\*\*|__|\*)?\s*(?:\(?([ABCD])\)?|([abcd]))\s*(?:\*\*|__|\*)?\s*[\.\)\:：]\s*(?:\*\*|__)?\s*(.+?)\s*(?:\*\*|__)?\s*$",
        src,
    ):
        L = (m.group(1) or m.group(2) or "").upper()
        if L in "ABCD" and L not in opts:
            opts[L] = clean(re.sub(r"^\*+\s*|\s*\*+$", "", m.group(3) or ""))
    filled = [L for L in "ABCD" if clean(opts.get(L, ""))]
    if len(filled) == 1:
        only = filled[0]
        blob = clean(opts.get(only, ""))
        if re.search(r"(?i)(?:^|\s)[ABCD]\s*[\.\)\:：]", blob):
            split = split_inline_abcd_options(blob if re.match(rf"(?i)^\s*{only}\s*[\.\)\:：]", blob) else f"{only}. {blob}")
            if len(split) >= 2:
                return split
    elif len(filled) == 0 and src:
        split = split_inline_abcd_options(src)
        if len(split) >= 2:
            return split
    # A dồn cả chuỗi dù đã có marker B/C/D bên trong
    a = clean(opts.get("A", ""))
    if a and re.search(r"(?i)(?:^|\s)[BCD]\s*[\.\)\:：]", a) and not clean(opts.get("B", "")):
        split = split_inline_abcd_options(a if re.match(r"(?i)^\s*A\s*[\.\)\:：]", a) else f"A. {a}")
        if len(split) >= 2:
            return split
    return opts


def _extract_numbered_similar_section(text: str, num: int, titles: List[str]) -> str:
    """Lấy nội dung mục số — kể cả khi AI ghi đáp án ngay trên cùng dòng tiêu đề.

    Gemini/Claude thường bọc tiêu đề bằng **markdown** (vd: ``1. **CÂU HỎI MỚI** …``);
    regex phải chấp nhận ** / __ quanh tiêu đề, nếu không sẽ chỉ đổ cả khối vào CauHoi
    và bỏ trống A–D / Đáp án.
    """
    raw = clean(text)
    if not raw:
        return ""
    title_alt = "|".join(titles)
    # Cho phép: 1. CÂU HỎI MỚI | 1. **CÂU HỎI MỚI** | 1) __CÂU HỎI__
    md = r"(?:\*\*|__|\*)?"
    pat = (
        rf"(?:^|\n)\s*{num}[\.\)]\s*{md}\s*(?:{title_alt})\b\s*{md}"
        rf"[^\S\n]*[:：.\-—]?[^\S\n]*"
        rf"([^\n]*)"
        rf"(?:\n([\s\S]*?))?"
        rf"(?=\n\s*\d+[\.\)]\s*(?:\*\*|__|\*)?\s*[A-ZÀ-Ỹ]|\Z)"
    )
    m = re.search(pat, raw, flags=re.I)
    if not m:
        return ""
    same_line = clean(m.group(1) or "")
    # Bỏ phần chú thích tiêu đề kiểu "— kết quả cuối rõ ràng"
    if same_line and re.match(
        r"^(?:kết quả|nội dung|phù hợp|bắt buộc|4–8|4-8)\b", same_line, flags=re.I
    ):
        same_line = ""
    # Bỏ markdown còn sót trên cùng dòng tiêu đề
    same_line = re.sub(r"^\*+\s*", "", same_line).strip()
    rest = clean(m.group(2) or "")
    # Không nuốt nhầm tiêu đề mục kế (khi lookahead lệch)
    rest = re.sub(
        rf"(?im)^\s*{num + 1}[\.\)]\s*(?:\*\*|__|\*)?.*",
        "",
        rest,
    ).strip()
    parts = [p for p in (same_line, rest) if p]
    return clean("\n".join(parts))


def _fallback_labeled_similar_field(text: str, labels: List[str]) -> str:
    """Fallback khi AI không đánh số mục: 'Đáp án: B' / 'Lời giải: ...'."""
    raw = clean(text)
    if not raw:
        return ""
    label_alt = "|".join(labels)
    m = re.search(
        rf"(?im)^\s*(?:\*\*|__)?(?:{label_alt})(?:\*\*|__)?\s*[:：]\s*(.+)$",
        raw,
    )
    if not m:
        return ""
    start = m.start(1)
    first = clean(m.group(1))
    tail = raw[m.end() :]
    # Lấy thêm các dòng tiếp theo đến nhãn/mục kế
    more = []
    for ln in re.split(r"\n", tail):
        if re.match(
            r"^\s*(?:\d+\.\s+|(?:\*\*|__)?(?:Đáp án|ĐA|Lời giải|Câu hỏi|Các lựa chọn)\b)",
            ln,
            flags=re.I,
        ):
            break
        t = clean(ln)
        if t:
            more.append(t)
    parts = [first] + more
    return clean("\n".join(parts))


def parse_similar_ai_to_question_fields(
    text: Any, dang_hint: str = ""
) -> Dict[str, Any]:
    """Tách câu tương tự AI thành field form ADMIN (để Thêm/Lưu Sheet)."""
    full = clean(text)
    body = strip_similar_variant_section(full) or full
    if not body:
        return {}
    cauhoi = _extract_numbered_similar_section(
        body, 1, ["CÂU HỎI MỚI", "CÂU HỎI", "ĐỀ BÀI"]
    )
    choices = _extract_numbered_similar_section(
        body, 2, ["CÁC LỰA CHỌN", "LỰA CHỌN", "PHƯƠNG ÁN"]
    )
    dapan = _extract_numbered_similar_section(
        body, 3, ["ĐÁP ÁN", "ĐÁP ÁN ĐÚNG", "ĐA"]
    )
    loigiai = _extract_numbered_similar_section(
        body, 4, ["LỜI GIẢI", "HƯỚNG DẪN GIẢI", "GIẢI CHI TIẾT", "GIẢI"]
    )
    if not dapan:
        dapan = _fallback_labeled_similar_field(
            body, ["Đáp án đúng", "Đáp án", "ĐA", "Answer"]
        )
    if not loigiai:
        loigiai = _fallback_labeled_similar_field(
            body, ["Lời giải", "Hướng dẫn giải", "Giải", "Solution"]
        )
    opts: Dict[str, str] = merge_abcd_options_from_text(choices or body)
    if not cauhoi:
        # Fallback: lấy đoạn trước phương án A
        m0 = re.search(
            r"^([\s\S]*?)(?=\n\s*(?:\*\*|__|\*)?\s*[AÁ]\s*[\.\):]|\n\s*2[\.\)]\s*)",
            body,
            flags=re.I,
        )
        if m0:
            cauhoi = clean(
                re.sub(
                    r"^\s*1[\.\)]\s*(?:\*\*|__|\*)?\s*(?:CÂU HỎI MỚI|CÂU HỎI|ĐỀ BÀI)\s*(?:\*\*|__|\*)?[^\n]*\n?",
                    "",
                    m0.group(1),
                    flags=re.I,
                )
            )
    # Luôn gỡ tiêu đề mục còn dính trong CauHoi (Gemini hay để «1. **CÂU HỎI MỚI** …»)
    cauhoi = clean(
        re.sub(
            r"^\s*(?:\*\*|__|\*)?\s*1[\.\)]\s*(?:\*\*|__|\*)?\s*(?:CÂU HỎI MỚI|CÂU HỎI|ĐỀ BÀI)\s*(?:\*\*|__|\*)?\s*[:：.\-—]?\s*",
            "",
            cauhoi or "",
            flags=re.I,
        )
    )
    cauhoi = clean(re.sub(r"^\*+\s*|\s*\*+$", "", cauhoi or ""))
    da = clean(dapan)
    # Nếu nhầm dính cả mục 4 vào đáp án → tách lại
    if re.search(r"(?im)^\s*4[\.\)]\s*(?:\*\*|__|\*)?\s*LỜI\s*GIẢI", da) or (
        "LỜI GIẢI" in da.upper() and not loigiai
    ):
        bits = re.split(
            r"(?im)\n?\s*4[\.\)]\s*(?:\*\*|__|\*)?\s*LỜI\s*GIẢI\b[^\n]*\n?",
            da,
            maxsplit=1,
        )
        if len(bits) == 2:
            da = clean(bits[0])
            loigiai = clean(bits[1]) or loigiai
        else:
            bits2 = re.split(r"(?im)\n?\s*Lời giải\s*[:：]", da, maxsplit=1)
            if len(bits2) == 2:
                da = clean(bits2[0])
                loigiai = clean(bits2[1]) or loigiai
    da = re.sub(
        r"^(?:đáp án đúng|đáp án|đa|answer|\*+)\s*[:：]?\s*", "", da, flags=re.I
    ).strip()
    da = clean(re.sub(r"^\*+\s*|\s*\*+$", "", da))
    # TN: lấy chữ cái A–D nếu có
    m_letter = re.search(r"(?i)(?:đáp án|đúng|chọn|là)?\s*[:：]?\s*\b([ABCD])\b", da)
    if not m_letter:
        m_letter = re.search(r"\b([ABCD])\b", da.upper())
    dang = clean(dang_hint) or "Trắc nghiệm"
    if opts and m_letter and dang != "Đúng sai":
        da = m_letter.group(1).upper()
        dang = "Trắc nghiệm"
    elif re.search(r"[ĐđD]\s*[,/·]|[Ss]\s*[,/·]|Đúng|Sai", da):
        dang = "Đúng sai"
    elif not opts and da:
        dang = dang if dang in ("Trả lời ngắn", "Tự luận") else "Trả lời ngắn"
    elif opts:
        dang = "Trắc nghiệm" if dang != "Đúng sai" else dang
    loigiai = clean(loigiai)
    loigiai = re.sub(
        r"^(?:lời giải|hướng dẫn giải|giải)\s*[:：]\s*", "", loigiai, flags=re.I
    ).strip()
    if not cauhoi and not opts:
        return {}
    return {
        "CauHoi": cauhoi,
        "A": opts.get("A", ""),
        "B": opts.get("B", ""),
        "C": opts.get("C", ""),
        "D": opts.get("D", ""),
        "DapAn": da,
        "LoiGiai": loigiai,
        "Dang": dang,
        "SaiSo": "",
    }


def ai_similar_question_from_provider(
    q: Dict[str, Any], peer_briefs: Optional[List[str]] = None
) -> Tuple[str, int, str, str]:
    cfg = ai_runtime_config()
    openai_keys = load_ai_keys("OPENAI") if is_admin() else []
    gemini_keys = load_ai_keys("GEMINI")
    provider = clean(cfg.get("admin_provider" if is_admin() else "provider", cfg.get("provider", "GEMINI"))).upper()
    if not is_admin():
        provider = "GEMINI"
    if provider not in ("AUTO", "OPENAI", "GEMINI"):
        provider = "AUTO"
    last_error = ""
    max_tokens = max(AI_HINT_SIMILAR_MAX_OUTPUT_TOKENS, 1200 if is_admin() else AI_HINT_SIMILAR_MAX_OUTPUT_TOKENS)
    max_chars = max(AI_HINT_SIMILAR_MAX_CHARS, 4500 if is_admin() else AI_HINT_SIMILAR_MAX_CHARS)
    model_openai = clean(cfg.get("openai_model") or os.environ.get("OPENAI_HINT_MODEL", DEFAULT_OPENAI_HINT_MODEL)).strip() or DEFAULT_OPENAI_HINT_MODEL
    model_gemini = clean(cfg.get("gemini_model") or os.environ.get("GEMINI_HINT_MODEL", DEFAULT_GEMINI_HINT_MODEL)).strip() or DEFAULT_GEMINI_HINT_MODEL
    gemini_models = [model_gemini] + [m for m in GEMINI_HINT_MODEL_FALLBACKS if m != model_gemini]
    sys_prompt = (
        "Bạn là giáo viên Vật lý/Toán và biên tập ngân hàng đề. "
        "Tạo câu hỏi luyện tập tương tự câu gốc. "
        "Trả lời tiếng Việt, có đáp án, lời giải, và mục 5 gợi ý biến thể tránh trùng. "
        "LaTeX trong $...$ một dòng."
    )
    teacher_prompt = build_ai_similar_question_prompt(q, peer_briefs=peer_briefs)
    temp = 0.2

    def _postprocess(raw: str) -> str:
        return trim_ai_hint_text(sanitize_hint_math_text(clean(raw)), max_chars)

    def try_openai() -> Tuple[str, int, str, str]:
        nonlocal last_error
        body = {
            "model": model_openai,
            "messages": [
                {"role": "system", "content": sys_prompt},
                {"role": "user", "content": teacher_prompt},
            ],
            "temperature": temp,
            "max_tokens": max_tokens,
        }
        for idx, api_key in enumerate(openai_keys, start=1):
            req = urllib.request.Request(
                "https://api.openai.com/v1/chat/completions",
                data=json.dumps(body).encode("utf-8"),
                headers={"Content-Type": "application/json", "Authorization": f"Bearer {api_key}"},
                method="POST",
            )
            try:
                with urllib.request.urlopen(req, timeout=25) as resp:
                    data = json.loads(resp.read().decode("utf-8", errors="ignore"))
                txt = _postprocess(
                    (((data or {}).get("choices") or [{}])[0].get("message") or {}).get("content", "")
                )
                if txt:
                    print(f"[AI_SIMILAR][OPENAI] using key #{idx}")
                    return txt, idx, "OPENAI", ""
            except Exception as e:
                last_error = _http_error_message(e)
                if _is_quota_or_rate_error(last_error):
                    break
                continue
        return "", 0, "OPENAI", last_error

    def try_gemini() -> Tuple[str, int, str, str]:
        nonlocal last_error
        for idx, api_key in enumerate(gemini_keys, start=1):
            for gmodel in gemini_models:
                txt, finish, err = _gemini_hint_call(
                    api_key, gmodel, sys_prompt, teacher_prompt, max_tokens, temp, timeout=28
                )
                if err:
                    last_error = err
                    if _is_quota_or_rate_error(last_error):
                        print(f"[AI_SIMILAR][GEMINI] model={gmodel} key #{idx} quota — thử model/key tiếp")
                        continue
                    continue
                txt = _postprocess(txt)
                if txt:
                    print(f"[AI_SIMILAR][GEMINI] model={gmodel} key=#{idx} finish={finish}")
                    return txt, idx, "GEMINI", ""
        return "", 0, "GEMINI", last_error

    txt, idx, used_provider, err = "", 0, provider, ""
    if provider == "OPENAI":
        txt, idx, used_provider, err = try_openai()
    elif provider == "GEMINI":
        txt, idx, used_provider, err = try_gemini()
    else:
        if gemini_keys:
            txt, idx, used_provider, err = try_gemini()
            if not txt and is_admin():
                txt, idx, used_provider, err = try_openai()
        else:
            if is_admin():
                txt, idx, used_provider, err = try_openai()

    if txt:
        return txt, idx, used_provider, ""
    fallback = (
        f"⚠️ Chưa gọi được AI ({err or 'không phản hồi'}).\n\n"
        f"Thử lại sau hoặc kiểm tra key AI.\n\n"
        f"Câu gốc ({effective_dang(q)}): {clean(q.get('CauHoi', ''))[:200]}…"
    )
    return fallback, 0, "FALLBACK", err or last_error


def _is_quota_or_rate_error(msg: str) -> bool:
    m = clean(msg).lower()
    return any(
        x in m
        for x in [
            "quota",
            "rate limit",
            "rate_limit",
            "resource_exhausted",
            "exceeded your current",
            "429",
            "too many requests",
            "account is not active",
            "check your billing",
            "billing details",
            "payment required",
            "402",
            "account has been deactivated",
            "insufficient_quota",
            "billing",
        ]
    )


class AdminGeminiQuotaError(Exception):
    """ADMIN: hết quota Gemini — client hỏi có chuyển GPT không."""

    def __init__(self, message: str = "", *, openai_available: bool = False):
        super().__init__(
            message or "Hết quota GEMINI. Đợi quota hồi hoặc chọn chạy GPT để tiếp tục."
        )
        self.openai_available = bool(openai_available)


def admin_ai_resolve_force(force_provider: Any) -> str:
    p = clean(force_provider).upper()
    if p in ("OPENAI", "GPT", "CHATGPT"):
        return "OPENAI"
    if p in ("GEMINI", "GOOGLE"):
        return "GEMINI"
    if p in ("ANTHROPIC", "CLAUDE"):
        return "ANTHROPIC"
    if p in ("AUTO", ""):
        # Chuỗi fallback Anthropic → Gemini → GPT (không ép OPENAI khi billing lỗi)
        return ""
    return "GEMINI"


def admin_ai_quota_json(err: AdminGeminiQuotaError):
    return jsonify(
        {
            "gemini_quota_exhausted": True,
            "openai_available": err.openai_available,
            "error": str(err),
        }
    ), 429


def _admin_anthropic_keys(extra_key: str = "") -> List[str]:
    """Claude của ADMIN: chỉ ANTHROPIC_API_KEY trên ENV. Bỏ qua key dán từ trình duyệt."""
    if not is_admin():
        return []
    return list(load_ai_keys_from_env("ANTHROPIC"))


def _debate_anthropic_keys(extra_key: str = "") -> List[str]:
    """Phản biện: cột Claude chỉ ADMIN, chỉ key ENV."""
    return _admin_anthropic_keys()


def _user_gemini_keys(extra_key: str = "") -> List[str]:
    """Gemini: ưu tiên key học sinh gửi/tự nạp, rồi mới tới pool lớp."""
    keys = list(load_ai_keys("GEMINI"))
    extras: List[str] = []
    raw = clean(extra_key)
    if raw:
        parsed, _, _ = parse_api_keys_2026(raw)
        extras = [k for k in parsed if _is_gemini_api_key(k)]
        if not extras:
            ek = clean_ai_key_2026(raw)
            if ek and _is_gemini_api_key(ek):
                extras = [ek]
    for ek in reversed(extras):
        keys = [k for k in keys if k != ek]
        keys = [ek] + keys
    return keys[:MAX_AI_KEYS_PER_PROVIDER]


def admin_ai_require_provider_keys(force_provider: str, extra_anthropic_key: str = "") -> None:
    """Kiểm tra sớm trước khi gọi AI — tránh treo request rồi Failed to fetch."""
    fp = admin_ai_resolve_force(force_provider)
    if fp == "ANTHROPIC":
        if not _admin_anthropic_keys(extra_anthropic_key):
            raise RuntimeError(
                "Chọn Claude nhưng chưa có ANTHROPIC_API_KEY trên server (ENV). "
                "Chỉ ADMIN được dùng Claude từ biến môi trường."
            )
        return
    if fp == "OPENAI":
        if not load_ai_keys("OPENAI"):
            raise RuntimeError(
                "Chọn GPT nhưng server chưa có OPENAI_API_KEY. Thêm vào file .env rồi restart app."
            )
        return
    if fp == "GEMINI":
        if not load_ai_keys("GEMINI"):
            raise RuntimeError(
                "Chọn Gemini nhưng chưa có GEMINI_API_KEY. Nạp key tại 🔑 Key AI hoặc .env."
            )


def admin_ai_body_params(body: Optional[Dict[str, Any]] = None) -> Tuple[str, bool]:
    body = body or {}
    return clean(body.get("admin_ai_provider", "")).upper(), bool(
        body.get("admin_ai_allow_gpt_fallback")
    )


def admin_ai_call_text(
    sys_prompt: str,
    user_prompt: str,
    *,
    max_tokens: int = 2200,
    temp: float = 0.02,
    timeout: int = 55,
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
    image_b64: str = "",
    image_mime: str = "",
    extra_anthropic_key: str = "",
) -> Tuple[str, str, str, int]:
    """ADMIN: Anthropic → Gemini → GPT (theo thứ tự ưu tiên / quota). Trả (text, provider, model, key_index)."""
    cfg = ai_runtime_config()
    openai_keys = load_ai_keys("OPENAI") if is_admin() else []
    gemini_keys = load_ai_keys("GEMINI")
    anthropic_keys = load_ai_keys("ANTHROPIC") if is_admin() else []
    gemini_saw_quota = False
    last_error = ""
    model_openai = (
        clean(cfg.get("openai_admin_model") or cfg.get("openai_model") or DEFAULT_OPENAI_ADMIN_MODEL)
        or DEFAULT_OPENAI_ADMIN_MODEL
    )
    if image_b64:
        model_openai = clean(os.environ.get("OPENAI_VISION_MODEL", DEFAULT_OPENAI_VISION_MODEL)) or model_openai
    model_gemini = (
        clean(cfg.get("gemini_model") or os.environ.get("GEMINI_ADMIN_MODEL", DEFAULT_GEMINI_ADMIN_MODEL))
        or DEFAULT_GEMINI_ADMIN_MODEL
    )
    if image_b64:
        model_gemini = clean(os.environ.get("GEMINI_VISION_MODEL", DEFAULT_GEMINI_VISION_MODEL)) or model_gemini
    model_anthropic = (
        clean(os.environ.get("ANTHROPIC_ADMIN_MODEL", DEFAULT_ANTHROPIC_ADMIN_MODEL))
        or DEFAULT_ANTHROPIC_ADMIN_MODEL
    )
    if image_b64:
        model_anthropic = clean(os.environ.get("ANTHROPIC_VISION_MODEL", DEFAULT_ANTHROPIC_VISION_MODEL)) or model_anthropic

    def try_anthropic() -> Tuple[str, str, str, int]:
        nonlocal last_error
        for idx, api_key in enumerate(anthropic_keys, start=1):
            txt, finish, err = _anthropic_chat_call(
                api_key,
                model_anthropic,
                sys_prompt,
                user_prompt,
                max_tokens,
                temp,
                timeout=timeout,
                image_b64=image_b64,
                image_mime=image_mime,
            )
            if txt:
                return txt, "ANTHROPIC", model_anthropic, idx
            last_error = err or finish or last_error
        return "", "ANTHROPIC", model_anthropic, 0

    def try_openai() -> Tuple[str, str, str, int]:
        nonlocal last_error
        for idx, api_key in enumerate(openai_keys, start=1):
            txt, finish, err = _openai_chat_call(
                api_key,
                model_openai,
                sys_prompt,
                user_prompt,
                max_tokens,
                temp,
                timeout=timeout,
                image_b64=image_b64,
                image_mime=image_mime,
            )
            if txt:
                return txt, "OPENAI", model_openai, idx
            last_error = err or finish or last_error
        return "", "OPENAI", model_openai, 0

    def try_gemini() -> Tuple[str, str, str, int]:
        nonlocal last_error, gemini_saw_quota
        models = [model_gemini] + [m for m in GEMINI_HINT_MODEL_FALLBACKS if m != model_gemini]
        for idx, api_key in enumerate(gemini_keys, start=1):
            for gmodel in models:
                txt, finish, err = _gemini_hint_call(
                    api_key,
                    gmodel,
                    sys_prompt,
                    user_prompt,
                    max_tokens,
                    temp,
                    timeout=timeout,
                    image_b64=image_b64,
                    image_mime=image_mime,
                )
                if txt:
                    return txt, "GEMINI", gmodel, idx
                last_error = err or finish or last_error
                if _is_quota_or_rate_error(last_error):
                    gemini_saw_quota = True
        return "", "GEMINI", model_gemini, 0

    def _chain(*names: str) -> Tuple[str, str, str, int]:
        for name in names:
            if name == "ANTHROPIC" and anthropic_keys:
                txt, prov, model, ki = try_anthropic()
                if txt:
                    return txt, prov, model, ki
            elif name == "GEMINI" and gemini_keys:
                txt, prov, model, ki = try_gemini()
                if txt:
                    return txt, prov, model, ki
            elif name == "OPENAI" and openai_keys:
                txt, prov, model, ki = try_openai()
                if txt:
                    return txt, prov, model, ki
        return "", "", "", 0

    fp = admin_ai_resolve_force(force_provider)
    if fp == "ANTHROPIC":
        txt, prov, model, ki = _chain("ANTHROPIC", "GEMINI", "OPENAI")
        if txt:
            return txt, prov, model, ki
        raise RuntimeError(last_error or "ANTHROPIC không phản hồi.")
    if fp == "OPENAI":
        txt, prov, model, ki = _chain("OPENAI", "GEMINI", "ANTHROPIC")
        if txt:
            return txt, prov, model, ki
        raise RuntimeError(last_error or "OPENAI không phản hồi.")
    if fp == "GEMINI":
        txt, prov, model, ki = _chain("GEMINI", "ANTHROPIC", "OPENAI")
        if txt:
            return txt, prov, model, ki
        if gemini_saw_quota and openai_keys and not allow_gpt_fallback:
            raise AdminGeminiQuotaError(last_error, openai_available=True)
        raise RuntimeError(last_error or "GEMINI không phản hồi.")
    # Mặc định (AUTO): Anthropic → Gemini → GPT (nếu allow_gpt_fallback hoặc hết lựa chọn khác)
    txt, prov, model, ki = _chain("ANTHROPIC", "GEMINI")
    if txt:
        return txt, prov, model, ki
    if gemini_saw_quota and openai_keys and not allow_gpt_fallback:
        raise AdminGeminiQuotaError(last_error, openai_available=True)
    if openai_keys and (allow_gpt_fallback or (not anthropic_keys and not gemini_keys)):
        txt, prov, model, ki = try_openai()
        if txt:
            return txt, prov, model, ki
    raise RuntimeError(last_error or "AI không phản hồi.")


def admin_ai_api_guard(fn):
    """Bọc API ADMIN — trả JSON quota thay vì 500."""
    try:
        return fn()
    except AdminGeminiQuotaError as e:
        return admin_ai_quota_json(e)


def _http_error_message(e: Exception) -> str:
    try:
        body = ""
        if hasattr(e, "read"):
            body = e.read().decode("utf-8", errors="ignore")
        elif getattr(e, "fp", None):
            body = e.fp.read().decode("utf-8", errors="ignore")  # type: ignore
        if body:
            try:
                j = json.loads(body)
                msg = clean(((j or {}).get("error") or {}).get("message") or "")
                if msg:
                    return msg[:220]
            except Exception:
                log_swallow("_http_error_message:12055")
                pass
            return clean(body)[:220]
    except Exception:
        log_swallow("_http_error_message:12058")
        pass
    return clean(str(e))[:220]


def _gemini_collect_response_text(resp_parts: Any) -> str:
    """Gộp mọi phần text thật từ Gemini (bỏ thought/ảnh) — tránh chỉ đọc parts[0]."""
    chunks: List[str] = []
    if not isinstance(resp_parts, list):
        return ""
    for p in resp_parts:
        if not isinstance(p, dict):
            continue
        if p.get("thought") is True:
            continue
        if p.get("inlineData") or p.get("inline_data"):
            continue
        tx = clean(p.get("text", ""))
        if tx:
            chunks.append(tx)
    return "\n".join(chunks).strip()


def _gemini_hint_call(
    api_key: str,
    gmodel: str,
    sys_prompt: str,
    user_prompt: str,
    max_tokens: int,
    temp: float,
    timeout: int = 22,
    image_b64: str = "",
    image_mime: str = "",
    thinking_budget: Optional[int] = None,
) -> Tuple[str, str, str]:
    """Gọi Gemini một lần. Trả về (text, finish_reason, error)."""
    parts: List[Dict[str, Any]] = [{"text": sys_prompt}, {"text": user_prompt}]
    if image_b64 and image_mime:
        parts.append({"inline_data": {"mime_type": image_mime, "data": image_b64}})
    gen_cfg: Dict[str, Any] = {"temperature": temp, "maxOutputTokens": max_tokens}
    if thinking_budget is not None:
        gen_cfg["thinkingConfig"] = {"thinkingBudget": int(thinking_budget)}
    body = {
        "contents": [{"parts": parts}],
        "generationConfig": gen_cfg,
    }
    url, headers = _gemini_request_target(api_key, gmodel)
    req = urllib.request.Request(
        url,
        data=json.dumps(body).encode("utf-8"),
        headers=headers,
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            data = json.loads(resp.read().decode("utf-8", errors="ignore"))
        cands = (data or {}).get("candidates") or []
        cand0 = cands[0] if cands else {}
        resp_parts = ((cand0.get("content") or {}).get("parts") or [])
        txt = _gemini_collect_response_text(resp_parts)
        finish = clean(cand0.get("finishReason", ""))
        return txt, finish, ""
    except Exception as e:
        return "", "", _http_error_message(e)


def _openai_chat_call(
    api_key: str,
    model: str,
    sys_prompt: str,
    user_prompt: str,
    max_tokens: int,
    temp: float,
    timeout: int = 45,
    image_b64: str = "",
    image_mime: str = "",
) -> Tuple[str, str, str]:
    """Gọi OpenAI chat một lần. Trả về (text, finish_reason, error)."""
    user_content: Any = user_prompt
    if image_b64 and image_mime:
        user_content = [
            {"type": "text", "text": user_prompt},
            {
                "type": "image_url",
                "image_url": {
                    "url": f"data:{image_mime};base64,{image_b64}",
                    "detail": "high",
                },
            },
        ]
    body = {
        "model": model,
        "messages": [
            {"role": "system", "content": sys_prompt},
            {"role": "user", "content": user_content},
        ],
        "temperature": temp,
        "max_tokens": max_tokens,
    }
    req = urllib.request.Request(
        "https://api.openai.com/v1/chat/completions",
        data=json.dumps(body).encode("utf-8"),
        headers={"Content-Type": "application/json", "Authorization": f"Bearer {api_key}"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            data = json.loads(resp.read().decode("utf-8", errors="ignore"))
        choice = ((data or {}).get("choices") or [{}])[0]
        txt = clean(((choice.get("message") or {}).get("content") or ""))
        finish = clean(choice.get("finish_reason") or "")
        return txt, finish, ""
    except Exception as e:
        return "", "", _http_error_message(e)


def _anthropic_chat_call(
    api_key: str,
    model: str,
    sys_prompt: str,
    user_prompt: str,
    max_tokens: int,
    temp: float,
    timeout: int = 45,
    image_b64: str = "",
    image_mime: str = "",
) -> Tuple[str, str, str]:
    """Gọi Anthropic Claude một lần. Trả về (text, finish_reason, error)."""
    user_content: Any
    if image_b64 and image_mime:
        user_content = [
            {"type": "image", "source": {"type": "base64", "media_type": image_mime, "data": image_b64}},
            {"type": "text", "text": user_prompt},
        ]
    else:
        user_content = user_prompt
    body = {
        "model": model,
        "max_tokens": max_tokens,
        "temperature": temp,
        "system": sys_prompt,
        "messages": [{"role": "user", "content": user_content}],
    }
    req = urllib.request.Request(
        "https://api.anthropic.com/v1/messages",
        data=json.dumps(body).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "x-api-key": api_key,
            "anthropic-version": "2023-06-01",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            data = json.loads(resp.read().decode("utf-8", errors="ignore"))
        content_blocks = (data or {}).get("content") or []
        parts = []
        for block in content_blocks:
            if isinstance(block, dict) and block.get("type") == "text":
                t = clean(block.get("text", ""))
                if t:
                    parts.append(t)
        txt = "\n".join(parts)
        finish = clean((data or {}).get("stop_reason") or "")
        return txt, finish, ""
    except Exception as e:
        return "", "", _http_error_message(e)


def question_repair_target_dang(q: Dict[str, Any], target_dang: Any = "") -> str:
    """Chọn dạng câu mục tiêu khi AI khôi phục câu thiếu."""
    td = norm_dang(target_dang) if clean(target_dang) else ""
    if td in DANG_GROUP_ORDER:
        return td
    # Chống lỗi cũ: nếu đáp án là A/B/C/D thì luôn ưu tiên Trắc nghiệm.
    if is_mcq_letter_answer(q.get("DapAn")) and has_tf_statements(q):
        return "Trắc nghiệm"
    return effective_dang(q)


def question_missing_report(q: Dict[str, Any], target_dang: Any = "") -> Dict[str, Any]:
    """Báo các phần thiếu trước khi AI khôi phục."""
    dang = question_repair_target_dang(q, target_dang)
    required = ["CauHoi", "DapAn", "LoiGiai"]
    if dang in ("Trắc nghiệm", "Đúng sai"):
        required += ["A", "B", "C", "D"]
    missing = [f for f in required if not clean(q.get(f, ""))]
    warnings: List[str] = []
    if dang == "Trắc nghiệm":
        if clean(q.get("DapAn")) and not is_mcq_letter_answer(q.get("DapAn")):
            warnings.append("Đáp án hiện tại không phải một chữ A/B/C/D.")
        if looks_like_dungsai_answer(q.get("DapAn")):
            warnings.append("Đáp án hiện tại giống Đúng/Sai nhưng dạng mục tiêu là Trắc nghiệm.")
    elif dang == "Đúng sai":
        vals = parse_tf_values(q.get("DapAn"))
        if sum(1 for v in vals if v in ("Đ", "S")) < 2:
            warnings.append("Đáp án Đ/S hiện tại chưa đủ tối thiểu 2 ý.")
    elif dang == "Trả lời ngắn":
        if any(clean(q.get(L, "")) for L in "ABCD"):
            warnings.append("Trả lời ngắn không cần A/B/C/D; AI sẽ để trống phương án nếu khôi phục.")
    return {"dang": dang, "missing": missing, "warnings": warnings}


def _strip_ai_json_fence(txt: Any) -> str:
    txt = clean(txt)
    txt = re.sub(r"^```(?:json)?", "", txt, flags=re.I).strip()
    txt = re.sub(r"```$", "", txt).strip()
    return txt


def _repair_latex_json_escapes(s: str) -> str:
    """Sửa backslash LaTeX trong chuỗi JSON (\\omega, \\frac…) để json.loads đọc được."""
    out: List[str] = []
    in_str = False
    esc = False
    i = 0
    while i < len(s):
        ch = s[i]
        if not in_str:
            out.append(ch)
            if ch == '"':
                in_str = True
                esc = False
            i += 1
            continue
        if esc:
            out.append(ch)
            esc = False
            i += 1
            continue
        if ch == "\\":
            nxt = s[i + 1] if i + 1 < len(s) else ""
            if nxt in '"\\/bfnrtu':
                out.append(ch)
                esc = True
            else:
                out.append("\\\\")
            i += 1
            continue
        if ch == '"':
            in_str = False
        out.append(ch)
        i += 1
    return "".join(out)


def _json_loads_ai_lenient(raw: str) -> Any:
    """Đọc JSON từ phản hồi AI — thử nhiều cách (object, array, sửa LaTeX)."""
    raw = _strip_ai_json_fence(raw)
    if not raw:
        return None
    chunks: List[str] = [raw]
    a, b = raw.find("{"), raw.rfind("}")
    if a >= 0 and b > a:
        chunks.append(raw[a: b + 1])
    a2, b2 = raw.find("["), raw.rfind("]")
    if a2 >= 0 and b2 > a2:
        chunks.append(raw[a2: b2 + 1])
    seen: set = set()
    for chunk in chunks:
        if not chunk or chunk in seen:
            continue
        seen.add(chunk)
        for variant in (chunk, _repair_latex_json_escapes(chunk)):
            try:
                return json.loads(variant)
            except Exception:
                log_swallow("_json_loads_ai_lenient:12323")
                pass
    return None


def _extract_ai_json_object(txt: Any) -> Dict[str, Any]:
    """Tách JSON object từ phản hồi AI."""
    parsed = _json_loads_ai_lenient(str(txt or ""))
    if isinstance(parsed, dict):
        return parsed
    if isinstance(parsed, list):
        return {"questions": [x for x in parsed if isinstance(x, dict)]}
    return {}



PHYSICS_COMPETENCY_CLASSIFIER_PROMPT = r"""
Bạn là chuyên gia xây dựng và phân loại câu hỏi đánh giá năng lực đặc thù môn Vật lí trong chương trình giáo dục phổ thông Việt Nam.

NHIỆM VỤ
Phân tích câu hỏi Vật lí được cung cấp và xác định năng lực vật lí chủ đạo mà học sinh phải sử dụng để trả lời câu hỏi.

Chỉ được lựa chọn một trong sáu nhóm sau:

1. NLVL01 – Nhận biết và trình bày kiến thức vật lí
1.1. Nhận biết, gọi tên, nêu khái niệm, hiện tượng, đại lượng, định luật hoặc quy tắc vật lí.
1.2. Trình bày kiến thức bằng lời, công thức, hình vẽ, sơ đồ hoặc biểu đồ.
1.3. Tìm từ khóa, sử dụng thuật ngữ và kết nối thông tin vật lí.

2. NLVL02 – Phân tích, giải thích và phản biện vật lí
2.1. So sánh, lựa chọn, phân loại hoặc phân tích hiện tượng và quá trình vật lí.
2.2. Giải thích nguyên nhân, cơ chế hoặc mối quan hệ giữa các đại lượng.
2.3. Phát hiện điểm sai, sửa lỗi trong nhận định, lập luận, lời giải hoặc kết luận.

3. NLVL03 – Đề xuất vấn đề và xây dựng giả thuyết
3.1. Nhận ra và đặt câu hỏi liên quan đến một hiện tượng vật lí.
3.2. Xác định vấn đề cần tìm hiểu.
3.3. Đưa ra phán đoán, dự đoán hoặc giả thuyết có thể kiểm chứng.

4. NLVL04 – Lập kế hoạch và thực hiện tìm hiểu vật lí
4.1. Xác định mục tiêu, dụng cụ, biến độc lập, biến phụ thuộc và biến kiểm soát.
4.2. Lựa chọn phương pháp quan sát, đo đạc, thí nghiệm, điều tra hoặc tra cứu.
4.3. Sắp xếp các bước tiến hành.
4.4. Thực hiện phép đo, thu thập và lưu giữ dữ liệu.

5. NLVL05 – Xử lí dữ liệu, kết luận và báo cáo
5.1. Đọc và xử lí bảng số liệu, đồ thị hoặc kết quả thực nghiệm.
5.2. Tính giá trị trung bình, sai số hoặc các đại lượng cần thiết.
5.3. So sánh kết quả với giả thuyết.
5.4. Rút ra kết luận từ bằng chứng.
5.5. Trình bày báo cáo, thảo luận, phản biện hoặc bảo vệ kết quả tìm hiểu.

6. NLVL06 – Vận dụng vật lí vào thực tiễn và đề xuất giải pháp
6.1. Vận dụng kiến thức vật lí để giải thích hoặc chứng minh một vấn đề thực tiễn.
6.2. Đánh giá tác động, ưu điểm, hạn chế hoặc mức độ an toàn của một giải pháp.
6.3. Thiết kế mô hình, sản phẩm, phương án hoặc quy trình.
6.4. Ra quyết định và đề xuất giải pháp liên quan đến kỹ thuật, đời sống, môi trường hoặc phát triển bền vững.
6.5. Nhận biết sự liên hệ giữa kiến thức vật lí với nghề nghiệp.

NGUYÊN TẮC PHÂN LOẠI
1. Phân loại theo hoạt động tư duy chủ đạo mà học sinh phải thực hiện, không chỉ dựa vào động từ xuất hiện trong đề.
2. Không đồng nhất năng lực vật lí với mức độ NB, TH, VD, VDC.
3. Không đồng nhất năng lực vật lí với loại câu hỏi Trắc nghiệm, Đúng/Sai, Trả lời ngắn hoặc Tự luận.
4. Một câu hỏi có thể liên quan đến nhiều năng lực nhưng chỉ chọn một năng lực chủ đạo.
5. Chỉ chọn NLVL03 khi học sinh thực sự phải đặt câu hỏi, dự đoán hoặc xây dựng giả thuyết.
6. Chỉ chọn NLVL04 khi học sinh phải lựa chọn dụng cụ, biến số, quy trình hoặc phương pháp thực hiện.
7. Chỉ chọn NLVL05 khi dữ liệu, bảng, đồ thị hoặc kết quả thực nghiệm là căn cứ chính để rút ra kết luận.
8. Chỉ chọn NLVL06 khi câu hỏi có bối cảnh thực tiễn và yêu cầu vận dụng, đánh giá, thiết kế, ra quyết định hoặc đề xuất giải pháp.
9. Một bài toán tính toán thông thường không tự động được xếp vào NLVL06. Nếu chỉ áp dụng trực tiếp công thức để tính đại lượng thì thường thuộc NLVL01; nếu phải phân tích quan hệ hoặc giải thích kết quả thì có thể thuộc NLVL02.
10. Không suy diễn thêm nội dung không có trong câu hỏi.

KẾT QUẢ PHẢI TRẢ VỀ ĐÚNG JSON SAU
{"ma_nang_luc":"NLVL01","ten_nang_luc":"Nhận biết và trình bày kiến thức vật lí","chi_bao_phu_hop":["1.1"],"bang_chung":"Mô tả ngắn hoạt động học sinh phải thực hiện","do_tin_cay":0.95,"can_kiem_tra_lai":false}

QUY ĐỊNH ĐẦU RA
Chỉ trả về một đối tượng JSON hợp lệ. Không dùng Markdown. Không viết giải thích ngoài JSON. do_tin_cay là số từ 0 đến 1. Nếu câu hỏi thiếu nội dung hoặc không đủ căn cứ phân loại, đặt can_kiem_tra_lai là true.
""".strip()


def classify_physics_competency_with_admin_gpt(
    q: Dict[str, Any],
    *,
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
) -> Dict[str, Any]:
    """ADMIN phân loại NLVL01–NLVL06; Gemini trước."""
    cfg = ai_runtime_config()
    model = clean(cfg.get("openai_admin_model") or DEFAULT_OPENAI_ADMIN_MODEL) or DEFAULT_OPENAI_ADMIN_MODEL
    payload = {
        "Mon": clean(q.get("Mon", "")),
        "Lop": clean(q.get("Lop", "")),
        "Chuong": clean(q.get("Chuong", "")),
        "BaiHoc": clean(q.get("BaiHoc", "")),
        "DangBaiTap": clean(q.get("DangBaiTap", "")),
        "Dang": effective_dang(q),
        "MucDo": clean(q.get("MucDo", "")),
        "CauHoi": clean(q.get("CauHoi", ""))[:3500],
        "A": clean(q.get("A", ""))[:900],
        "B": clean(q.get("B", ""))[:900],
        "C": clean(q.get("C", ""))[:900],
        "D": clean(q.get("D", ""))[:900],
        "DapAn": clean(q.get("DapAn", ""))[:500],
        "LoiGiai": clean(q.get("LoiGiai", ""))[:2200],
    }
    if not payload["CauHoi"]:
        return {
            "ma_nang_luc": "",
            "ten_nang_luc": "",
            "chi_bao_phu_hop": [],
            "bang_chung": "Chưa có nội dung câu hỏi Vật lí để phân loại.",
            "do_tin_cay": 0.0,
            "can_kiem_tra_lai": True,
            "ai_provider": "OPENAI",
            "ai_model": model,
        }
    user_prompt = PHYSICS_COMPETENCY_CLASSIFIER_PROMPT + "\n\nCÂU HỎI CẦN PHÂN LOẠI:\n" + json.dumps(payload, ensure_ascii=False, indent=2)
    txt, prov, model_used, key_index = admin_ai_call_text(
        "Chỉ trả một JSON object hợp lệ, không markdown.",
        user_prompt,
        max_tokens=900,
        temp=0.01,
        timeout=55,
        force_provider=force_provider,
        allow_gpt_fallback=allow_gpt_fallback,
    )
    obj = _extract_ai_json_object(txt)
    if not obj:
        raise RuntimeError("AI trả JSON không hợp lệ.")
    obj["key_index"] = key_index
    code = norm_nang_luc_vat_ly(obj.get("ma_nang_luc") or obj.get("NangLucVatLy"))
    if not code:
        raise RuntimeError("GPT trả mã năng lực không thuộc NLVL01–NLVL06.")
    indicators = obj.get("chi_bao_phu_hop")
    if isinstance(indicators, str):
        indicators = [x.strip() for x in re.split(r"[,;|]+", indicators) if x.strip()]
    if not isinstance(indicators, list):
        indicators = []
    try:
        confidence = max(0.0, min(1.0, float(obj.get("do_tin_cay", 0))))
    except Exception:
        log_swallow("classify_physics_competency_with_admin_gpt:12462")
        confidence = 0.0
    recheck_raw = obj.get("can_kiem_tra_lai", False)
    recheck = recheck_raw if isinstance(recheck_raw, bool) else key_norm(recheck_raw) in {"true", "1", "co", "yes"}
    return {
        "ma_nang_luc": code,
        "ten_nang_luc": NANG_LUC_VAT_LY[code],
        "chi_bao_phu_hop": [clean(x) for x in indicators if clean(x)][:8],
        "bang_chung": clean(obj.get("bang_chung", ""))[:500],
        "do_tin_cay": round(confidence, 2),
        "can_kiem_tra_lai": bool(recheck),
        "ai_provider": prov,
        "ai_model": model_used,
        "key_index": int(obj.get("key_index") or key_index),
    }




def classify_physics_competency_bulk_with_admin_gpt(
    qs: List[Dict[str, Any]],
    *,
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
) -> Dict[str, Any]:
    """Phân loại lô câu — Gemini trước."""
    cfg = ai_runtime_config()
    model = clean(cfg.get("openai_admin_model") or DEFAULT_OPENAI_ADMIN_MODEL) or DEFAULT_OPENAI_ADMIN_MODEL
    payload_items: List[Dict[str, Any]] = []
    for i, q in enumerate(qs):
        payload_items.append({
            "index": int(q.get("_bulk_index", i)),
            "Mon": clean(q.get("Mon", "")),
            "Lop": clean(q.get("Lop", "")),
            "Chuong": clean(q.get("Chuong", "")),
            "BaiHoc": clean(q.get("BaiHoc", "")),
            "DangBaiTap": clean(q.get("DangBaiTap", "")),
            "Dang": effective_dang(q),
            "MucDo": clean(q.get("MucDo", "")),
            "CauHoi": clean(q.get("CauHoi", ""))[:2600],
            "A": clean(q.get("A", ""))[:650],
            "B": clean(q.get("B", ""))[:650],
            "C": clean(q.get("C", ""))[:650],
            "D": clean(q.get("D", ""))[:650],
            "DapAn": clean(q.get("DapAn", ""))[:350],
            "LoiGiai": clean(q.get("LoiGiai", ""))[:1400],
        })
    bulk_instruction = r"""
TÁC VỤ HÀNG LOẠT
Phân loại RIÊNG từng phần tử trong danh sách CÂU HỎI. Giữ nguyên index đầu vào.
Chỉ trả về đúng một JSON object theo cấu trúc:
{"items":[{"index":0,"ma_nang_luc":"NLVL01","ten_nang_luc":"Nhận biết và trình bày kiến thức vật lí","chi_bao_phu_hop":["1.1"],"bang_chung":"Hoạt động tư duy chủ đạo...","do_tin_cay":0.95,"can_kiem_tra_lai":false}]}
Không dùng Markdown. Không bỏ sót phần tử. Mỗi câu chỉ chọn một năng lực chủ đạo.
""".strip()
    user_prompt = PHYSICS_COMPETENCY_CLASSIFIER_PROMPT + "\n\n" + bulk_instruction + "\n\nCÂU HỎI:\n" + json.dumps(payload_items, ensure_ascii=False, indent=2)
    txt, prov, model_used, key_index = admin_ai_call_text(
        "Chỉ trả một JSON object hợp lệ có khóa items, không markdown.",
        user_prompt,
        max_tokens=3600,
        temp=0.01,
        timeout=75,
        force_provider=force_provider,
        allow_gpt_fallback=allow_gpt_fallback,
    )
    obj = _extract_ai_json_object(txt)
    raw_items = obj.get("items") if isinstance(obj, dict) else None
    if not isinstance(raw_items, list):
        raise RuntimeError("AI trả JSON hàng loạt không hợp lệ.")
    out: List[Dict[str, Any]] = []
    seen = set()
    for raw in raw_items:
        if not isinstance(raw, dict):
            continue
        try:
            index = int(raw.get("index"))
        except Exception:
            log_swallow("classify_physics_competency_bulk_with_admin_gpt:12537")
            continue
        if index in seen:
            continue
        seen.add(index)
        code = norm_nang_luc_vat_ly(raw.get("ma_nang_luc") or raw.get("NangLucVatLy"))
        indicators = raw.get("chi_bao_phu_hop")
        if isinstance(indicators, str):
            indicators = [x.strip() for x in re.split(r"[,;|]+", indicators) if x.strip()]
        if not isinstance(indicators, list):
            indicators = []
        try:
            confidence = max(0.0, min(1.0, float(raw.get("do_tin_cay", 0))))
        except Exception:
            log_swallow("classify_physics_competency_bulk_with_admin_gpt:12550")
            confidence = 0.0
        recheck_raw = raw.get("can_kiem_tra_lai", False)
        recheck = recheck_raw if isinstance(recheck_raw, bool) else key_norm(recheck_raw) in {"true", "1", "co", "yes"}
        out.append({
            "index": index,
            "ma_nang_luc": code,
            "NangLucVatLy": code,
            "ten_nang_luc": NANG_LUC_VAT_LY.get(code, ""),
            "chi_bao_phu_hop": [clean(x) for x in indicators if clean(x)][:8],
            "bang_chung": clean(raw.get("bang_chung", ""))[:500],
            "do_tin_cay": round(confidence, 2),
            "can_kiem_tra_lai": bool(recheck or not code),
        })
    return {
        "items": out,
        "ai_provider": prov,
        "ai_model": model_used,
        "key_index": key_index,
    }

def normalize_ai_generation_spec(raw: Dict[str, Any]) -> Dict[str, Any]:
    """Chuẩn hóa yêu cầu sinh câu; mỗi request chỉ sinh một batch nhỏ để tránh timeout."""
    raw = raw or {}
    try:
        count = int(raw.get("count") or raw.get("batch_count") or 1)
    except Exception:
        log_swallow("normalize_ai_generation_spec:12576")
        count = 1
    count = max(1, min(count, AI_GENERATE_BATCH_MAX))
    try:
        offset = max(0, int(raw.get("offset") or 0))
    except Exception:
        log_swallow("normalize_ai_generation_spec:12581")
        offset = 0

    dang = norm_dang(raw.get("Dang", raw.get("dang", "")))
    mucdo = clean(raw.get("MucDo", raw.get("mucdo", raw.get("level", "")))).upper()
    if mucdo not in ("NB", "TH", "VD", "VDC"):
        raise RuntimeError("Mức độ phải là NB, TH, VD hoặc VDC.")
    if dang not in DANG_GROUP_ORDER:
        raise RuntimeError("Dạng câu hỏi không hợp lệ.")

    out: Dict[str, Any] = {
        "Mon": clean(raw.get("Mon", raw.get("mon", ""))),
        "Lop": clean(raw.get("Lop", raw.get("lop", ""))),
        "Chuong": clean(raw.get("Chuong", raw.get("chuong", ""))),
        "BaiHoc": clean(raw.get("BaiHoc", raw.get("baihoc", raw.get("bai_hoc", "")))),
        "DangBaiTap": clean(raw.get("DangBaiTap", raw.get("dangbaitap", raw.get("dang_bai_tap", "")))),
        "NangLucVatLy": norm_nang_luc_vat_ly(raw.get("NangLucVatLy", raw.get("nang_luc_vat_ly", raw.get("nlvl", "")))),
        "Dang": dang,
        "MucDo": mucdo,
        "BoDe": clean(raw.get("BoDe", raw.get("bode", ""))) or "Ngân hàng AI",
        "De": clean(raw.get("De", raw.get("de", ""))),
        "MaDe": clean(raw.get("MaDe", raw.get("made", ""))),
        "QuyenTruyCap": access_level_from_text(raw.get("QuyenTruyCap", raw.get("quyen", "VIP"))),
        "Diem": clean(raw.get("Diem", raw.get("diem", ""))),
        "SaiSo": clean(raw.get("SaiSo", raw.get("saiso", ""))),
        "extra_instruction": clean(raw.get("extra_instruction", raw.get("instruction", raw.get("yeu_cau_them", ""))))[:1800],
        "request_id": clean(raw.get("request_id", ""))[:80],
        "count": count,
        "offset": offset,
    }
    missing = [k for k in ("Mon", "Lop", "Chuong", "BaiHoc", "DangBaiTap") if not out[k]]
    if missing:
        labels = {"Mon": "Môn", "Lop": "Lớp", "Chuong": "Chương", "BaiHoc": "Bài học", "DangBaiTap": "Dạng bài tập"}
        raise RuntimeError("Chưa nhập: " + ", ".join(labels[x] for x in missing) + ".")
    if not out["De"]:
        out["De"] = f"{out['BaiHoc']} · {out['DangBaiTap']}"
    if not out["request_id"]:
        out["request_id"] = stable_hash(
            f"{session.get('mahs')}|{out['Mon']}|{out['Lop']}|{out['BaiHoc']}|{out['DangBaiTap']}|{time.time()}|{random.random()}",
            14,
        )
    if not out["MaDe"]:
        # Cùng khóa thẻ bài với catalog → sau lưu thấy ngay trong đúng bài học
        out["MaDe"] = catalog_group_key(out)
    avoid = raw.get("avoid_stems") or raw.get("avoid") or []
    if isinstance(avoid, str):
        avoid = [x.strip() for x in avoid.split("\n") if x.strip()]
    if not isinstance(avoid, list):
        avoid = []
    out["avoid_stems"] = [short_plain_text(x, 180) for x in avoid if clean(x)][:40]
    out["wants_tikz"] = ai_gen_wants_tikz(out)
    return out


def ai_gen_wants_tikz(spec: Dict[str, Any]) -> bool:
    """ADMIN yêu cầu đồ thị / TikZ trong form tạo ngân hàng."""
    blob = " ".join([
        clean(spec.get("extra_instruction", "")),
        clean(spec.get("DangBaiTap", "")),
        clean(spec.get("BaiHoc", "")),
    ])
    kn = key_norm(blob)
    keys = (
        "tikz", "do thi", "dong thi", "hinh ve", "hinh anh", "graph", "bieu do",
        "ve anh", "ve do thi", "minh hoa bang hinh", "co hinh", "nhu hinh",
    )
    return any(k in kn for k in keys)


def ai_gen_output_fields_for_spec(spec: Dict[str, Any]) -> List[str]:
    out = list(AI_GEN_OUTPUT_FIELDS)
    if ai_gen_wants_tikz(spec):
        out.append("Tikz")
    return out


def _extract_tikz_block(text: str) -> str:
    m = _LATEX_TIKZ_RE.search(clean(text))
    return m.group(0) if m else ""


def _encode_tikzraw(tikz_code: str) -> str:
    code = clean(tikz_code)
    if not code:
        return ""
    enc = base64.urlsafe_b64encode(code.encode("utf-8")).decode("ascii")
    return f"tikzraw:{enc}"


def _parse_hinhanh_cell(value: Any) -> Tuple[str, str]:
    """Tách cột T: (link ảnh hoặc tikzraw, mã TikZ thuần để sửa)."""
    s = clean(value)
    if not s:
        return "", ""
    lines = [ln.strip() for ln in re.split(r"[\r\n]+", s) if ln.strip()]
    img = ""
    tikz = ""
    for ln in lines:
        low = ln.lower()
        if low.startswith("tikzraw:"):
            tikz = _decode_tikzraw_src(ln) or tikz
        elif not img and (
            extract_drive_file_id(ln)
            or ln.startswith("http://")
            or ln.startswith("https://")
            or ln.startswith("/static/")
            or ln.lower().startswith("static/")
        ):
            img = ln
    if not tikz and len(lines) == 1 and lines[0].lower().startswith("tikzraw:"):
        tikz = _decode_tikzraw_src(lines[0])
        return lines[0], tikz
    if not img and tikz:
        return _encode_tikzraw(tikz), tikz
    return img, tikz


def _build_hinhanh_cell(image_link: str, tikz_code: str) -> str:
    parts: List[str] = []
    img = clean(image_link)
    tz = clean(tikz_code)
    if img and not img.lower().startswith("tikzraw:"):
        norm = normalize_image_src(img)
        parts.append(norm or img)
    if tz:
        tr = _encode_tikzraw(tz)
        if tr:
            parts.append(tr)
    return "\n".join(parts)


def _maybe_extract_tikz_into_hinhanh(
    data: Dict[str, Any], *, only_fields: Optional[set] = None
) -> Dict[str, Any]:
    """Giữ TikZ tại chỗ trong Sheet (K/L–O/R) — không gộp sang cột T."""
    return dict(data or {})


def _process_ai_gen_tikz(raw: Dict[str, Any], ordinal: int) -> Tuple[str, str]:
    """Lưu mã TikZ (tikzraw) vào cột T — có thể sửa lại; thử biên dịch chỉ để báo lỗi."""
    candidates = [
        clean(raw.get("Tikz", "")),
        clean(raw.get("HinhAnh", "")),
    ]
    for f in ("CauHoi", "LoiGiai", "A", "B", "C", "D"):
        candidates.append(_extract_tikz_block(clean(raw.get(f, ""))))
    tikz_code = ""
    for c in candidates:
        block = _extract_tikz_block(c) if c else ""
        if block:
            tikz_code = block
            break
    if not tikz_code:
        return "", "Chưa có \\begin{tikzpicture}…\\end{tikzpicture} — không vẽ được đồ thị."
    enc_line = _encode_tikzraw(tikz_code)
    ctx = _build_latex_asset_context(commit=True)
    url = _compile_tikz_to_png(tikz_code, ctx, ordinal, 1)
    warn = ""
    if url:
        warn = "Mã TikZ đã lưu — có thể sửa trong form trước khi tải ảnh lên Drive."
    else:
        for w in (ctx.get("warnings") or []):
            wtxt = clean(w.get("warning", ""))
            if wtxt:
                warn = wtxt
                break
        if not warn:
            warn = "TikZ chưa biên dịch thử — trang sẽ tự vẽ khi xem; vẫn sửa được mã."
    return enc_line, warn


def _ai_generation_answer_plan(spec: Dict[str, Any]) -> List[str]:
    count = int(spec.get("count") or 1)
    offset = int(spec.get("offset") or 0)
    if spec.get("Dang") == "Trắc nghiệm":
        return ["ABCD"[(offset + i) % 4] for i in range(count)]
    if spec.get("Dang") == "Đúng sai":
        patterns = ["Đ,S,Đ,S", "S,Đ,S,Đ", "Đ,Đ,S,S", "S,S,Đ,Đ", "Đ,S,S,Đ", "S,Đ,Đ,S"]
        return [patterns[(offset + i) % len(patterns)] for i in range(count)]
    return []


def build_ai_generate_questions_prompt(spec: Dict[str, Any], references: List[Dict[str, Any]]) -> str:
    count = int(spec.get("count") or 1)
    dang = spec["Dang"]
    answer_plan = _ai_generation_answer_plan(spec)
    out_fields = ai_gen_output_fields_for_spec(spec)
    wants_tikz = "Tikz" in out_fields
    schema_question = {f: "" for f in out_fields}
    schema = {"questions": [schema_question]}
    dang_rules = {
        "Trắc nghiệm": [
            "Mỗi câu bắt buộc có đủ A, B, C, D; các phương án cùng kiểu đại lượng và có nhiễu hợp lý.",
            "DapAn chỉ là đúng một chữ A/B/C/D.",
            "LoiGiai phải tự tính kiểm tra và chốt rõ đáp án đúng — chỉ giải thích phương án đúng (một bài giải liền mạch), không giải thích từng ý A/B/C/D kiểu Đ/S.",
            "Phân bố đáp án theo kế hoạch, không dồn tất cả vào một chữ.",
        ],
        "Đúng sai": [
            "A, B, C, D là bốn mệnh đề độc lập để xét Đúng/Sai.",
            "DapAn ghi đúng mẫu A=Đúng; B=Sai; C=Đúng; D=Sai.",
            "LoiGiai: đúng 4 dòng `A. Đúng — giải thích` (mỗi dòng chỉ một lần Đúng/Sai, KHÔNG viết A. Đúng — Đúng. …).",
        ],
        "Trả lời ngắn": [
            "A, B, C, D phải để trống.",
            "DapAn là kết quả ngắn gọn, có đơn vị nếu cần.",
            "LoiGiai có công thức, thay số và bước làm tròn nếu đề yêu cầu.",
        ],
        "Tự luận": [
            "A, B, C, D để trống.",
            "DapAn ghi kết quả/kết luận chính; LoiGiai trình bày đủ các bước.",
        ],
    }[dang]
    ref_text = json.dumps(references[:3], ensure_ascii=False, indent=2) if references else "Không có câu mẫu; tự bám đúng chương, bài học và dạng bài tập đã chỉ định."
    avoid_text = "\n".join(f"- {x}" for x in spec.get("avoid_stems", [])[:40]) or "- Không có."
    plan_text = json.dumps(answer_plan, ensure_ascii=False) if answer_plan else "Không áp dụng."
    extra = spec.get("extra_instruction") or "Không có yêu cầu thêm."
    fields_line = f"Mỗi phần tử trong questions[] CHỈ gồm: {', '.join(out_fields)}."
    meta_skip = "MaDe, Mon, Lop, Chuong, BaiHoc, DangBaiTap, MucDo, Dang, QuyenTruyCap, BoDe, De, ID, HinhAnh"
    lines = [
        "Bạn là giáo viên THPT Việt Nam chuyên xây dựng ngân hàng câu hỏi chính xác.",
        f"Hãy tạo ĐÚNG {count} câu hỏi MỚI, không trùng nhau, theo đúng metadata bên dưới.",
        "Chỉ trả về MỘT JSON object hợp lệ; không markdown, không ``` và không viết thêm lời giải thích ngoài JSON.",
        "Mọi backslash LaTeX trong JSON phải escape đúng. Công thức chỉ dùng $...$ trên một dòng, không dùng $$...$$.",
        "Mỗi câu phải có đáp án và lời giải đã được tự kiểm tra.",
        "",
        f"METADATA (server tự gán — KHÔNG ghi lại {meta_skip} trong JSON):",
        json.dumps({k: spec[k] for k in ("Mon", "Lop", "Chuong", "BaiHoc", "DangBaiTap", "MucDo", "Dang", "QuyenTruyCap")}, ensure_ascii=False),
        fields_line,
        "",
        "QUY TẮC THEO DẠNG CÂU:",
        *(f"- {x}" for x in dang_rules),
        f"- Kế hoạch đáp án cho {count} câu theo đúng thứ tự: {plan_text}",
        "",
        "YÊU CẦU CHẤT LƯỢNG:",
        "- Cùng Dạng bài tập nhưng thay đổi số liệu/tình huống/cách hỏi để các câu không lặp mẫu máy móc.",
        "- Mức NB: nhận biết trực tiếp; TH: hiểu và biến đổi ngắn; VD: vận dụng nhiều bước; VDC: tổng hợp hoặc có bẫy hợp lý.",
        "- Số liệu đẹp, đơn vị chuẩn, kết quả hợp lý; không tạo phương án vô nghĩa.",
        "- Nội dung phù hợp chương trình THPT và đúng Môn/Lớp đã chỉ định.",
        f"- Yêu cầu thêm của ADMIN: {extra}",
        "",
        "KHÔNG ĐƯỢC TẠO LẠI CÁC CÂU CÓ NỘI DUNG GẦN GIỐNG:",
        avoid_text,
        "",
        "CÂU MẪU CÙNG PHẠM VI (chỉ tham khảo cấu trúc, tuyệt đối không chép):",
        ref_text,
        "",
        "SCHEMA JSON BẮT BUỘC:",
        json.dumps(schema, ensure_ascii=False, indent=2),
    ]
    if wants_tikz:
        tikz_insert = [
            "",
            "ĐỒ THỊ / HÌNH TIKZ (BẮT BUỘC):",
            "- Trường Tikz chứa đúng một khối \\begin{tikzpicture}...\\end{tikzpicture}.",
            "- Vẽ đồ thị d–t, v–t, sơ đồ lực… rõ ràng: trục, mốc, đơn vị; số liệu khớp đề và lời giải.",
            "- Chỉ được viết «như hình vẽ»/«theo đồ thị» khi đã có Tikz đầy đủ.",
            "- Không ghi URL ảnh; server tự biên dịch Tikz → PNG (cột HinhAnh).",
            "- Không nhét \\begin{tikzpicture} vào CauHoi — chỉ ghi trong Tikz.",
        ]
        lines[5:5] = tikz_insert
    else:
        lines.insert(5, "Không tạo hình ảnh, không viện dẫn hình/bảng chưa được cung cấp, không thiếu dữ kiện.")
        no_hinh_idx = next(i for i, x in enumerate(lines) if x.startswith("- Nội dung phù hợp"))
        lines.insert(no_hinh_idx + 1, "- Không ghi ID, MaDe, HinhAnh — server tự tạo.")
    return "\n".join(lines)


def _flatten_ai_dapan(value: Any) -> str:
    """AI hay trả DapAn dạng object/list thay vì chuỗi A=Đúng; B=Sai…"""
    if value is None:
        return ""
    if isinstance(value, dict):
        parts = []
        for L in "ABCD":
            v = value.get(L)
            if v is None:
                v = value.get(L.lower())
            if v is not None and clean(v) != "":
                parts.append(f"{L}={clean(v)}")
        return "; ".join(parts) if parts else ""
    if isinstance(value, list):
        vals = [_tf_token_to_ds(v) for v in value[:4]]
        if sum(1 for x in vals if x) >= 2:
            return "; ".join(
                f"{L}={'Đúng' if vals[i] == 'Đ' else 'Sai'}"
                for i, L in enumerate("ABCD")
                if i < len(vals) and vals[i]
            )
    return clean(value)


def _resolve_ai_ds_dapan(data: Dict[str, Any]) -> str:
    """Gộp đáp án Đ/S từ DapAn + LoiGiai khi AI trả lệch format."""
    letters = [L for L in "ABCD" if clean(data.get(L))]
    if len(letters) < 4:
        return ""
    dapan_raw = data.get("DapAn")
    if isinstance(dapan_raw, (dict, list)):
        dapan_raw = _flatten_ai_dapan(dapan_raw)
    da = _format_tf_answer_standard(dapan_raw)
    if da:
        return da
    lg_da = _format_tf_answer_standard(ds_dapan_from_loigiai(clean(data.get("LoiGiai", "")), data))
    if lg_da:
        return lg_da
    merged: Dict[str, str] = {}
    for i, L in enumerate("ABCD"):
        vals = parse_tf_values(dapan_raw)
        if i < len(vals) and vals[i] in ("Đ", "S"):
            merged[L] = "Đúng" if vals[i] == "Đ" else "Sai"
    for L, v in extract_ds_verdicts_from_loigiai(clean(data.get("LoiGiai", ""))).items():
        merged.setdefault(L, v)
    if all(merged.get(L) for L in letters):
        return "; ".join(f"{L}={merged[L]}" for L in letters)
    return ""


def _normalize_ai_gen_raw(raw: Dict[str, Any]) -> Dict[str, Any]:
    """Chuẩn hóa key AI hay trả lệch (cau_hoi, dap_an…)."""
    raw = dict(raw or {})
    alias = {
        "cauhoi": "CauHoi", "cau_hoi": "CauHoi", "noidung": "CauHoi", "de_bai": "CauHoi",
        "loigiai": "LoiGiai", "loi_giai": "LoiGiai", "giai": "LoiGiai",
        "dapan": "DapAn", "dap_an": "DapAn", "answer": "DapAn",
        "nanglucvatly": "NangLucVatLy", "nang_luc_vat_ly": "NangLucVatLy", "nlvl": "NangLucVatLy",
        "tikz": "Tikz", "tikz_code": "Tikz", "hinhanh": "HinhAnh",
    }
    out = dict(raw)
    for k, v in raw.items():
        canon = alias.get(key_norm(k))
        if canon:
            out[canon] = v
    if isinstance(out.get("DapAn"), (dict, list)):
        out["DapAn"] = _flatten_ai_dapan(out.get("DapAn"))
    return out


def _salvage_ai_question_dicts(raw: str) -> List[Dict[str, Any]]:
    """Cứu các object câu hỏi hoàn chỉnh khi JSON bị cắt cụt giữa chừng."""
    raw = _strip_ai_json_fence(raw)
    if not raw:
        return []
    m = re.search(r'"questions"\s*:\s*\[', raw, flags=re.I)
    start = m.end() - 1 if m else raw.find("[")
    if start < 0:
        return []
    out: List[Dict[str, Any]] = []
    i = start + 1
    n = len(raw)
    while i < n:
        while i < n and raw[i] in " \t\n\r,":
            i += 1
        if i >= n or raw[i] == "]":
            break
        if raw[i] != "{":
            i += 1
            continue
        depth = 0
        in_str = False
        esc = False
        j = i
        while j < n:
            ch = raw[j]
            if in_str:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == '"':
                    in_str = False
                j += 1
                continue
            if ch == '"':
                in_str = True
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    chunk = raw[i: j + 1]
                    parsed_obj: Optional[Dict[str, Any]] = None
                    for variant in (chunk, _repair_latex_json_escapes(chunk)):
                        try:
                            obj = json.loads(variant)
                            if isinstance(obj, dict):
                                parsed_obj = obj
                                break
                        except Exception:
                            log_swallow("_salvage_ai_question_dicts:12970")
                            pass
                    if parsed_obj:
                        norm = _normalize_ai_gen_raw(parsed_obj)
                        if clean(norm.get("CauHoi", "")) or any(clean(norm.get(L, "")) for L in "ABCD"):
                            out.append(norm)
                    i = j + 1
                    break
            j += 1
        else:
            break
    return out


def _extract_ai_question_list(txt: Any) -> List[Dict[str, Any]]:
    parsed = _json_loads_ai_lenient(str(txt or ""))
    if isinstance(parsed, list):
        return [_normalize_ai_gen_raw(x) for x in parsed if isinstance(x, dict)]
    if isinstance(parsed, dict):
        for key in ("questions", "items", "cau_hoi", "CauHoi"):
            items = parsed.get(key)
            if isinstance(items, list):
                return [_normalize_ai_gen_raw(x) for x in items if isinstance(x, dict)]
        if isinstance(parsed.get("question"), dict):
            return [_normalize_ai_gen_raw(parsed.get("question"))]
    salvaged = _salvage_ai_question_dicts(str(txt or ""))
    if salvaged:
        return salvaged
    return []


def _format_tf_answer_standard(value: Any) -> str:
    vals = parse_tf_values(value)
    if sum(1 for x in vals if x in ("Đ", "S")) < 4:
        return ""
    return "; ".join(f"{L}={'Đúng' if vals[i] == 'Đ' else 'Sai'}" for i, L in enumerate("ABCD"))


def coerce_ai_generated_question(raw: Dict[str, Any], spec: Dict[str, Any], ordinal: int) -> Tuple[Optional[Dict[str, Any]], str]:
    raw = _normalize_ai_gen_raw(raw or {})
    data = {f: clean(raw.get(f, "")) for f in CREATE_QUESTION_FIELDS}
    for f in ("MaDe", "BoDe", "De", "Lop", "Mon", "Chuong", "BaiHoc", "DangBaiTap", "MucDo", "Dang", "QuyenTruyCap", "Diem"):
        data[f] = clean(spec.get(f, ""))
    requested_nlvl = norm_nang_luc_vat_ly(spec.get("NangLucVatLy", ""))
    data["NangLucVatLy"] = requested_nlvl or ""
    data["ID"] = "AIQ_" + stable_hash(
        f"{spec.get('request_id')}|{spec.get('offset', 0)}|{ordinal}|{data.get('CauHoi')}|{time.time()}|{random.random()}",
        14,
    )
    data["HinhAnh"] = ""
    if spec.get("wants_tikz") or ai_gen_wants_tikz(spec):
        hinh, tz_warn = _process_ai_gen_tikz({**raw, **data}, ordinal)
        if hinh:
            data["HinhAnh"], hz = _finalize_hinhanh_for_sheet(hinh)
            if hz and not tz_warn:
                tz_warn = hz
        if tz_warn:
            data["_ai_tikz_warning"] = tz_warn
    data["Dang"] = spec["Dang"]
    data["MucDo"] = spec["MucDo"]
    data["QuyenTruyCap"] = spec["QuyenTruyCap"]
    data["TrangThai"] = QUESTION_REVIEW_PENDING_LABEL
    for f in ("CauHoi", "A", "B", "C", "D", "DapAn", "SaiSo", "LoiGiai"):
        data[f] = normalize_latex_light(data.get(f, ""))
    if not data["CauHoi"]:
        return None, "Thiếu nội dung câu hỏi"

    dang = spec["Dang"]
    if dang == "Trắc nghiệm":
        # AI hay dồn «A. … B. … C. … D. …» vào một ô A
        split_opts = merge_abcd_options_from_text(
            " ".join(f"{L}. {data[L]}" for L in "ABCD" if data.get(L)).strip()
            or data.get("A", ""),
            {L: data.get(L, "") for L in "ABCD"},
        )
        if len([L for L in "ABCD" if clean(split_opts.get(L, ""))]) >= 2:
            for L in "ABCD":
                data[L] = clean(split_opts.get(L, "")) or data.get(L, "")
        missing = [L for L in "ABCD" if not data[L]]
        if missing:
            return None, "Thiếu phương án " + ", ".join(missing)
        da = norm_letter(data["DapAn"])
        if not da:
            return None, "Đáp án trắc nghiệm không phải A/B/C/D"
        data["DapAn"] = da
    elif dang == "Đúng sai":
        missing = [L for L in "ABCD" if not data[L]]
        if missing:
            return None, "Thiếu mệnh đề " + ", ".join(missing)
        da = _resolve_ai_ds_dapan(data)
        if not da:
            return None, "Đáp án Đúng/Sai chưa đủ 4 ý"
        data["DapAn"] = da
        data["LoiGiai"] = normalize_ds_loigiai(data["LoiGiai"], data, use_sheet_dapan=True)
    elif dang == "Trả lời ngắn":
        for L in "ABCD":
            data[L] = ""
        if not data["DapAn"]:
            return None, "Thiếu đáp án trả lời ngắn"
    else:
        for L in "ABCD":
            data[L] = ""
        if not data["DapAn"] and not data["LoiGiai"]:
            return None, "Tự luận thiếu đáp án/lời giải"

    if not data["LoiGiai"]:
        return None, "Thiếu lời giải"
    return data, ""


def validate_ai_generated_questions_for_save(items: Any) -> List[Dict[str, Any]]:
    if not isinstance(items, list) or not items:
        raise RuntimeError("Chưa có câu hỏi để lưu.")
    if len(items) > AI_GENERATE_TOTAL_MAX:
        raise RuntimeError(f"Mỗi lần chỉ lưu tối đa {AI_GENERATE_TOTAL_MAX} câu.")
    out: List[Dict[str, Any]] = []
    for i, raw in enumerate(items, start=1):
        if not isinstance(raw, dict):
            raise RuntimeError(f"Câu {i}: dữ liệu không phải JSON object.")
        data = {f: clean(raw.get(f, "")) for f in CREATE_QUESTION_FIELDS}
        if not data["CauHoi"]:
            raise RuntimeError(f"Câu {i}: thiếu CauHoi.")
        missing_meta = [f for f in ("Mon", "Lop", "Chuong", "BaiHoc", "DangBaiTap") if not data.get(f)]
        if missing_meta:
            raise RuntimeError(f"Câu {i}: thiếu metadata " + ", ".join(missing_meta) + ".")
        data["MucDo"] = clean(data.get("MucDo", "")).upper()
        data["NangLucVatLy"] = norm_nang_luc_vat_ly(data.get("NangLucVatLy", ""))  # tùy chọn — GPT tạo ngân hàng không bắt buộc
        if data["MucDo"] not in ("NB", "TH", "VD", "VDC"):
            raise RuntimeError(f"Câu {i}: MucDo phải là NB/TH/VD/VDC.")
        data["Dang"] = norm_dang(data.get("Dang"))
        if data["Dang"] == "Trắc nghiệm":
            if any(not data[L] for L in "ABCD") or not is_mcq_letter_answer(data["DapAn"]):
                raise RuntimeError(f"Câu {i}: trắc nghiệm phải đủ A-D và DapAn là A/B/C/D.")
            data["DapAn"] = norm_letter(data["DapAn"])
        elif data["Dang"] == "Đúng sai":
            if any(not data[L] for L in "ABCD"):
                raise RuntimeError(f"Câu {i}: Đúng/Sai phải đủ 4 mệnh đề A-D.")
            da = _format_tf_answer_standard(data["DapAn"])
            if not da:
                raise RuntimeError(f"Câu {i}: đáp án Đúng/Sai chưa đủ 4 ý.")
            data["DapAn"] = da
            data["LoiGiai"] = normalize_ds_loigiai(data["LoiGiai"], data, use_sheet_dapan=True)
        elif data["Dang"] in ("Trả lời ngắn", "Tự luận"):
            for L in "ABCD":
                data[L] = ""
        if not data.get("TrangThai"):
            data["TrangThai"] = QUESTION_REVIEW_PENDING_LABEL
        if not data["ID"]:
            data["ID"] = "AIQ_" + stable_hash(f"save|{i}|{data['CauHoi']}|{time.time()}|{random.random()}", 14)
        # MaDe ổn định theo bài — gom vào đúng thẻ catalog (GRP_/AI_ cùng bài)
        if not data["MaDe"]:
            data["MaDe"] = catalog_group_key(data)
        data.pop("_ai_tikz_warning", None)
        tikz_extra = clean(data.pop("Tikz", None) or "")
        if tikz_extra:
            img_link, _ = _parse_hinhanh_cell(data.get("HinhAnh", ""))
            img_clean = img_link if img_link and not img_link.lower().startswith("tikzraw:") else ""
            data["HinhAnh"] = _build_hinhanh_cell(img_clean, tikz_extra)
        data["HinhAnh"], hz = _finalize_hinhanh_for_sheet(data.get("HinhAnh", ""))
        if hz:
            data["_hinhanh_warning"] = hz
        data["QuyenTruyCap"] = access_level_from_text(data.get("QuyenTruyCap", "VIP"))
        out.append(data)
    return out


def ai_generate_question_batch_from_provider(
    spec: Dict[str, Any],
    references: List[Dict[str, Any]],
    *,
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
    extra_anthropic_key: str = "",
) -> Dict[str, Any]:
    cfg = ai_runtime_config()
    openai_keys = load_ai_keys("OPENAI")
    gemini_keys = load_ai_keys("GEMINI")
    anthropic_keys = load_ai_keys("ANTHROPIC") if is_admin() else []
    if not openai_keys and not gemini_keys and not anthropic_keys:
        raise RuntimeError("Chưa có key AI (Gemini/GPT/Claude) để ADMIN tạo câu hỏi.")

    sys_prompt = (
        "Bạn là chuyên gia ra đề THPT Việt Nam. Chỉ trả JSON hợp lệ, không markdown. "
        "Mỗi câu phải đúng kiến thức, đúng loại câu, có đáp án và lời giải tự kiểm tra."
    )
    user_prompt = build_ai_generate_questions_prompt(spec, references)
    count = max(1, int(spec.get("count") or 1))
    dang = spec.get("Dang") or ""
    wants_tikz = bool(spec.get("wants_tikz")) or ai_gen_wants_tikz(spec)
    fp_now = admin_ai_resolve_force(force_provider)
    # Render gunicorn timeout ~120s: luôn cắt nhỏ đợt + token để AI kịp trả JSON
    if fp_now == "ANTHROPIC":
        count = min(count, 1)
    else:
        count = min(count, 2)
    per_q = 2200 if dang == "Đúng sai" else (1800 if dang == "Tự luận" else 1400)
    if wants_tikz:
        per_q += 800
    tok_cap = 8000 if wants_tikz else 5500
    max_tokens = min(tok_cap, max(2800, count * per_q))
    gen_timeout = 48
    temp = 0.22
    model_openai = clean(cfg.get("openai_admin_model") or cfg.get("openai_model") or DEFAULT_OPENAI_ADMIN_MODEL) or DEFAULT_OPENAI_ADMIN_MODEL
    model_gemini = clean(os.environ.get("GEMINI_ADMIN_MODEL", DEFAULT_GEMINI_ADMIN_MODEL)) or DEFAULT_GEMINI_ADMIN_MODEL
    if fp_now == "ANTHROPIC":
        max_tokens = min(max_tokens, 4500)
        gen_timeout = min(gen_timeout, 42)
    last_error = ""
    raw_text = ""
    last_finish = ""
    used_provider = "GEMINI"
    key_index = 0
    model_used = ""
    gemini_saw_quota = False

    def try_openai(tok: int) -> bool:
        nonlocal last_error, raw_text, used_provider, key_index, model_used, last_finish
        for idx, api_key in enumerate(openai_keys, start=1):
            txt, finish, err = _openai_chat_call(
                api_key, model_openai, sys_prompt, user_prompt, tok, temp, timeout=gen_timeout
            )
            if txt:
                raw_text = txt
                last_finish = finish
                used_provider = "OPENAI"
                key_index = idx
                model_used = model_openai
                return True
            last_error = err or finish or last_error
            last_finish = finish or last_finish
        return False

    def try_gemini(tok: int) -> bool:
        nonlocal last_error, raw_text, used_provider, key_index, model_used, gemini_saw_quota, last_finish
        # Chỉ 1 model chính + tối đa 1 fallback — tránh vòng lặp nhiều model làm quá timeout Render
        models = [model_gemini]
        for m in GEMINI_HINT_MODEL_FALLBACKS:
            if m != model_gemini:
                models.append(m)
                break
        for idx, api_key in enumerate(gemini_keys[:2], start=1):
            for gmodel in models:
                txt, finish, err = _gemini_hint_call(
                    api_key, gmodel, sys_prompt, user_prompt, tok, temp, timeout=gen_timeout
                )
                if txt:
                    raw_text = txt
                    last_finish = finish
                    used_provider = "GEMINI"
                    key_index = idx
                    model_used = gmodel
                    return True
                last_error = err or finish or last_error
                last_finish = finish or last_finish
                if _is_quota_or_rate_error(last_error):
                    gemini_saw_quota = True
                    break
        return False

    def try_anthropic(tok: int) -> bool:
        nonlocal last_error, raw_text, used_provider, key_index, model_used, last_finish
        ant_model = clean(os.environ.get("ANTHROPIC_ADMIN_MODEL", "")) or "claude-sonnet-4-6"
        for idx, api_key in enumerate(anthropic_keys, start=1):
            try:
                txt, finish, err = _anthropic_chat_call(
                    api_key, ant_model, sys_prompt, user_prompt,
                    max(tok, 4000), temp, timeout=gen_timeout
                )
                if txt:
                    raw_text = txt
                    last_finish = finish or ""
                    used_provider = "ANTHROPIC"
                    key_index = idx
                    model_used = ant_model
                    return True
                last_error = err or finish or last_error
            except Exception as e:
                last_error = str(e)
        return False

    def call_provider(tok: int) -> bool:
        fp = admin_ai_resolve_force(force_provider)
        if fp == "OPENAI":
            return try_openai(tok)
        if fp == "ANTHROPIC":
            return try_anthropic(tok)
        # Mặc định: Anthropic trước (nếu có key riêng), rồi Gemini, rồi GPT
        if anthropic_keys:
            if try_anthropic(tok):
                return True
        if try_gemini(tok):
            return True
        if gemini_saw_quota and anthropic_keys:
            if try_anthropic(tok):
                return True
        if gemini_saw_quota and openai_keys and not allow_gpt_fallback:
            raise AdminGeminiQuotaError(last_error, openai_available=True)
        if allow_gpt_fallback and openai_keys:
            return try_openai(tok)
        return False

    ok = call_provider(max_tokens)
    if not ok:
        raise RuntimeError("AI chưa tạo được câu: " + (last_error or "không có phản hồi."))

    raw_items = _extract_ai_question_list(raw_text)
    # Chỉ retry nhẹ khi bị cắt token — tránh gọi AI lần 2 làm gunicorn 500
    if not raw_items and raw_text:
        cut = "MAX_TOKENS" in (last_finish or "").upper() or "LENGTH" in (last_finish or "").upper()
        if cut:
            retry_tok = min(tok_cap, max_tokens + 1500)
            if retry_tok > max_tokens and call_provider(retry_tok):
                raw_items = _extract_ai_question_list(raw_text)
    if not raw_items:
        preview = short_plain_text(raw_text, 300)
        prov = "Gemini" if used_provider == "GEMINI" else "GPT"
        cut = "MAX_TOKENS" in (last_finish or "").upper() or "LENGTH" in (last_finish or "").upper()
        hint = "Phản hồi bị cắt giữa chừng — " if cut else ""
        raise RuntimeError(
            hint + "AI trả về dữ liệu không đúng JSON questions[]. "
            f"({prov}). Thử bấm lại hoặc chọn GPT khi hết quota Gemini. "
            + (f"Đầu phản hồi: {preview}" if preview else "AI không trả nội dung.")
        )
    questions: List[Dict[str, Any]] = []
    warnings: List[str] = []
    seen: set = set()
    for idx, raw in enumerate(raw_items[:count], start=1):
        q, err = coerce_ai_generated_question(raw, spec, idx)
        if not q:
            warnings.append(f"Câu {idx}: {err}")
            continue
        if q.get("_ai_tikz_warning"):
            warnings.append(f"Câu {idx}: {q['_ai_tikz_warning']}")
        elif q.get("_hinhanh_warning"):
            warnings.append(f"Câu {idx}: {q['_hinhanh_warning']}")
        fp = question_content_fingerprint(canonical_question({f: q.get(f, "") for f in QUESTION_FIELDS}))
        if fp in seen:
            warnings.append(f"Câu {idx}: trùng nội dung trong cùng đợt")
            continue
        seen.add(fp)
        questions.append(q)
    if not questions:
        raise RuntimeError("AI có phản hồi nhưng không có câu hợp lệ. " + " · ".join(warnings[:4]))
    if len(questions) < count:
        warnings.append(f"Đợt này yêu cầu {count} câu nhưng chỉ nhận được {len(questions)} câu hợp lệ; app sẽ gọi tiếp phần còn thiếu.")
    return {
        "ok": True,
        "questions": questions,
        "generated": len(questions),
        "requested": count,
        "warnings": warnings,
        "provider_used": used_provider,
        "model_used": model_used,
        "key_index": key_index,
    }


def _coerce_ai_question_result(
    src_q: Dict[str, Any],
    obj: Dict[str, Any],
    *,
    target_dang: str,
) -> Dict[str, Any]:
    """Chuẩn hóa JSON AI thành đúng cột Google Sheet."""
    payload = obj.get("question") if isinstance(obj.get("question"), dict) else obj
    out: Dict[str, Any] = {}
    # Giữ metadata của câu gốc nếu AI không trả về.
    for f in CREATE_QUESTION_FIELDS:
        out[f] = clean(payload.get(f, src_q.get(f, "")))
    out["Dang"] = target_dang
    # Bắt buộc không để DangBaiTap lấn sang loại câu.
    if not clean(out.get("DangBaiTap")):
        out["DangBaiTap"] = clean(src_q.get("DangBaiTap", ""))
    # Chuẩn hóa text/LaTeX.
    for f in ("CauHoi", "A", "B", "C", "D", "LoiGiai"):
        out[f] = normalize_latex_text(out.get(f, ""))
    da = clean(out.get("DapAn", ""))
    warnings: List[str] = []
    if target_dang == "Trắc nghiệm":
        letter = norm_letter(da)
        if letter:
            out["DapAn"] = letter
        else:
            warnings.append("AI chưa trả đáp án trắc nghiệm dạng A/B/C/D.")
            out["DapAn"] = da
    elif target_dang == "Đúng sai":
        vals = parse_tf_values(da)
        if any(v in ("Đ", "S") for v in vals):
            parts = []
            for i, L in enumerate("ABCD"):
                if clean(out.get(L, "")):
                    v = vals[i] if i < len(vals) else ""
                    if v:
                        parts.append(f"{L}={'Đúng' if v == 'Đ' else 'Sai'}")
            out["DapAn"] = "; ".join(parts) if parts else da
        else:
            warnings.append("AI chưa trả đáp án Đ/S rõ ràng.")
            out["DapAn"] = da
    elif target_dang == "Trả lời ngắn":
        for L in "ABCD":
            out[L] = ""
        out["DapAn"] = normalize_latex_light(da)
    else:
        out["DapAn"] = normalize_latex_light(da)
    # ID/MaDe: khôi phục để sửa câu hiện tại thì giữ nguyên ID dòng cũ.
    if clean(src_q.get("ID")):
        out["ID"] = clean(src_q.get("ID"))
    if clean(src_q.get("MaDe")):
        out["MaDe"] = clean(src_q.get("MaDe"))
    # Cảnh báo từ AI + cảnh báo hậu kiểm.
    ai_warning = clean(obj.get("warning") or payload.get("warning") or "")
    if ai_warning:
        warnings.insert(0, ai_warning)
    return {
        "status": clean(obj.get("status") or payload.get("status") or "OK") or "OK",
        "repair_level": clean(obj.get("repair_level") or payload.get("repair_level") or "bo_sung"),
        "warning": "\n".join([w for w in warnings if w]),
        "question": out,
        "raw_json": obj,
    }


def build_ai_repair_question_prompt(q: Dict[str, Any], target_dang: str, mode: str = "repair") -> str:
    """Prompt ADMIN: AI khôi phục câu thiếu, trả JSON để đổ vào form sửa."""
    src = {f: clean(q.get(f, "")) for f in CREATE_QUESTION_FIELDS}
    missing = question_missing_report(q, target_dang)
    mode = clean(mode) or "repair"
    dang_rules = {
        "Trắc nghiệm": [
            "Dang phải là \"Trắc nghiệm\".",
            "Bắt buộc có 4 phương án A, B, C, D là các lựa chọn trả lời, không phải mệnh đề Đúng/Sai.",
            "DapAn bắt buộc chỉ là một chữ A hoặc B hoặc C hoặc D.",
            "LoiGiai chỉ giải thích phương án đúng (một bài giải liền mạch), không giải thích từng ý A/B/C/D kiểu Đ/S.",
            "Tuyệt đối không chốt kiểu A=Đúng/B=Sai.",
        ],
        "Đúng sai": [
            "Dang phải là \"Đúng sai\".",
            "A, B, C, D là 4 mệnh đề để xét đúng/sai.",
            "DapAn dạng chuẩn: A=Đúng; B=Sai; C=Đúng; D=Sai.",
            "LoiGiai phải giải thích từng ý A, B, C, D.",
        ],
        "Trả lời ngắn": [
            "Dang phải là \"Trả lời ngắn\".",
            "Không tạo phương án A/B/C/D; để A, B, C, D là chuỗi rỗng.",
            "DapAn là số/kết quả ngắn, có đơn vị nếu cần; SaiSo nếu đề yêu cầu làm tròn.",
        ],
        "Tự luận": [
            "Dang phải là \"Tự luận\".",
            "Không bắt buộc A/B/C/D; LoiGiai trình bày theo bước.",
        ],
    }.get(target_dang, [])
    schema = {
        "status": "OK hoặc NEED_REVIEW",
        "repair_level": "none | bo_sung_nhe | bo_sung_vua | tao_lai_theo_y_goc | need_review",
        "warning": "cảnh báo nếu dữ kiện thiếu nặng, để trống nếu chắc chắn",
        "question": {f: "..." for f in CREATE_QUESTION_FIELDS},
    }
    return "\n".join(
        [
            "Bạn là ADMIN kiểm định và khôi phục ngân hàng câu hỏi THPT.",
            "Nhiệm vụ: tái tạo/bổ sung các phần bị thiếu nhưng KHÔNG tự lưu Sheet.",
            "Chỉ trả về JSON hợp lệ, không markdown, không ```.",
            "Mọi ký tự backslash LaTeX trong JSON phải escape đúng dạng \\\\.",
            "",
            f"CHẾ ĐỘ: {mode}",
            f"DẠNG CÂU MỤC TIÊU: {target_dang}",
            "",
            "QUY TẮC BẮT BUỘC THEO DẠNG:",
            *(f"- {x}" for x in dang_rules),
            "",
            "QUY TẮC AN TOÀN:",
            "- Ưu tiên giữ nguyên ý gốc, số liệu gốc, môn/lớp/chương/bài/mức độ.",
            "- Nếu thiếu nhẹ như A/B/C/D, DapAn, LoiGiai thì bổ sung hợp lý và tự giải kiểm tra.",
            "- Nếu thiếu dữ kiện chính không thể suy chắc chắn, vẫn đề xuất bản hoàn chỉnh nhưng status=NEED_REVIEW và warning ghi rõ phần đã tự bổ sung.",
            "- Không đổi từ Trắc nghiệm sang Đúng sai hoặc ngược lại khi đã có DẠNG CÂU MỤC TIÊU.",
            "- Công thức LaTeX dùng $...$ một dòng; không dùng $$...$$.",
            "- LoiGiai ngắn gọn, đủ để tự học, có công thức thay số nếu cần.",
            "",
            "TRƯỜNG ĐANG THIẾU / CẢNH BÁO TRƯỚC KHI KHÔI PHỤC:",
            json.dumps(missing, ensure_ascii=False),
            "",
            "SCHEMA JSON BẮT BUỘC:",
            json.dumps(schema, ensure_ascii=False, indent=2),
            "",
            "DỮ LIỆU CÂU HIỆN TẠI:",
            json.dumps(src, ensure_ascii=False, indent=2),
        ]
    )


def build_ai_rewrite_ds_statements_prompt(q: Dict[str, Any]) -> str:
    """Prompt ADMIN: viết lại câu dẫn + 4 mệnh đề Đ/S — không đổi P/R."""
    src = {
        "Mon": clean(q.get("Mon", "")),
        "Lop": clean(q.get("Lop", "")),
        "Chuong": clean(q.get("Chuong", "")),
        "BaiHoc": clean(q.get("BaiHoc", "")),
        "DangBaiTap": clean(q.get("DangBaiTap", "")),
        "MucDo": clean(q.get("MucDo", "")),
        "CauHoi": clean(q.get("CauHoi", "")),
        "A": clean(q.get("A", "")),
        "B": clean(q.get("B", "")),
        "C": clean(q.get("C", "")),
        "D": clean(q.get("D", "")),
        "DapAn": clean(q.get("DapAn", "")),
    }
    schema = {
        "status": "OK hoặc NEED_REVIEW",
        "warning": "cảnh báo nếu không chắc ý gốc, để trống nếu chắc",
        "CauHoi": "câu dẫn ngắn (1–2 câu)",
        "A": "mệnh đề khẳng định 1",
        "B": "mệnh đề khẳng định 2",
        "C": "mệnh đề khẳng định 3",
        "D": "mệnh đề khẳng định 4",
    }
    return "\n".join(
        [
            "Bạn là giáo viên THPT Việt Nam, chuyên chuẩn hóa câu ĐÚNG/SAI (4 mệnh đề).",
            "Nhiệm vụ: VIẾT LẠI câu dẫn (CauHoi) và 4 mệnh đề A–D cho đúng dạng thi — KHÔNG sửa đáp án P, KHÔNG viết lời giải.",
            "Chỉ trả JSON hợp lệ, không markdown, không ```.",
            "Mọi ký tự backslash LaTeX trong JSON phải escape đúng dạng \\\\.",
            "",
            "QUY TẮC BẮT BUỘC:",
            "- Dang là Đúng/Sai: A, B, C, D là 4 MỆNH ĐỀ độc lập để học sinh chọn Đúng hoặc Sai.",
            "- Mỗi mệnh đề là MỘT câu khẳng định hoàn chỉnh (có thể đúng hoặc sai về mặt vật lý).",
            "- CauHoi chỉ là câu dẫn ngắn, ví dụ: «Xét các phát biểu sau về …» — KHÔNG nhét đáp án vào CauHoi.",
            "- GIỮ NGUYÊN ý vật lý và giá trị đúng/sai của từng ý (dựa vào nội dung gốc và DapAn nếu có).",
            "- KHÔNG đổi số liệu, công thức, đơn vị so với bản gốc trừ khi bản gốc sai chính tả/LaTeX.",
            "- Công thức LaTeX dùng $...$; không dùng $$...$$.",
            "",
            "LOẠI LỖI CẦN SỬA (rất hay gặp):",
            "- Gộp câu hỏi + đáp án meta: «Đại lượng nào… — phát biểu đúng là: Nhiệt độ».",
            "- Có cụm «phát biểu đúng là», «phát biểu … là đúng», «đáp án là», «—» nối câu hỏi với kết luận.",
            "- Mỗi ý là câu hỏi trắc nghiệm riêng thay vì mệnh đề.",
            "",
            "VÍ DỤ CHUẨN HÓA:",
            "SAI: «Đại lượng nào không đổi trong quá trình đẳng nhiệt… — phát biểu đúng là: Nhiệt độ.»",
            "ĐÚNG: «Trong quá trình đẳng nhiệt của một lượng khí xác định, nhiệt độ không đổi.»",
            "SAI: «Hệ thức nào là định luật Boyle? — phát biểu $V_1/T_1=V_2/T_2$ là đúng.»",
            "ĐÚNG: «Định luật Boyle được biểu diễn bởi hệ thức $V_1/T_1=V_2/T_2$.» (nếu mệnh đề này sai về mặt vật lý thì vẫn giữ ý sai đó).",
            "",
            "KHÔNG:",
            "- Không thêm tiền tố A. B. C. D. vào đầu mệnh đề.",
            "- Không trả DapAn, LoiGiai, không đổi Dang.",
            "- Không tự đổi Trắc nghiệm ↔ Đúng sai.",
            "",
            "SCHEMA JSON BẮT BUỘC:",
            json.dumps(schema, ensure_ascii=False, indent=2),
            "",
            "DỮ LIỆU CÂU HIỆN TẠI:",
            json.dumps(src, ensure_ascii=False, indent=2),
        ]
    )


def _coerce_ai_ds_statements_result(obj: Dict[str, Any]) -> Dict[str, Any]:
    """Chuẩn hóa JSON AI → CauHoi + A–D."""
    out: Dict[str, str] = {}
    for f in ("CauHoi", "A", "B", "C", "D"):
        s = clean(obj.get(f, ""))
        if f != "CauHoi":
            s = re.sub(rf"^(?:{re.escape(f)}\s*[.)]\s*)", "", s, flags=re.I).strip()
            s = re.sub(r"^(?:Phương án|Phuong an)\s*[ABCD]\s*[.)]\s*", "", s, flags=re.I).strip()
        out[f] = normalize_latex_light(s)
    if not any(out.get(L) for L in ("A", "B", "C", "D")):
        raise RuntimeError("AI chưa trả đủ mệnh đề A–D.")
    return {
        "fields": out,
        "status": clean(obj.get("status", "OK")) or "OK",
        "warning": clean(obj.get("warning", "")),
    }


def ai_rewrite_ds_statements(
    q: Dict[str, Any],
    *,
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
    extra_anthropic_key: str = "",
) -> Tuple[Dict[str, Any], str]:
    """ADMIN: viết lại CauHoi + A–D cho đúng dạng Đ/S; không đổi P/R."""
    dang = effective_dang(q)
    if dang != "Đúng sai":
        raise RuntimeError("Chỉ dùng cho câu Đúng/Sai.")
    if not any(clean(q.get(L, "")) for L in ("A", "B", "C", "D")):
        raise RuntimeError("Chưa có mệnh đề A–D để viết lại.")

    sys_prompt = (
        "Bạn là giáo viên ra đề THPT. "
        "Bạn chuẩn hóa câu Đúng/Sai: mỗi ý A–D là một mệnh đề, không meta-text. "
        "Chỉ trả JSON hợp lệ, không markdown."
    )
    user_prompt = build_ai_rewrite_ds_statements_prompt(q)

    txt, prov, _model, _ki = admin_ai_call_text(
        sys_prompt,
        user_prompt,
        max_tokens=1800,
        temp=0.12,
        timeout=45,
        force_provider=force_provider,
        allow_gpt_fallback=allow_gpt_fallback,
        extra_anthropic_key=extra_anthropic_key,
    )
    if not txt:
        raise RuntimeError("AI chưa trả về nội dung.")
    obj = _extract_ai_json_object(txt)
    if not obj:
        raise RuntimeError("AI không trả JSON hợp lệ.")
    result = _coerce_ai_ds_statements_result(obj)
    result["provider"] = prov
    return result, prov


def ai_repair_question_from_provider(
    q: Dict[str, Any],
    *,
    target_dang: Any = "",
    mode: str = "repair",
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
    extra_anthropic_key: str = "",
) -> Tuple[Dict[str, Any], int, str, str, Dict[str, Any]]:
    """ADMIN: AI khôi phục câu thiếu, trả object để đổ vào form sửa."""
    target = question_repair_target_dang(q, target_dang)
    vision = prepare_question_vision(q)
    img_b64 = vision.get("image_b64", "") if vision.get("vision_ready") else ""
    img_mime = vision.get("image_mime", "") if vision.get("vision_ready") else ""
    vision_meta: Dict[str, Any] = {
        "has_question_image": bool(vision.get("has_image")),
        "vision_used": bool(img_b64),
        "vision_model": "",
        "image_src": vision.get("image_src", ""),
        "image_fetch_error": vision.get("fetch_error", ""),
    }
    sys_prompt = (
        "Bạn là giáo viên ra đề và kiểm định đề THPT. "
        "Bạn khôi phục câu bị thiếu rất cẩn thận, không nhầm loại câu. "
        "Chỉ trả JSON hợp lệ, không markdown."
    )
    user_prompt = build_ai_repair_question_prompt(q, target, mode=mode)
    if img_b64:
        user_prompt += "\n\nCó ảnh minh họa kèm theo: hãy đọc ảnh để bổ sung dữ kiện/phương án/lời giải nếu cần."

    def postprocess(raw: str) -> Dict[str, Any]:
        obj = _extract_ai_json_object(raw)
        if not obj:
            raise RuntimeError("AI không trả JSON hợp lệ để khôi phục câu.")
        return _coerce_ai_question_result(q, obj, target_dang=target)

    txt, prov, model, ki = admin_ai_call_text(
        sys_prompt,
        user_prompt,
        max_tokens=2600,
        temp=0.08,
        timeout=45,
        force_provider=force_provider,
        allow_gpt_fallback=allow_gpt_fallback,
        extra_anthropic_key=extra_anthropic_key,
        image_b64=img_b64,
        image_mime=img_mime,
    )
    if not txt:
        raise RuntimeError("AI chưa khôi phục được câu: không có phản hồi.")
    if img_b64 and model:
        vision_meta["vision_model"] = model
    out = postprocess(txt)
    out["target_dang"] = target
    out["missing_before"] = question_missing_report(q, target)
    return out, ki, prov, "", vision_meta

def ai_rewrite_latex_text(
    field: str,
    text: str,
    context: Dict[str, Any],
    *,
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
    extra_anthropic_key: str = "",
) -> Tuple[str, str]:
    """ADMIN: dùng AI viết lại nội dung cho đúng LaTeX, không tự lưu Sheet."""
    field = clean(field)
    text = clean(text)
    if not text:
        raise RuntimeError("Nội dung đang trống.")

    mon = clean(context.get("Mon", ""))
    lop = clean(context.get("Lop", ""))
    chuong = clean(context.get("Chuong", ""))
    baihoc = clean(context.get("BaiHoc", ""))
    dang = clean(context.get("Dang", ""))
    mucdo = clean(context.get("MucDo", ""))

    sys_prompt = (
        "Bạn là giáo viên Việt Nam chuyên chuẩn hóa đề kiểm tra sang LaTeX. "
        "Chỉ trả về NỘI DUNG ĐÃ SỬA, không giải thích, không markdown, không ```."
    )

    user_prompt = "\n".join([
        "Hãy viết lại nội dung sau cho đúng tiếng Việt và đúng LaTeX.",
        "",
        "YÊU CẦU BẮT BUỘC:",
        "- Giữ nguyên ý nghĩa đề, không tự đổi môn, không tự đổi số liệu.",
        "- Sửa lỗi LaTeX bị vỡ như $\\{(V)$_{1}}$ thành $V_1$, $\\{(p)$_{1}}$ thành $p_1$.",
        "- Công thức viết trong $...$.",
        "- Đơn vị viết dạng $\\mathrm{m^3}$, $\\mathrm{Pa}$, $^\\circ\\mathrm{C}$ nếu cần.",
        "- Không thêm lời giải, không thêm đáp án, không thêm phương án nếu văn bản gốc không có.",
        "- Không dùng $$...$$ trong câu hỏi ngắn; chỉ dùng $...$.",
        "- Chỉ trả về đoạn văn đã sửa.",
        "",
        f"Trường đang sửa: {field}",
        f"Môn: {mon}",
        f"Lớp: {lop}",
        f"Chương: {chuong}",
        f"Bài học: {baihoc}",
        f"Dạng: {dang}",
        f"Mức độ: {mucdo}",
        "",
        "NỘI DUNG GỐC:",
        text,
    ])

    def postprocess(s: str) -> str:
        s = clean(s)
        s = re.sub(r"^```(?:latex|tex|text)?", "", s, flags=re.I).strip()
        s = re.sub(r"```$", "", s).strip()
        return normalize_latex_light(s)

    txt, prov, _model, _ki = admin_ai_call_text(
        sys_prompt,
        user_prompt,
        max_tokens=900,
        temp=0.05,
        timeout=35,
        force_provider=force_provider,
        allow_gpt_fallback=allow_gpt_fallback,
        extra_anthropic_key=extra_anthropic_key,
    )
    out = postprocess(txt)
    if not out:
        raise RuntimeError("AI chưa sửa được nội dung.")
    return out, prov


def _extract_numeric_literals(text: str) -> List[str]:
    """Trích số để kiểm tra AI có giữ số liệu gốc."""
    t = clean(text)
    found: List[str] = []
    for m in re.finditer(r"\d+(?:[.,]\d+)?(?:\s*[×x*]\s*10\s*\^?\s*[-+]?\d+)?", t):
        v = m.group(0).strip()
        if v and v not in found:
            found.append(v)
    return found


def ai_recontext_debai_text(
    text: str,
    context: Dict[str, Any],
    *,
    field: str = "CauHoi",
    theme_hint: str = "",
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
    extra_anthropic_key: str = "",
) -> Tuple[str, str, List[str]]:
    """ADMIN: đổi bối cảnh/ngữ liệu đề bài hoặc phương án — giữ nguyên số liệu."""
    text = clean(text)
    if not text:
        raise RuntimeError("Nội dung đang trống.")

    field = clean(field) or "CauHoi"
    if field not in ("CauHoi", "A", "B", "C", "D"):
        raise RuntimeError("Chỉ hỗ trợ CauHoi và phương án A–D.")

    mon = clean(context.get("Mon", ""))
    lop = clean(context.get("Lop", ""))
    chuong = clean(context.get("Chuong", ""))
    baihoc = clean(context.get("BaiHoc", ""))
    dang = clean(context.get("Dang", ""))
    mucdo = clean(context.get("MucDo", ""))
    cau_hoi = clean(context.get("CauHoi", ""))
    theme = clean(theme_hint)

    is_option = field in ("A", "B", "C", "D")
    field_label = f"Phương án {field}" if is_option else "Câu hỏi (K)"

    sys_prompt = (
        "Bạn là giáo viên Vật lý Việt Nam, chuyên viết lại đề/ phương án với ngữ liệu/bối cảnh mới "
        "nhưng giữ nguyên toàn bộ số liệu và cấu trúc toán. "
        f"Chỉ trả về {field_label.upper()} MỚI, không giải thích, không markdown, không ```."
    )

    theme_line = (
        f"- Gợi ý ngữ liệu/bối cảnh mới: {theme}."
        if theme
        else "- Tự chọn bối cảnh mới phù hợp môn Vật lý (vật rơi, xe, mạch điện, thể thao…), khác hẳn bản gốc."
    )

    task_line = (
        f"Viết lại {field_label} sau với NGỮ LIỆU / BỐI CẢNH / CÁCH DIỄN ĐẠT KHÁC."
        if is_option
        else "Viết lại ĐỀ BÀI sau với NGỮ LIỆU / BỐI CẢNH / CÂU CHUYỆN KHÁC (đối tượng, tình huống, động từ mô tả…)."
    )

    user_prompt_parts = [
        task_line,
        "",
        "YÊU CẦU BẮT BUỘC — GIỮ NGUYÊN 100%:",
        "- Mọi con số, hệ số, sai số, khoảng thời gian, khoảng cách, khối lượng, vận tốc…",
        "- Mọi công thức LaTeX ($...$, \\[...\\]) và biểu thức toán.",
        "- Tên điểm, vectơ, biến vật lý (A, B, C, O, M, N, v, a, F, I, U…).",
        "- Quan hệ hình học / vật lý (trung điểm, song song, vuông góc, cùng chiều…).",
        "- Đơn vị (cm, m, s, kg, N, V, A, Ω, J, W…).",
    ]
    if not is_option:
        user_prompt_parts.append("- Yêu cầu / câu hỏi cuối (nếu có) — không đổi ý hỏi.")
    else:
        user_prompt_parts.extend([
            "- Ý nghĩa vật lý / mệnh đề của phương án (đúng/sai, giá trị, khẳng định…) — không đổi.",
            "- Phương án phải nhất quán ngữ liệu với đề bài (nếu có đề bài bên dưới).",
        ])

    user_prompt_parts.extend([
        "",
        "ĐƯỢC PHÉP ĐỔI:",
        "- Nhân vật / vật thể (kiến → xe, hòn bi → quả bóng…).",
        "- Bối cảnh, động từ, cách diễn đạt tiếng Việt.",
        theme_line,
        "",
        "KHÔNG:",
        "- Không thêm tiền tố A. B. C. D. ở đầu.",
        "- Không thêm phương án khác, không thêm lời giải, không thêm số liệu mới.",
        "- Không đổi môn học, không làm sai LaTeX.",
        "",
        f"Trường: {field_label}",
        f"Môn: {mon}",
        f"Lớp: {lop}",
        f"Chương: {chuong}",
        f"Bài học: {baihoc}",
        f"Dạng: {dang}",
        f"Mức độ: {mucdo}",
    ])
    if is_option and cau_hoi:
        user_prompt_parts.extend(["", "ĐỀ BÀI HIỆN TẠI (để đồng bộ ngữ liệu):", cau_hoi])
    user_prompt_parts.extend(["", f"{field_label.upper()} GỐC:", text])
    user_prompt = "\n".join(user_prompt_parts)

    def postprocess(s: str) -> str:
        s = clean(s)
        s = re.sub(r"^```(?:latex|tex|text)?", "", s, flags=re.I).strip()
        s = re.sub(r"```$", "", s).strip()
        if is_option:
            s = re.sub(rf"^(?:Phương án|Phuong an|P\.?\s*)?{re.escape(field)}\s*[.)]\s*", "", s, flags=re.I).strip()
        else:
            s = re.sub(r"^(?:Đề bài|De bai|Câu hỏi|Cau hoi)\s*[:：]\s*", "", s, flags=re.I).strip()
        return normalize_latex_light(s)

    txt, prov, _model, _ki = admin_ai_call_text(
        sys_prompt,
        user_prompt,
        max_tokens=900,
        temp=0.35,
        timeout=40,
        force_provider=force_provider,
        allow_gpt_fallback=allow_gpt_fallback,
        extra_anthropic_key=extra_anthropic_key,
    )
    out = postprocess(txt)
    if not out:
        raise RuntimeError("AI chưa tạo được đề mới.")

    missing_nums: List[str] = []
    for num in _extract_numeric_literals(text):
        alt = num.replace(",", ".")
        if num not in out and alt not in out:
            missing_nums.append(num)
    return out, prov, missing_nums


def ai_admin_fix_loigiai(
    text: str,
    context: Dict[str, Any],
    *,
    format_mode: str = "auto",
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
    extra_anthropic_key: str = "",
) -> Tuple[str, str]:
    """ADMIN: chỉnh lại lời giải theo dạng TN / Đ-S / TLN."""
    text = clean(text)
    generating = not text
    if generating:
        if not clean(context.get("CauHoi", "")):
            raise RuntimeError("Chưa có đề bài để viết lời giải.")
        text = "(chưa có lời giải)"

    fmt = clean(format_mode).lower() or "auto"
    dang_eff = effective_dang(context)
    if fmt == "auto":
        if dang_eff == "Đúng sai":
            fmt = "ds"
        elif dang_eff == "Trả lời ngắn":
            fmt = "tln"
        else:
            fmt = "tn"
    if fmt not in ("tn", "ds", "tln"):
        fmt = "tn"

    fmt_rules = {
        "tn": "\n".join([
            "ĐỊNH DẠNG TRẮC NGHIỆM:",
            "- Lời giải là MỘT bài giải liền mạch: dữ kiện → công thức → thay số → kết luận.",
            "- CHỈ giải thích vì sao phương án đúng (cột P) thỏa yêu cầu câu hỏi.",
            "- KHÔNG liệt kê A/B/C/D; KHÔNG phân tích riêng từng phương án sai; KHÔNG dùng «Đúng»/«Sai» từng ý.",
            "- TUYỆT ĐỐI KHÔNG viết «Chọn A», «Chọn B», «Chọn C», «Chọn D», «Đáp án A/B/C/D» — đề bị TRỘN phương án nên chữ cái sẽ SAI.",
            "- Kết luận bằng nội dung vật lý/toán (công thức, kết quả, ý đúng), không nêu chữ cái phương án.",
        ]),
        "ds": "\n".join([
            "ĐỊNH DẠNG ĐÚNG/SAI:",
            "- Bắt buộc đủ 4 dòng A. B. C. D. — giải thích TỪNG ý/mệnh đề.",
            "- Mỗi dòng: «A. Đúng — …» hoặc «A. Sai — …» (hoặc tương đương).",
            "- Có thể có 1–2 dòng diễn giải chung TRƯỚC block A/B/C/D.",
            "- Khớp đáp án cột P dạng A=Đ · B=S …",
        ]),
        "tln": "\n".join([
            "ĐỊNH DẠNG TRẢ LỜI NGẮN:",
            "- Lời giải gọn: dữ kiện → công thức → thay số → kết quả.",
            "- Dòng cuối ghi đáp số cuối cùng (khớp cột P), có đơn vị nếu cần.",
            "- Không dùng format A/B/C/D.",
        ]),
    }

    cfg = ai_runtime_config()
    openai_keys = load_ai_keys("OPENAI")
    gemini_keys = load_ai_keys("GEMINI")
    gemini_saw_quota = False

    mon = clean(context.get("Mon", ""))
    lop = clean(context.get("Lop", ""))
    chuong = clean(context.get("Chuong", ""))
    baihoc = clean(context.get("BaiHoc", ""))
    dang = clean(context.get("Dang", ""))
    mucdo = clean(context.get("MucDo", ""))
    dapan = clean(context.get("DapAn", ""))
    cauhoi = clean(context.get("CauHoi", ""))[:1200]
    ds_stmts = []
    for L in "ABCD":
        stmt = clean(context.get(L, ""))
        if stmt:
            ds_stmts.append(f"{L}. {stmt[:500]}")

    sys_prompt = (
        "Bạn là giáo viên Việt Nam chuyên soát và viết lời giải đề THPT. "
        "Chỉ trả về LỜI GIẢI, không giải thích meta, không markdown, không ```."
    )

    user_prompt_lines = [
        (
            "Lời giải đang trống. Hãy VIẾT MỚI lời giải đầy đủ, đúng tiếng Việt, đúng LaTeX, đúng định dạng dạng bài. "
            "KHÔNG viết «Chọn A/B/C/D» vì đề sẽ bị trộn phương án."
            if generating
            else "Chỉnh lại lời giải sau cho đúng tiếng Việt, đúng LaTeX và đúng định dạng dạng bài."
        ),
        "",
        fmt_rules.get(fmt, fmt_rules["tn"]),
        "",
        "YÊU CẦU CHUNG:",
        "- Giữ nguyên ý và kết quả toán học, không tự đổi đáp án.",
        "- Công thức trong $...$; đơn vị $\\mathrm{m^3}$, $\\mathrm{Pa}$.",
        "- Chỉ trả về lời giải đã chỉnh.",
        *(
            [
                "- Với TN: CẤM mọi cụm «Chọn A/B/C/D» / «Đáp án A» — kết luận bằng ý đúng, không bằng chữ cái (đề bị trộn)."
            ]
            if fmt == "tn"
            else []
        ),
        "",
        f"Môn: {mon}",
        f"Lớp: {lop}",
        f"Dạng (J): {dang}",
        (
            f"Đáp án (P) — chỉ nội bộ, CẤM in chữ cái ra lời giải: {dapan or '(chưa có)'}"
            if fmt == "tn"
            else f"Đáp án (P): {dapan or '(chưa có)'}"
        ),
        "",
        "CÂU HỎI (tham chiếu):",
        cauhoi or "(trống)",
    ]
    if ds_stmts and fmt == "ds":
        user_prompt_lines.extend(["", "MỆNH ĐỀ A–D:", *ds_stmts])
    if fmt == "tn":
        corr_L = norm_letter(dapan)
        corr_txt = clean(context.get(corr_L, ""))[:500] if corr_L else ""
        if corr_txt:
            user_prompt_lines.extend(
                [
                    "",
                    "NỘI DUNG Ý ĐÚNG (giải thích ý này; không viết chữ A/B/C/D):",
                    corr_txt,
                ]
            )
    user_prompt_lines.extend([
        "",
        "LỜI GIẢI GỐC:",
        text,
    ])
    user_prompt = "\n".join(user_prompt_lines)

    model_openai = clean(cfg.get("openai_admin_model") or cfg.get("openai_model") or DEFAULT_OPENAI_ADMIN_MODEL)
    model_gemini = clean(cfg.get("gemini_model") or os.environ.get("GEMINI_HINT_MODEL", DEFAULT_GEMINI_HINT_MODEL)) or DEFAULT_GEMINI_HINT_MODEL
    last_error = ""

    def postprocess(s: str) -> str:
        s = clean(s)
        s = re.sub(r"^```(?:latex|tex|text)?", "", s, flags=re.I).strip()
        s = re.sub(r"```$", "", s).strip()
        s = normalize_latex_light(s)
        if fmt == "tn":
            s = _strip_tn_loigiai_choice_letters(_strip_tn_loigiai_ds_lines(s, dapan))
        elif fmt == "ds" and context:
            try:
                s = normalize_ds_loigiai(
                    s, context, use_sheet_dapan=looks_like_dungsai_answer(dapan)
                )
            except Exception:
                log_swallow("ai_admin_fix_loigiai:13812")
                pass
        return s

    def try_openai() -> Tuple[str, str]:
        nonlocal last_error
        for api_key in openai_keys:
            txt, finish, err = _openai_chat_call(
                api_key,
                model_openai,
                sys_prompt,
                user_prompt,
                1200,
                0.08,
                timeout=45,
            )
            if txt:
                return postprocess(txt), "OPENAI"
            last_error = err
        return "", "OPENAI"

    def try_gemini() -> Tuple[str, str]:
        nonlocal last_error, gemini_saw_quota
        models = [model_gemini] + [m for m in GEMINI_HINT_MODEL_FALLBACKS if m != model_gemini]
        for api_key in gemini_keys:
            for gmodel in models:
                txt, finish, err = _gemini_hint_call(
                    api_key,
                    gmodel,
                    sys_prompt,
                    user_prompt,
                    1200,
                    0.08,
                    timeout=45,
                )
                if txt:
                    return postprocess(txt), "GEMINI"
                last_error = err
                if _is_quota_or_rate_error(err):
                    gemini_saw_quota = True
        return "", "GEMINI"

    def try_anthropic() -> Tuple[str, str]:
        nonlocal last_error
        model_anthropic = (
            clean(os.environ.get("ANTHROPIC_ADMIN_MODEL", DEFAULT_ANTHROPIC_ADMIN_MODEL))
            or DEFAULT_ANTHROPIC_ADMIN_MODEL
        )
        for api_key in _admin_anthropic_keys(extra_anthropic_key):
            txt, finish, err = _anthropic_chat_call(
                api_key, model_anthropic, sys_prompt, user_prompt, 1200, 0.08, timeout=45
            )
            if txt:
                return postprocess(txt), "ANTHROPIC"
            last_error = err
        return "", "ANTHROPIC"

    fp = admin_ai_resolve_force(force_provider)
    if fp == "ANTHROPIC":
        out, used = try_anthropic()
        if not out:
            out, used = try_gemini()
        if not out and allow_gpt_fallback and openai_keys:
            out, used = try_openai()
    elif fp == "OPENAI":
        out, used = try_openai()
    else:
        out, used = try_gemini()
        if not out:
            if gemini_saw_quota and openai_keys and not allow_gpt_fallback:
                raise AdminGeminiQuotaError(last_error, openai_available=True)
            if allow_gpt_fallback:
                if _admin_anthropic_keys(extra_anthropic_key):
                    out, used = try_anthropic()
                if not out and openai_keys:
                    out, used = try_openai()

    if not out:
        raise RuntimeError("AI chưa chỉnh được lời giải: " + (last_error or "không có phản hồi."))

    return out, used


def _quiz_abcd_analysis_rules(context: Dict[str, Any], *, spoken: bool = False) -> str:
    """Bắt AI phân tích từng ý A/B/C/D đúng như đề đang hiện trên màn hình."""
    ctx = dict(context or {})
    dang = clean(ctx.get("Dang", "")) or clean(effective_dang(ctx))
    letters = [L for L in "ABCD" if clean(ctx.get(L, ""))]
    if not letters:
        return ""
    n = len(letters)
    sample = []
    for L in letters:
        if dang == "Đúng sai":
            sample.append(f"Ý {L} là: Đúng/Sai — giải thích mệnh đề {L}.")
        else:
            sample.append(f"Ý {L} là: tóm tắt phương án {L} — đúng hoặc sai vì …")
    if spoken:
        if dang == "Đúng sai":
            return (
                f"BẮT BUỘC đọc đủ {n} ý, đúng chữ đang hiện trên đề. "
                "Mỗi ý một cụm: «Ý A là đúng vì …». Rồi ý B, ý C, ý D. "
                "Chữ A/B/C/D phải khớp phương án gửi kèm, không đổi chỗ."
            )
        return (
            f"BẮT BUỘC đọc đủ {n} ý. Mỗi ý: «Ý A là … — đúng/sai vì …». "
            "Rồi ý B, ý C, ý D. Chữ cái khớp phương án trên màn hình."
        )
    head = (
        f"BẮT BUỘC đủ {n} dòng, đúng thứ tự chữ trên đề học sinh đang nhìn "
        "(A/B/C/D dưới đây đã khớp màn hình). Mỗi dòng mở đầu đúng cụm «Ý X là:». "
        "Không gộp hai ý một dòng. Không bỏ ý."
    )
    if dang == "Đúng sai":
        extra = "Với Đúng/Sai: sau «Ý A là:» ghi Đúng hoặc Sai, rồi giải thích mệnh đề đó."
    else:
        extra = (
            "Với trắc nghiệm: sau «Ý A là:» nêu nội dung ý đó rồi kết luận đúng/sai vì sao. "
            "Chốt phương án đúng bằng nội dung, vẫn gắn đúng chữ đang hiện."
        )
    return "\n".join([head, extra, *sample])


def _plain_quiz_speak_talk(s: str) -> str:
    s = clean(s)
    s = re.sub(r"^```(?:\w+)?", "", s, flags=re.I).strip()
    s = re.sub(r"```\s*$", "", s).strip()
    s = s.replace("$", " ")
    s = re.sub(r"\\[a-zA-Z]+", " ", s)
    s = re.sub(r"[*_#>`]+", " ", s)
    s = re.sub(r"\s+", " ", s).strip()
    return s


def ai_quiz_speak_talk(
    context: Dict[str, Any],
    *,
    spoil: bool = False,
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
    extra_anthropic_key: str = "",
) -> Tuple[str, str]:
    """Đoạn nói chuyện ngắn để TTS đọc — không phải lời giải Sheet."""
    ctx = dict(context or {})
    cauhoi = clean(ctx.get("CauHoi", ""))[:1400]
    if not cauhoi:
        raise RuntimeError("Chưa có đề bài để thảo luận.")
    dang = clean(ctx.get("Dang", "")) or clean(effective_dang(ctx))
    mon = clean(ctx.get("Mon", ""))
    lop = clean(ctx.get("Lop", ""))
    mucdo = clean(ctx.get("MucDo", ""))
    opts = []
    for L in "ABCD":
        stmt = clean(ctx.get(L, ""))
        if stmt:
            opts.append(f"{L}. {stmt[:400]}")
    loigiai = clean(ctx.get("LoiGiai", ""))[:900] if spoil else ""
    dapan = clean(ctx.get("DapAn", ""))[:200] if spoil else ""

    sys_prompt = (
        "Bạn là giáo viên THPT Việt Nam đang nói chuyện trực tiếp với học sinh. "
        "Viết đoạn ĐỌC THÀNH TIẾNG: thân thiện, rõ ràng. "
        "Chỉ tiếng Việt. Không markdown, không ký hiệu LaTeX, không dấu $. "
        "Công thức viết bằng lời. Không chào dài. "
        "Nếu đề có A B C D: đọc lần lượt «Ý A là …», «Ý B là …», «Ý C là …», «Ý D là …»."
    )
    user_lines = [
        f"Môn: {mon or 'Vật lý / Toán'} · Lớp: {lop or '?'} · Dạng: {dang or '?'} · Mức: {mucdo or '?'}",
        "",
        "ĐỀ BÀI:",
        cauhoi,
    ]
    if opts:
        user_lines.extend(["", "PHƯƠNG ÁN (đúng như màn hình đang hiện):", *opts])
    abcd_rules = _quiz_abcd_analysis_rules(ctx, spoken=True)
    if spoil:
        user_lines.extend(
            [
                "",
                "ĐÃ ĐƯỢC XEM ĐÁP ÁN. Phân tích rõ từng ý rồi mới chốt.",
            ]
        )
        if abcd_rules:
            user_lines.extend(["", abcd_rules])
        if dapan:
            user_lines.extend(["Đáp án cột P (khớp chữ đang hiện trên đề):", dapan])
        if loigiai:
            user_lines.extend(["Lời giải Sheet (diễn đạt lại bằng lời nói, vẫn bám từng ý A–D):", loigiai])
    else:
        user_lines.extend(
            [
                "",
                "Học sinh CHƯA xem đáp án. Gợi ý dữ kiện, hướng nghĩ, bẫy thường gặp. "
                "TUYỆT ĐỐI KHÔNG nêu đáp án, KHÔNG kết luận phương án nào đúng/sai.",
            ]
        )
    user_prompt = "\n".join(user_lines)

    cfg = ai_runtime_config()
    openai_keys = load_ai_keys("OPENAI")
    gemini_keys = load_ai_keys("GEMINI")
    gemini_saw_quota = False
    model_openai = clean(
        cfg.get("openai_admin_model") or cfg.get("openai_model") or DEFAULT_OPENAI_ADMIN_MODEL
    )
    model_gemini = (
        clean(cfg.get("gemini_model") or os.environ.get("GEMINI_HINT_MODEL", DEFAULT_GEMINI_HINT_MODEL))
        or DEFAULT_GEMINI_HINT_MODEL
    )
    last_error = ""

    def try_openai() -> Tuple[str, str]:
        nonlocal last_error
        for api_key in openai_keys:
            txt, finish, err = _openai_chat_call(
                api_key, model_openai, sys_prompt, user_prompt, 900, 0.4, timeout=28
            )
            if txt:
                return _plain_quiz_speak_talk(txt), "OPENAI"
            last_error = err
        return "", "OPENAI"

    def try_gemini() -> Tuple[str, str]:
        nonlocal last_error, gemini_saw_quota
        models = [model_gemini] + [m for m in GEMINI_HINT_MODEL_FALLBACKS if m != model_gemini]
        for api_key in gemini_keys:
            for gmodel in models:
                txt, finish, err = _gemini_hint_call(
                    api_key, gmodel, sys_prompt, user_prompt, 900, 0.4, timeout=22
                )
                if txt:
                    return _plain_quiz_speak_talk(txt), "GEMINI"
                last_error = err
                if _is_quota_or_rate_error(err):
                    gemini_saw_quota = True
        return "", "GEMINI"

    def try_anthropic() -> Tuple[str, str]:
        nonlocal last_error
        model_anthropic = (
            clean(os.environ.get("ANTHROPIC_ADMIN_MODEL", DEFAULT_ANTHROPIC_ADMIN_MODEL))
            or DEFAULT_ANTHROPIC_ADMIN_MODEL
        )
        for api_key in _admin_anthropic_keys(extra_anthropic_key):
            txt, finish, err = _anthropic_chat_call(
                api_key, model_anthropic, sys_prompt, user_prompt, 900, 0.4, timeout=28
            )
            if txt:
                return _plain_quiz_speak_talk(txt), "ANTHROPIC"
            last_error = err
        return "", "ANTHROPIC"

    fp = admin_ai_resolve_force(force_provider)
    if fp == "ANTHROPIC":
        out, used = try_anthropic()
        if not out:
            out, used = try_gemini()
        if not out and allow_gpt_fallback and openai_keys:
            out, used = try_openai()
    elif fp == "OPENAI":
        out, used = try_openai()
    else:
        out, used = try_gemini()
        if not out:
            if gemini_saw_quota and openai_keys and not allow_gpt_fallback:
                raise AdminGeminiQuotaError(last_error, openai_available=True)
            if allow_gpt_fallback:
                if _admin_anthropic_keys(extra_anthropic_key):
                    out, used = try_anthropic()
                if not out and openai_keys:
                    out, used = try_openai()

    if not out:
        raise RuntimeError("AI chưa soạn được đoạn thảo luận: " + (last_error or "không có phản hồi."))
    return out, used


def _quiz_debate_plain(s: str) -> str:
    s = clean(s)
    s = re.sub(r"^```(?:\w+)?", "", s, flags=re.I).strip()
    s = re.sub(r"```\s*$", "", s).strip()
    s = re.sub(r"\s+\n", "\n", s)

    def _compact_math(x: str) -> str:
        return re.sub(r"\s+", "", x or "")

    def _same_math(a: str, b: str) -> bool:
        ca, cb = _compact_math(a), _compact_math(b)
        return bool(ca) and ca == cb

    def _collapse_dup_math(m: re.Match) -> str:
        a, b = m.group(1), m.group(2)
        if _same_math(a, b):
            return f"${a}$"
        return m.group(0)

    # $A$$A$ / $A$ $A$
    s = re.sub(r"\$([^$\n]{1,160})\$\s*\$([^$\n]{1,160})\$", _collapse_dup_math, s)
    # $A$A  (bản chữ dính ngay sau)
    s = re.sub(
        r"\$([^$\n]{1,160})\$\s*\1(?=\s|[',.;:)\]\n]|$)",
        r"$\1$",
        s,
    )
    s = re.sub(r"\$([^$\n]{1,160})\$\1", r"$\1$", s)

    # $1 + 2 = 3$1+2=3  (khác khoảng trắng)
    out: List[str] = []
    i, n = 0, len(s)
    while i < n:
        if s[i] != "$":
            out.append(s[i])
            i += 1
            continue
        j = s.find("$", i + 1)
        if j < 0 or "\n" in s[i + 1 : j]:
            out.append(s[i])
            i += 1
            continue
        inner = s[i + 1 : j]
        k = j + 1
        while k < n and s[k] in " \t":
            k += 1
        compact = _compact_math(inner)
        p, ci, ok = k, 0, bool(compact)
        while ok and ci < len(compact) and p < n:
            if s[p] in " \t":
                p += 1
                continue
            if s[p] != compact[ci]:
                ok = False
                break
            p += 1
            ci += 1
        if ok and ci == len(compact) and (p >= n or not (s[p].isalnum() or s[p] in "\\{}^_")):
            out.append(f"${inner}$")
            i = p
            continue
        out.append(f"${inner}$")
        i = j + 1
    s = "".join(out)

    # "1 + 2 = 3" dính "1 + 2 = 3" → "1 + 2 = 31 + 2 = 3"
    s = re.sub(
        r"([A-Za-z0-9\\{}^_+\-*/\s]{1,40}=\s*)([A-Za-z0-9\\{}]{1,24})\1\2",
        r"\1\2",
        s,
    )
    return s.strip()


def _quiz_debate_hook_rules(kind: str) -> str:
    """Bám sát đề + nêu công thức. kind: debate | chat | script."""
    k = clean(kind).lower()
    if k == "chat":
        return (
            "BÁM SÁT ĐỀ VÀ NÊU CÔNG THỨC (mỗi lượt, trừ khi em nói hết thắc mắc):\n"
            "1) Ý em: tóm tắt 1 câu.\n"
            "2) Kết luận in rõ: ĐÚNG. hoặc SAI. hoặc ĐÚNG MỘT PHẦN.\n"
            "3) Nhắc đúng 1 cụm chữ hoặc số liệu lấy nguyên từ ĐỀ BÀI / PHƯƠNG ÁN đang hiện.\n"
            "4) Nêu công thức/định luật/tính chất mà CÂU NÀY dùng, bọc $...$ "
            "(ví dụ $F=ma$, $U=IR$, $W=\\vec{F}\\cdot\\vec{s}$). Giải thích đại lượng nào đề cho, đại lượng nào cần tìm.\n"
            "5) Dẫn chứng 2–4 ý: đề / phương án A–D / đáp án / lời giải / công thức vừa nêu. Không giảng bài chương khác, không lấy ví dụ ngoài đề.\n"
            "Nếu em hỏi lan man: kéo về câu này, vẫn nêu công thức của bài. Không bịa số liệu."
        )
    if k == "script":
        return (
            "Kịch bản LỚP HỌC KÍCH THÍCH, khoảng 2 phút, 10–16 câu thoại:\n"
            "- An đọc đề, nhấn số liệu then chốt (không bỏ số, đơn vị, điều kiện).\n"
            "- Nếu có A/B/C/D: An, Bình, Chi, Dũng lần lượt đọc 4 phương án (đúng chữ nguồn).\n"
            "- BẮT BUỘC tranh luận: một em chọn bẫy (công thức sai / gần đúng / quên điều kiện), một em phản. Không ai chỉ gật đồng ý.\n"
            "- Ít nhất 2 lượt NÊU TÊN CÔNG THỨC bằng tiếng Việt nói được "
            "(vd: «F bằng m a», «U bằng I nhân R», «công bằng lực nhân độ dịch chuyển nhân cosin alpha»). "
            "Không đọc lệnh LaTeX như frac, vec, mathbb.\n"
            "- Mỗi ý kiến phải neo vào một số liệu hoặc điều kiện trên đề — không bàn chuyện chung.\n"
            "- Thầy Minh hỏi Socratic 1 câu (công thức nào khớp dữ kiện đề?), rồi chốt: công thức đúng + thay số đề + đáp án. "
            "Nếu nguồn mâu thuẫn/sai thì nói thẳng.\n"
            "- Giọng lớp thật: ngạc nhiên, phản biện, có nhịp; không diễn văn, không tiết lộ đáp án quá sớm."
        )
    return (
        "BÁM SÁT ĐỀ: mọi nhận xét dùng số liệu, ký hiệu, điều kiện trong ĐỀ BÀI và PHƯƠNG ÁN gửi kèm. "
        "Không giảng bài chung, không lấy ví dụ khác, không bịa hằng số.\n"
        "CÔNG THỨC: nêu đúng công thức/định luật/tính chất mà CÂU NÀY dùng, bọc $...$. "
        "Chỉ rõ đại lượng nào đề cho sẵn, đại lượng nào cần tìm. "
        "Nếu lời giải thiếu/sai công thức: chỉ ra, viết công thức đúng, rồi đối chiếu số liệu đề."
    )


def _quiz_debate_context_prompt(
    context: Dict[str, Any],
    loigiai: str,
    *,
    role: str,
    peer_name: str = "",
    peer_text: str = "",
) -> Tuple[str, str]:
    ctx = dict(context or {})
    cauhoi = clean(ctx.get("CauHoi", ""))[:1400]
    dang = clean(ctx.get("Dang", "")) or clean(effective_dang(ctx))
    mon = clean(ctx.get("Mon", ""))
    lop = clean(ctx.get("Lop", ""))
    chuong = clean(ctx.get("Chuong", ""))
    baihoc = clean(ctx.get("BaiHoc", ""))
    dapan = clean(ctx.get("DapAn", ""))[:240]
    opts = []
    for L in "ABCD":
        stmt = clean(ctx.get(L, ""))
        if stmt:
            opts.append(f"{L}. {stmt[:400]}")
    branded = clean(role).lower() in {"gemini", "tro ly", "trợ lý", "thay minh"}
    if branded:
        sys_prompt = (
            "Bạn là trợ lý AI của Thầy Minh Vật Lý, đang nói chuyện với học sinh. "
            "Mở đầu đúng 1 câu: «Xin chào em. Mình là trợ lý AI của Thầy Minh Vật Lý.» "
            "Phản biện LỜI GIẢI đã có. Tiếng Việt, rõ từng ý, sư phạm. "
            "Bám sát đề đang gửi: nêu công thức $...$ của đúng bài này, nhận xét theo số liệu/điều kiện trên đề. "
            "Mỗi công thức chỉ viết đúng một lần trong $...$ (MathJax), không lặp lại dạng chữ ngay sau. "
            "Không markdown heading, không ```. "
            "BẮT BUỘC phân tích lần lượt: Ý A là … / Ý B là … / Ý C là … / Ý D là … "
            "đúng chữ đang hiện trên đề (khớp PHƯƠNG ÁN gửi kèm). "
            "Kết thúc đúng câu: «Em còn thắc mắc gì không? Nếu có, hãy hỏi để mình trao đổi tiếp.»"
        )
    else:
        sys_prompt = (
            f"Bạn là {role}, giáo viên THPT Việt Nam. "
            "Phản biện LỜI GIẢI đã có. Tiếng Việt, rõ từng ý. "
            "Bám sát đề đang gửi: nêu công thức $...$ của đúng bài này, nhận xét theo số liệu/điều kiện trên đề. "
            "Mỗi công thức chỉ viết ĐÚNG MỘT LẦN, bọc $...$ để MathJax hiện (ví dụ $F=ma$, $\\mathbb{R}$). "
            "Không viết lại dạng chữ ngay sau. Không dùng \\[ \\] hay \\( \\). "
            "Không markdown heading, không ```. "
            "BẮT BUỘC phân tích lần lượt: Ý A là … / Ý B là … / Ý C là … / Ý D là … "
            "đúng chữ đang hiện trên đề (khớp PHƯƠNG ÁN gửi kèm)."
        )
    lines = [
        f"Môn: {mon or '?'} · Lớp: {lop or '?'} · Dạng: {dang or '?'}",
        f"Chương: {chuong or '?'} · Bài: {baihoc or '?'}",
        "",
        "ĐỀ BÀI (bám sát từng số liệu/điều kiện dưới đây):",
        cauhoi or "(trống)",
    ]
    if opts:
        lines.extend(["", "PHƯƠNG ÁN (đúng như màn hình đang hiện — phân tích theo đúng chữ này):", *opts])
    if dapan:
        lines.extend(["", "ĐÁP ÁN (khớp chữ đang hiện trên đề):", dapan])
    lines.extend(["", "LỜI GIẢI CẦN PHẢN BIỆN:", loigiai or "(trống)"])
    abcd_rules = _quiz_abcd_analysis_rules(ctx, spoken=False)
    if peer_text:
        lines.extend(
            [
                "",
                f"PHẢN BIỆN CỦA {peer_name}:",
                peer_text[:1200],
                "",
                "Hãy đáp lại đồng nghiệp: đồng ý chỗ nào, bác chỗ nào, bổ sung 1–3 ý. "
                "Khoảng 80–140 chữ. Không lặp lại nguyên văn lời giải.",
            ]
        )
        sys_prompt += " Đây là lượt đáp lại đồng nghiệp."
    else:
        lines.extend(
            [
                "",
                abcd_rules or "Phân tích lời giải: đúng/sai chỗ nào, bước thiếu, cách trình bày.",
                _quiz_debate_hook_rules("debate"),
                "Sau 4 ý (nếu có), thêm 1–3 câu nhận xét lời giải Sheet: thiếu bước / đã đủ / cần chặt hơn — luôn gắn số liệu đề.",
            ]
        )
    return sys_prompt, "\n".join(lines)


def _quiz_source_block(context: Dict[str, Any], loigiai: str) -> str:
    """Gói 1 câu đang mở — không gửi cả đề / cả file .tex."""
    ctx = dict(context or {})
    cauhoi = clean(ctx.get("CauHoi", ""))[:1400]
    dang = clean(ctx.get("Dang", "")) or clean(effective_dang(ctx))
    mon = clean(ctx.get("Mon", ""))
    lop = clean(ctx.get("Lop", ""))
    chuong = clean(ctx.get("Chuong", ""))
    baihoc = clean(ctx.get("BaiHoc", ""))
    dapan = clean(ctx.get("DapAn", ""))[:240]
    opts = []
    for L in "ABCD":
        stmt = clean(ctx.get(L, ""))
        if stmt:
            opts.append(f"{L}. {stmt[:400]}")
    lines = [
        "DỮ LIỆU NGUỒN — KHÔNG ĐƯỢC ÂM THẦM SỬA",
        f"Môn: {mon or '?'} · Lớp: {lop or '?'} · Dạng: {dang or '?'}",
        f"Chương: {chuong or '?'} · Bài: {baihoc or '?'}",
        f"ID: {clean(ctx.get('ID', '')) or 'không có'}",
        "",
        "ĐỀ:",
        cauhoi or "(trống)",
    ]
    if opts:
        lines.extend(["", "PHƯƠNG ÁN/Ý:", *opts])
    lines.extend(["", "ĐÁP ÁN TRÍCH TỪ NGUỒN:", dapan or "—"])
    lines.extend(["", "LỜI GIẢI NGUỒN:", clean(loigiai)[:1800] or "[không có]"])
    lines.append(
        "Lưu ý: nếu nguồn sai/mâu thuẫn, hãy chỉ ra rõ. Không tự thay nguồn rồi giả vờ nguồn ban đầu đúng."
    )
    return "\n".join(lines)


def _quiz_local_class_script(context: Dict[str, Any], loigiai: str, analysis: str = "") -> str:
    """Kịch bản mẫu không API — An/Bình/Chi/Dũng + Thầy Minh, có tranh luận."""
    ctx = dict(context or {})
    q = clean(ctx.get("CauHoi", ""))[:420] or "Đề đang trống."
    dang = clean(ctx.get("Dang", "")) or clean(effective_dang(ctx))
    chuong = clean(ctx.get("Chuong", ""))
    names = ["An", "Bình", "Chi", "Dũng"]
    opts = []
    for L in "ABCD":
        stmt = clean(ctx.get(L, ""))
        if stmt:
            opts.append((L, stmt[:280]))
    lines = [
        f"An: Đề này cho: {q}",
        "Bình: Khoan chọn vội. Dễ bị bẫy nếu áp sai công thức, không khớp số liệu đề.",
    ]
    if opts:
        L0, s0 = opts[0]
        lines.append(f"{names[0]}: Mình nghiêng {L0}: {s0}")
        if len(opts) > 1:
            L1, s1 = opts[1]
            lines.append(f"{names[1]}: Không đồng ý ngay. {L1} cũng nghe có lý: {s1}")
        if len(opts) > 2:
            L2, s2 = opts[2]
            lines.append(
                f"{names[2]}: Hai hướng đó xung đột. {L2}: {s2} — đề đang hỏi gì, công thức nào mới khớp dữ kiện?"
            )
        if len(opts) > 3:
            L3, s3 = opts[3]
            lines.append(f"{names[3]}: Còn {L3}: {s3}. Có thể là nhiễu nếu quên điều kiện trên đề.")
    else:
        lines.append("Chi: Tách dữ kiện đề: cái nào cho sẵn, cái nào cần tìm.")
        lines.append("Dũng: Rồi mới nêu công thức, thay đúng số trên đề.")
    topic = dang or chuong or "bài này"
    lines.append(f"Chi: Dạng {topic} thì công thức xương sống là gì? Đừng nhớ máy móc.")
    if clean(analysis):
        lines.append("Dũng: Phản biện AI vừa chỉ chỗ cần kiểm — nghe Thầy chốt công thức rồi đối chiếu đề.")
    elif clean(loigiai):
        lg = clean(loigiai)[:280]
        lines.append(f"Dũng: Lời giải nguồn viết: {lg}")
    da = clean(ctx.get("DapAn", ""))[:120]
    lines.append(
        "Thầy Minh: Tranh luận tốt. Bám sát đề, nêu đúng công thức của bài, thay đúng số liệu rồi mới kết luận. "
        f"Theo nguồn, đáp án là {da or 'cần đối chiếu lại Sheet'}. "
        "Nếu nguồn lệch đề thì nói thẳng. Đây là draft máy, chưa ghi Sheet."
    )
    return "\n".join(lines)


def ai_quiz_class_script(
    context: Dict[str, Any],
    loigiai: str,
    analysis: str = "",
    *,
    extra_gemini_key: str = "",
    extra_anthropic_key: str = "",
    provider: str = "GEMINI",
) -> Dict[str, str]:
    """Tạo kịch bản lớp học — chỉ trả text, không ghi Sheet."""
    if not clean(context.get("CauHoi", "")):
        raise RuntimeError("Chưa có đề bài.")
    prov = clean(provider or "GEMINI").upper()
    if prov in {"LOCAL", "MAU", "MẪU"}:
        return {"text": _quiz_local_class_script(context, loigiai, analysis), "provider": "LOCAL"}
    source = _quiz_source_block(context, loigiai)
    prompt = (
        "Bạn là biên tập viên kịch bản giảng bài THPT bằng tiếng Việt, giọng lớp thật, có tranh luận.\n\n"
        f"{source}\n\n"
        f"PHÂN TÍCH/PHẢN BIỆN ĐÃ CÓ:\n{clean(analysis)[:3500] or '[không có]'}\n\n"
        f"{_quiz_debate_hook_rules('script')}\n"
        "Chỉ trả về kịch bản với nhãn An:, Bình:, Chi:, Dũng:, Thầy Minh:. Không giải thích ngoài kịch bản."
    )
    sys_p = (
        "Chỉ trả kịch bản thoại tiếng Việt, kích thích, bám sát đề. "
        "Học sinh phải nêu công thức bằng lời. Không markdown, không ```."
    )
    cfg = ai_runtime_config()
    last = ""
    if prov == "ANTHROPIC" and is_admin():
        ant_keys = _debate_anthropic_keys(extra_anthropic_key)
        model_anthropic = (
            clean(os.environ.get("ANTHROPIC_ADMIN_MODEL", DEFAULT_ANTHROPIC_ADMIN_MODEL))
            or DEFAULT_ANTHROPIC_ADMIN_MODEL
        )
        for api_key in ant_keys:
            txt, finish, err = _anthropic_chat_call(
                api_key, model_anthropic, sys_p, prompt, 1800, 0.48, timeout=40
            )
            if txt:
                return {"text": _quiz_debate_plain(txt), "provider": "ANTHROPIC"}
            last = err or finish or last
    gemini_keys = _user_gemini_keys(extra_gemini_key)
    model_gemini = (
        clean(cfg.get("gemini_model") or os.environ.get("GEMINI_HINT_MODEL", DEFAULT_GEMINI_HINT_MODEL))
        or DEFAULT_GEMINI_HINT_MODEL
    )
    models = [model_gemini] + [m for m in GEMINI_HINT_MODEL_FALLBACKS if m != model_gemini]
    for api_key in gemini_keys:
        for gmodel in models:
            txt, finish, err = _gemini_hint_call(
                api_key, gmodel, sys_p, prompt, 1800, 0.48, timeout=40
            )
            if txt:
                return {"text": _quiz_debate_plain(txt), "provider": "GEMINI"}
            last = err or finish or last
    return {"text": _quiz_local_class_script(context, loigiai, analysis), "provider": "LOCAL", "warning": last}



def _quiz_debate_question_from_request(data: Dict[str, Any], idx: int) -> Dict[str, Any]:
    """Lấy câu đang mở từ phiên RAM; nếu hết phiên thì dùng question gọn từ client (không cần cả đề)."""
    sid = clean((data or {}).get("sid"))
    restore = quiz_restore_payload_from_body(data or {})
    body_q = (data or {}).get("question") if isinstance((data or {}).get("question"), dict) else None
    sess_err = None
    try:
        ses = get_store().check_quiz_session(sid, restore)
        qs = ses.get("questions") or []
        if 0 <= idx < len(qs) and qs[idx]:
            return dict(qs[idx])
        sess_err = RuntimeError("Phiên làm bài không khớp câu đang mở.")
    except Exception as e:
        sess_err = e
    if body_q and clean(body_q.get("CauHoi", "")):
        return dict(body_q)
    if sess_err:
        raise sess_err
    raise RuntimeError("Chưa có đề bài.")


def ai_quiz_debate_loigiai(
    context: Dict[str, Any],
    loigiai: str,
    *,
    extra_anthropic_key: str = "",
    extra_gemini_key: str = "",
    force_provider: str = "",
) -> Dict[str, str]:
    """1 bước phản biện. VIP: Gemini. ADMIN: Claude (ENV) hoặc Gemini. Không ghi Sheet."""
    loigiai = clean(loigiai)
    if not loigiai:
        raise RuntimeError("Chưa có lời giải để phản biện.")
    if not clean(context.get("CauHoi", "")):
        raise RuntimeError("Chưa có đề bài.")

    cfg = ai_runtime_config()
    gemini_keys = _user_gemini_keys(extra_gemini_key)
    openai_keys = load_ai_keys("OPENAI")
    ant_keys = _debate_anthropic_keys(extra_anthropic_key)
    model_gemini = (
        clean(cfg.get("gemini_model") or os.environ.get("GEMINI_HINT_MODEL", DEFAULT_GEMINI_HINT_MODEL))
        or DEFAULT_GEMINI_HINT_MODEL
    )
    model_anthropic = (
        clean(os.environ.get("ANTHROPIC_ADMIN_MODEL", DEFAULT_ANTHROPIC_ADMIN_MODEL))
        or DEFAULT_ANTHROPIC_ADMIN_MODEL
    )
    model_openai = clean(
        cfg.get("openai_admin_model") or cfg.get("openai_model") or DEFAULT_OPENAI_ADMIN_MODEL
    )

    def call_gemini(sys_prompt: str, user_prompt: str) -> Tuple[str, str]:
        last = ""
        models = [model_gemini] + [m for m in GEMINI_HINT_MODEL_FALLBACKS if m != model_gemini]
        for api_key in gemini_keys:
            for gmodel in models:
                txt, finish, err = _gemini_hint_call(
                    api_key, gmodel, sys_prompt, user_prompt, 1100, 0.22, timeout=22
                )
                if txt:
                    return _quiz_debate_plain(txt), ""
                last = err or finish or last
        return "", last or "Gemini không phản hồi."

    def call_claude(sys_prompt: str, user_prompt: str) -> Tuple[str, str]:
        last = ""
        for api_key in ant_keys:
            txt, finish, err = _anthropic_chat_call(
                api_key, model_anthropic, sys_prompt, user_prompt, 1100, 0.22, timeout=22
            )
            if txt:
                return _quiz_debate_plain(txt), ""
            last = err or finish or last
        return "", last or "Claude không phản hồi."

    def call_gpt(sys_prompt: str, user_prompt: str) -> Tuple[str, str]:
        last = ""
        for api_key in openai_keys:
            txt, finish, err = _openai_chat_call(
                api_key, model_openai, sys_prompt, user_prompt, 1100, 0.22, timeout=22
            )
            if txt:
                return _quiz_debate_plain(txt), ""
            last = err or finish or last
        return "", last or "GPT không phản hồi."

    want = clean(force_provider or "").upper()
    use_claude = bool(ant_keys and is_admin() and want in {"", "ANTHROPIC", "CLAUDE"})
    if is_admin() and want in {"GEMINI", "OPENAI", "GPT"}:
        use_claude = False

    claude_txt, claude_err = "", ""
    gemini_txt, gemini_err = "", ""

    if use_claude:
        sys_c, user_c = _quiz_debate_context_prompt(context, loigiai, role="Claude")
        claude_txt, claude_err = call_claude(sys_c, user_c)
        if claude_txt:
            gemini_txt = claude_txt
        elif gemini_keys:
            sys_g, user_g = _quiz_debate_context_prompt(context, loigiai, role="gemini")
            gemini_txt, gemini_err = call_gemini(sys_g, user_g)
            if not gemini_txt and openai_keys:
                gemini_txt, gemini_err = call_gpt(sys_g, user_g)
                if gemini_txt:
                    gemini_err = ""
    else:
        sys_g, user_g = _quiz_debate_context_prompt(context, loigiai, role="gemini")
        gemini_txt, gemini_err = call_gemini(sys_g, user_g)
        if not gemini_txt and openai_keys and is_admin():
            gemini_txt, gemini_err = call_gpt(sys_g, user_g)
            if gemini_txt:
                gemini_err = ""
        if not gemini_txt and ant_keys and is_admin():
            sys_c, user_c = _quiz_debate_context_prompt(context, loigiai, role="Claude")
            claude_txt, claude_err = call_claude(sys_c, user_c)
            if claude_txt:
                gemini_txt = claude_txt

    final_txt = gemini_txt or claude_txt
    if not final_txt:
        bits = [x for x in (claude_err, gemini_err) if x]
        raise RuntimeError("Không phản biện được: " + " · ".join(bits or ["AI im lặng."]))

    return {
        "claude": claude_txt,
        "gemini": gemini_txt,
        "final": final_txt,
        "claude_reply": "",
        "gemini_reply": "",
        "claude_error": claude_err if not claude_txt else "",
        "gemini_error": gemini_err if not gemini_txt else "",
        "mode": "one",
    }


def ai_quiz_debate_followup(
    context: Dict[str, Any],
    loigiai: str,
    message: str,
    *,
    history: Optional[List[Dict[str, Any]]] = None,
    debate_text: str = "",
    extra_gemini_key: str = "",
) -> Dict[str, str]:
    """Học sinh hỏi tiếp trợ lý AI của Thầy Minh Vật Lý (Gemini)."""
    msg = clean(message)
    if not msg:
        raise RuntimeError("Hãy gõ thắc mắc rồi gửi.")
    if len(msg) > 1200:
        msg = msg[:1200]
    ctx = dict(context or {})
    cauhoi = clean(ctx.get("CauHoi", ""))[:1400]
    if not cauhoi:
        raise RuntimeError("Chưa có đề bài.")
    dang = clean(ctx.get("Dang", "")) or clean(effective_dang(ctx))
    mon = clean(ctx.get("Mon", ""))
    lop = clean(ctx.get("Lop", ""))
    chuong = clean(ctx.get("Chuong", ""))
    baihoc = clean(ctx.get("BaiHoc", ""))
    dapan = clean(ctx.get("DapAn", ""))[:240]
    user_answer = clean(ctx.get("_user_answer") or "")[:400]
    spoken = bool(ctx.get("_spoken"))
    opts = []
    for L in "ABCD":
        stmt = clean(ctx.get(L, ""))
        if stmt:
            opts.append(f"{L}. {stmt[:400]}")
    gemini_keys = _user_gemini_keys(extra_gemini_key)
    if not gemini_keys:
        raise RuntimeError(
            "Chưa có Gemini key. Vào 🔑 Key AI dán AIza... hoặc AQ... (aistudio.google.com/apikey) rồi Lưu."
        )
    cfg = ai_runtime_config()
    model_gemini = (
        clean(cfg.get("gemini_model") or os.environ.get("GEMINI_HINT_MODEL", DEFAULT_GEMINI_HINT_MODEL))
        or DEFAULT_GEMINI_HINT_MODEL
    )
    heard = "Học sinh vừa NÓI (giọng nói)" if spoken else "Học sinh vừa nêu ý kiến"
    sys_prompt = (
        "Bạn là trợ lý AI của Thầy Minh Vật Lý. Nhiệm vụ: NGHE / đọc ý kiến học sinh rồi PHẢN BIỆN sát đề đang mở. "
        "Tiếng Việt, sư phạm, rõ ràng. Không markdown heading, không ```. "
        "Không bịa số liệu, không bịa định luật, không giảng bài ngoài câu này. "
        + _quiz_debate_hook_rules("chat")
        + " Kết thúc: «Em còn thắc mắc gì không? Có thể nói tiếp vào mic.» "
        "Nếu học sinh nói không còn thắc mắc: khen ngắn, KHÔNG hỏi thêm, không nhồi công thức."
    )
    lines = [
        f"Môn: {mon or 'Vật lý'} · Lớp: {lop or '?'} · Dạng: {dang or '?'}",
        f"Chương: {chuong or '?'} · Bài: {baihoc or '?'}",
        "",
        "ĐỀ BÀI (bám sát từng số liệu/điều kiện):",
        cauhoi or "(trống)",
    ]
    if opts:
        lines.extend(["", "PHƯƠNG ÁN (đúng chữ trên màn hình):", *opts])
    if dapan:
        lines.extend(["", "ĐÁP ÁN ĐÚNG:", dapan])
    if user_answer:
        lines.extend(["", "EM ĐÃ CHỌN KHI LÀM BÀI:", user_answer])
    if clean(loigiai):
        lines.extend(["", "LỜI GIẢI (nguồn dẫn chứng):", clean(loigiai)[:1800]])
    if clean(debate_text):
        lines.extend(["", "PHẢN BIỆN ĐÃ NÓI:", clean(debate_text)[:1600]])
    hist_lines = []
    for turn in (history or [])[-8:]:
        if not isinstance(turn, dict):
            continue
        role = "Học sinh" if clean(turn.get("role")).lower() in {"user", "hs", "hoc sinh"} else "Trợ lý"
        text = clean(turn.get("text") or turn.get("content") or "")[:700]
        if text:
            hist_lines.append(f"{role}: {text}")
    if hist_lines:
        lines.extend(["", "TRAO ĐỔI TRƯỚC:", *hist_lines])
    lines.extend(["", f"{heard}:", msg, "", "Hãy phán ĐÚNG/SAI ý kiến trên, nêu công thức $...$ của bài, và bám sát đề đang gửi."])
    user_prompt = "\n".join(lines)
    last = ""
    models = [model_gemini] + [m for m in GEMINI_HINT_MODEL_FALLBACKS if m != model_gemini]
    for api_key in gemini_keys:
        for gmodel in models:
            txt, finish, err = _gemini_hint_call(
                api_key, gmodel, sys_prompt, user_prompt, 1100, 0.28, timeout=24
            )
            if txt:
                return {"text": _quiz_debate_plain(txt), "provider": "GEMINI"}
            last = err or finish or last
    raise RuntimeError(last or "Gemini không phản hồi. Kiểm tra key tại 🔑 Key AI rồi thử lại.")


def ai_admin_generate_tikz(
    context: Dict[str, Any],
    *,
    extra_hint: str = "",
    existing_tikz: str = "",
    mode: str = "new",
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
    extra_anthropic_key: str = "",
) -> Tuple[str, str, str]:
    """ADMIN: AI tạo hoặc sửa mã TikZ minh họa câu hỏi."""
    ctx = dict(context or {})
    cauhoi = clean(ctx.get("CauHoi", ""))[:1600]
    loigiai = clean(ctx.get("LoiGiai", ""))[:2000]
    if not cauhoi and not loigiai:
        raise RuntimeError("Cần có đề bài hoặc lời giải để AI vẽ hình.")

    mon = clean(ctx.get("Mon", ""))
    lop = clean(ctx.get("Lop", ""))
    chuong = clean(ctx.get("Chuong", ""))
    baihoc = clean(ctx.get("BaiHoc", ""))
    dang = clean(ctx.get("Dang", ""))
    dapan = clean(ctx.get("DapAn", ""))
    extra = clean(extra_hint)[:800]
    old_tz = clean(existing_tikz)[:6000]
    rewrite = clean(mode).lower() == "rewrite" or bool(old_tz)

    ds_stmts = []
    for L in "ABCD":
        stmt = clean(ctx.get(L, ""))
        if stmt:
            ds_stmts.append(f"{L}. {stmt[:400]}")

    sys_prompt = (
        "Bạn là giáo viên Việt Nam chuyên vẽ hình minh họa đề THPT bằng TikZ/LaTeX. "
        "Chỉ trả về MỘT khối \\begin{tikzpicture}...\\end{tikzpicture}, không giải thích, không markdown, không ```."
    )

    user_lines = [
        "Tạo mã TikZ minh họa câu hỏi sau cho đúng chương trình THPT.",
        "",
        "YÊU CẦU BẮT BUỘC:",
        "- Chỉ trả về đúng MỘT khối \\begin{tikzpicture}...\\end{tikzpicture}.",
        "- Vẽ rõ ràng: trục tọa độ, mốc, đơn vị, nhãn; số liệu khớp đề và lời giải.",
        "- Toán: đồ thị hàm, hình học, véc-tơ… · Lý: sơ đồ lực, mạch điện, đồ thị v–t, d–t…",
        "- Dùng \\draw, \\node, \\coordinate; tránh gói phức tạp ngoài tikz.",
        "- Không nhét \\begin{tikzpicture} vào câu hỏi — chỉ trả mã TikZ.",
        "- Không URL ảnh; không lời giải chữ.",
    ]
    if rewrite and old_tz:
        user_lines.extend([
            "",
            "ĐÃ CÓ TIKZ — hãy SỬA/CẢI THIỆN (giữ ý nghĩa, sửa lỗi biên dịch nếu có):",
            old_tz,
        ])
    user_lines.extend([
        "",
        f"Môn: {mon}",
        f"Lớp: {lop}",
        f"Chương: {chuong}",
        f"Bài học: {baihoc}",
        f"Dạng: {dang}",
        f"Đáp án (P): {dapan or '(chưa có)'}",
    ])
    if extra:
        user_lines.extend(["", f"Yêu cầu thêm của ADMIN: {extra}"])
    user_lines.extend(["", "CÂU HỎI:", cauhoi or "(trống)"])
    if ds_stmts:
        user_lines.extend(["", "PHƯƠNG ÁN A–D:", *ds_stmts])
    if loigiai:
        user_lines.extend(["", "LỜI GIẢI (tham chiếu số liệu/hình):", loigiai])
    user_prompt = "\n".join(user_lines)

    def postprocess(s: str) -> str:
        s = clean(s)
        s = re.sub(r"^```(?:latex|tex|tikz|text)?", "", s, flags=re.I).strip()
        s = re.sub(r"```$", "", s).strip()
        block = _extract_tikz_block(s)
        if block:
            return block
        if "\\begin{tikzpicture}" in s.lower():
            return s
        return ""

    txt, prov, _model, _ki = admin_ai_call_text(
        sys_prompt,
        user_prompt,
        max_tokens=2200,
        temp=0.12,
        timeout=50,
        force_provider=force_provider,
        allow_gpt_fallback=allow_gpt_fallback,
        extra_anthropic_key=extra_anthropic_key,
    )
    tikz = postprocess(txt)
    if not tikz:
        raise RuntimeError("AI chưa trả về \\begin{tikzpicture}…\\end{tikzpicture} hợp lệ.")

    compile_warn = ""
    try:
        url = _compile_tikz_to_png(tikz, ctx, 0, 1)
        if not url:
            compile_warn = "TikZ chưa biên dịch thử — bấm 🔄 Vẽ lại; vẫn sửa được mã."
    except Exception as ex:
        compile_warn = f"TikZ chưa biên dịch thử: {ex}"

    return tikz, prov, compile_warn


def gemini_generate_infographic_image(
    prompt: str,
    api_key: str,
    *,
    ref_b64: str = "",
    ref_mime: str = "",
    timeout: int = 55,
) -> Tuple[str, str, str, str]:
    """Gọi Gemini tạo poster infographic. Trả (image_b64, mime, error, model_used)."""
    models_try: List[str] = []
    primary = (
        clean(os.environ.get("GEMINI_IMAGE_MODEL", DEFAULT_GEMINI_IMAGE_MODEL)).strip()
        or DEFAULT_GEMINI_IMAGE_MODEL
    )
    for m in [primary, "gemini-2.0-flash-exp-image-generation", DEFAULT_GEMINI_IMAGE_MODEL]:
        if m and m not in models_try:
            models_try.append(m)
    parts: List[Dict[str, Any]] = [{"text": prompt}]
    if ref_b64 and ref_mime:
        parts.append({"inline_data": {"mime_type": ref_mime, "data": ref_b64}})
        parts[0] = {
            "text": prompt
            + "\n\n(Ảnh tham chiếu cột T đính kèm — vẽ lại poster đẹp hơn, flat vector hiện đại, giữ đúng nội dung Sheet.)"
        }
    last_err = ""
    for gmodel in models_try:
        body = {
            "contents": [{"parts": parts}],
            "generationConfig": {"responseModalities": ["TEXT", "IMAGE"]},
        }
        url, headers = _gemini_request_target(api_key, gmodel)
        req = urllib.request.Request(
            url,
            data=json.dumps(body).encode("utf-8"),
            headers=headers,
            method="POST",
        )
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                data = json.loads(resp.read().decode("utf-8", errors="ignore"))
            cands = (data or {}).get("candidates") or []
            cand0 = cands[0] if cands else {}
            resp_parts = ((cand0.get("content") or {}).get("parts") or [])
            for p in resp_parts:
                if not isinstance(p, dict):
                    continue
                inline = p.get("inlineData") or p.get("inline_data") or {}
                b64 = clean(inline.get("data", ""))
                mime = clean(inline.get("mimeType") or inline.get("mime_type") or "image/png")
                if b64:
                    return b64, mime or "image/png", "", gmodel
            last_err = "Model không trả ảnh trong phản hồi"
        except Exception as e:
            last_err = _http_error_message(e)
            if _is_quota_or_rate_error(last_err):
                break
    return "", "", last_err or "Gemini không tạo được ảnh", ""


def ai_hint_from_provider(
    q: Dict[str, Any],
    user_answer: Any,
    admin_review: bool = False,
    vip_formula_only: bool = False,
    vip_short: bool = False,
    svip_hint: bool = False,
    admin_review_mode: str = "full",
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
    extra_anthropic_key: str = "",
) -> Tuple[str, int, str, str, Dict[str, Any]]:

    cfg = ai_runtime_config()
    vision = prepare_question_vision(q)
    img_b64 = vision.get("image_b64", "") if vision.get("vision_ready") else ""
    img_mime = vision.get("image_mime", "") if vision.get("vision_ready") else ""
    vision_meta: Dict[str, Any] = {
        "has_question_image": bool(vision.get("has_image")),
        "vision_used": bool(img_b64),
        "vision_model": "",
        "image_src": vision.get("image_src", ""),
        "image_fetch_error": vision.get("fetch_error", ""),
    }
    openai_keys = load_ai_keys("OPENAI")
    gemini_keys = load_ai_keys("GEMINI")
    if admin_review and clean(force_provider):
        provider = admin_ai_resolve_force(force_provider)
    else:
        provider = resolve_ai_provider(cfg, admin_review=admin_review, svip_hint=svip_hint)
    last_error = ""
    gemini_saw_quota = False
    review_opts = resolve_admin_review_opts(admin_review_mode) if admin_review else None
    if admin_review and review_opts:
        max_tokens = int(review_opts["max_tokens"])
        max_chars = int(review_opts["max_chars"])
    elif vip_short or vip_formula_only:
        if svip_hint:
            max_tokens = AI_HINT_SVIP_MAX_OUTPUT_TOKENS
            max_chars = AI_HINT_SVIP_MAX_CHARS
        else:
            max_tokens = AI_HINT_VIP_MAX_OUTPUT_TOKENS
            max_chars = AI_HINT_VIP_MAX_CHARS
    else:
        max_tokens = AI_HINT_MAX_OUTPUT_TOKENS
        max_chars = AI_HINT_MAX_CHARS

    model_openai = cfg.get("openai_model") or DEFAULT_OPENAI_HINT_MODEL
    if admin_review:
        fast_model = clean((review_opts or {}).get("openai_model", ""))
        model_openai = fast_model or cfg.get("openai_admin_model") or model_openai
    model_gemini = clean(os.environ.get("GEMINI_HINT_MODEL", DEFAULT_GEMINI_HINT_MODEL)).strip() or DEFAULT_GEMINI_HINT_MODEL
    if admin_review:
        admin_model = (
            clean(os.environ.get("GEMINI_ADMIN_MODEL", DEFAULT_GEMINI_ADMIN_MODEL)).strip()
            or DEFAULT_GEMINI_ADMIN_MODEL
        )
        gemini_models_raw = [admin_model, model_gemini] + GEMINI_HINT_MODEL_FALLBACKS
    else:
        gemini_models_raw = [model_gemini] + GEMINI_HINT_MODEL_FALLBACKS
    seen_models: set = set()
    gemini_models: List[str] = []
    for m in gemini_models_raw:
        if m and m not in seen_models:
            seen_models.add(m)
            gemini_models.append(m)
    if img_b64:
        gv = (
            clean(os.environ.get("GEMINI_VISION_MODEL", DEFAULT_GEMINI_VISION_MODEL)).strip()
            or DEFAULT_GEMINI_VISION_MODEL
        )
        gemini_models = [gv] + [m for m in gemini_models if m != gv]

    oa_vision_model = (
        clean(os.environ.get("OPENAI_VISION_MODEL", DEFAULT_OPENAI_VISION_MODEL)).strip()
        or DEFAULT_OPENAI_VISION_MODEL
    )

    if admin_review:
        review_opts = resolve_admin_review_opts(admin_review_mode)
        fast_admin = (review_opts or {}).get("mode") == "fast"

        sys_prompt = admin_review_sys_prompt_2026(q, fast=fast_admin)

        teacher_prompt = build_ai_admin_review_prompt_2026(
            q, user_answer, mode=(review_opts or {}).get("mode", "full")
        )
        temp = 0.1
    elif vip_short:
        if svip_hint:
            sys_prompt = (
                "Bạn là trợ giảng SVIP dùng Gemini. Trả lời tiếng Việt. "
                "CHỈ 2 mục: 1. PHƯƠNG HƯỚNG LÀM BÀI và 2. GỢI Ý TỰ KIỂM TRA. "
                "Tuyệt đối KHÔNG chốt đáp án, không ghi A/B/C/D đúng, không ghi đáp số cuối. "
                "Chỉ ADMIN dùng Soát đề GPT mới được chốt đáp án. LaTeX trong $...$ một dòng."
            )
        else:
            sys_prompt = (
                "Bạn là trợ giảng VIP. Trả lời tiếng Việt, NGẮN GỌN. "
                "CHỈ 2 mục: 1. PHƯƠNG HƯỚNG LÀM BÀI và 2. GỢI Ý TỰ KIỂM TRA. "
                "KHÔNG giải từng phương án A/B/C/D. KHÔNG chốt đáp án/đáp số. "
                "Chỉ ADMIN dùng Soát đề GPT mới được chốt đáp án. LaTeX trong $...$ một dòng."
            )
        teacher_prompt = build_ai_vip_hint_prompt_2026(q, user_answer, svip_hint=svip_hint)
        temp = 0.12
    elif vip_formula_only:
        sys_prompt = (
            "Bạn là trợ giảng VIP. Trả lời tiếng Việt: nhắc đề, định nghĩa, "
            "công thức ĐÃ THAY SỐ từ đề bài, các bước so khớp phương án. "
            "Không nêu đáp án A/B/C/D cuối. LaTeX trong $...$ một dòng, không để trống."
        )
        teacher_prompt = build_ai_vip_formula_prompt_2026(q, user_answer)
        temp = 0.12
    else:
        sys_prompt = (
            "Bạn là trợ giảng luyện đề. Trả lời tiếng Việt, NGẮN GỌN (4–5 dòng), "
            "chỉ gợi ý hướng làm — không viết bài giải dài, không đáp án cuối."
        )
        teacher_prompt = build_ai_teacher_prompt_2026(q, user_answer)
        temp = 0.15
    if img_b64:
        sys_prompt += (
            " Có ẢNH MINH HỌA đính kèm — đọc sơ đồ/đồ thị/hình vẽ trong ảnh trước khi phân tích."
        )

    def _postprocess_hint_text(raw: str, *, compact_admin: bool = False) -> str:
        raw = clean(raw)
        if admin_review:
            txt = _finalize_admin_hint_text(raw, max_chars)
            if compact_admin:
                return trim_ai_hint_text(txt, AI_HINT_VIP_MAX_CHARS)
            return txt
        return trim_ai_hint_text(raw, max_chars)

    def _continue_admin_gemini(txt: str, finish: str, api_key: str, gmodel: str) -> str:
        nonlocal last_error

        def call_fn(user_prompt: str, timeout: int) -> Tuple[str, str, str]:
            return _gemini_hint_call(
                api_key, gmodel, sys_prompt, user_prompt, max_tokens, temp, timeout=timeout
            )

        return _finish_admin_review_text(txt, finish, teacher_prompt, call_fn, q, review_opts)

    def _continue_admin_openai(txt: str, finish: str, api_key: str, omodel: str) -> str:
        nonlocal last_error

        def call_fn(user_prompt: str, timeout: int) -> Tuple[str, str, str]:
            return _openai_chat_call(
                api_key, omodel, sys_prompt, user_prompt, max_tokens, temp, timeout=timeout
            )

        return _finish_admin_review_text(txt, finish, teacher_prompt, call_fn, q, review_opts)

    def try_openai() -> Tuple[str, int, str, str]:
        nonlocal last_error
        oa_timeout = (
            int((review_opts or {}).get("openai_timeout", 70))
            if admin_review
            else (38 if svip_hint and img_b64 else (32 if svip_hint else 18))
        )
        if img_b64 and not admin_review:
            oa_timeout = max(oa_timeout, 38)
        oa_keys = openai_keys
        if admin_review and review_opts and review_opts.get("mode") == "fast":
            oa_keys = openai_keys[:1]
        oa_model = model_openai
        if img_b64:
            oa_model = (
                (cfg.get("openai_admin_model") or oa_vision_model)
                if admin_review
                else oa_vision_model
            )
        for idx, api_key in enumerate(oa_keys, start=1):
            txt, finish, err = _openai_chat_call(
                api_key,
                oa_model,
                sys_prompt,
                teacher_prompt,
                max_tokens,
                temp,
                timeout=oa_timeout,
                image_b64=img_b64,
                image_mime=img_mime,
            )
            if err:
                last_error = err
                if _is_quota_or_rate_error(last_error):
                    print(f"[AI_HINT][OPENAI] key #{idx} quota/rate — thử key tiếp")
                    continue
                continue
            if not txt:
                continue
            if admin_review and not (review_opts and review_opts.get("mode") == "fast"):
                txt = _continue_admin_openai(txt, finish, api_key, model_openai)
            txt = _postprocess_hint_text(clean(txt))
            if txt:
                tag = "ADMIN_REVIEW" if admin_review else "OPENAI"
                if img_b64:
                    vision_meta["vision_model"] = oa_model
                print(f"[AI_HINT][{tag}] using key #{idx}" + (" +vision" if img_b64 else ""))
                return txt, idx, "OPENAI", ""
        return "", 0, "OPENAI", last_error

    def try_gemini() -> Tuple[str, int, str, str]:
        nonlocal last_error, gemini_saw_quota
        admin_primary = gemini_models[0] if admin_review else ""
        gem_timeout = (
            int((review_opts or {}).get("gemini_timeout", 70))
            if admin_review
            else 22
        )
        for idx, api_key in enumerate(gemini_keys, start=1):
            for gmodel in gemini_models:
                compact_admin = bool(admin_review and gmodel != admin_primary)
                call_sys = ADMIN_SYS_PROMPT_COMPACT if compact_admin else sys_prompt
                call_tokens = AI_HINT_VIP_MAX_OUTPUT_TOKENS if compact_admin else max_tokens
                call_timeout = 28 if compact_admin else gem_timeout
                txt, finish, err = _gemini_hint_call(
                    api_key,
                    gmodel,
                    call_sys,
                    teacher_prompt,
                    call_tokens,
                    temp,
                    timeout=call_timeout,
                    image_b64=img_b64,
                    image_mime=img_mime,
                )
                if err:
                    last_error = err
                    if _is_quota_or_rate_error(last_error):
                        gemini_saw_quota = True
                        print(f"[AI_HINT][GEMINI] model={gmodel} key #{idx} quota — thử model/key tiếp")
                        continue
                    continue
                if not txt:
                    continue
                if admin_review and not compact_admin:
                    txt = _continue_admin_gemini(txt, finish, api_key, gmodel)
                txt = _postprocess_hint_text(txt, compact_admin=compact_admin)
                if txt:
                    tag = "ADMIN_REVIEW" if admin_review else "GEMINI"
                    mode = " compact" if compact_admin else ""
                    if img_b64:
                        vision_meta["vision_model"] = gmodel
                    print(
                        f"[AI_HINT][{tag}] model={gmodel} key=#{idx} finish={finish}{mode}"
                        + (" +vision" if img_b64 else "")
                    )
                    return txt, idx, "GEMINI", ""
        return "", 0, "GEMINI", last_error

    txt, idx, used_provider, err = "", 0, provider, ""
    fallback_note = ""
    if provider == "ANTHROPIC" and admin_review:
        review_opts = resolve_admin_review_opts(admin_review_mode)
        max_tokens_admin = int((review_opts or {}).get("max_tokens", AI_HINT_ADMIN_MAX_OUTPUT_TOKENS))
        timeout_admin = int((review_opts or {}).get("gemini_timeout", 70))
        try:
            txt_raw, prov_used, model_used, ki = admin_ai_call_text(
                sys_prompt,
                teacher_prompt,
                max_tokens=max_tokens_admin,
                temp=temp,
                timeout=timeout_admin,
                force_provider="ANTHROPIC",
                allow_gpt_fallback=allow_gpt_fallback,
                extra_anthropic_key=extra_anthropic_key,
                image_b64=img_b64,
                image_mime=img_mime,
            )
            if txt_raw:
                txt = _postprocess_hint_text(clean(txt_raw))
                if txt:
                    idx = ki
                    used_provider = prov_used or "ANTHROPIC"
                    if img_b64 and model_used:
                        vision_meta["vision_model"] = model_used
                    return txt, idx, used_provider, fallback_note, vision_meta
        except AdminGeminiQuotaError:
            raise
        except Exception as ex:
            err = clean(str(ex))
        if allow_gpt_fallback:
            if gemini_keys:
                txt, idx, used_provider, err = try_gemini()
                if txt:
                    fallback_note = f"Claude lỗi ({err or 'không phản hồi'}) — dùng Gemini dự phòng."
                    return txt, idx, used_provider, fallback_note, vision_meta
            if openai_keys:
                txt, idx, used_provider, err = try_openai()
                if txt:
                    fallback_note = f"Claude lỗi ({err or 'không phản hồi'}) — dùng GPT dự phòng."
                    return txt, idx, used_provider, fallback_note, vision_meta
    elif provider == "OPENAI":
        txt, idx, used_provider, err = try_openai()
        primary_err = err
        admin_fast = bool(
            admin_review and review_opts and review_opts.get("mode") == "fast"
        )
        if admin_review and not txt and gemini_keys and not admin_fast:
            tag = "ADMIN_REVIEW"
            print(f"[AI_HINT][{tag}] OPENAI lỗi — thử GEMINI dự phòng: {primary_err}")
            txt, idx, used_provider, err = try_gemini()
            if txt:
                fallback_note = (
                    f"Chọn OPENAI nhưng lỗi: {primary_err or 'không phản hồi'} "
                    f"— đang dùng GEMINI dự phòng."
                )
    elif provider == "GEMINI":
        txt, idx, used_provider, err = try_gemini()
        primary_err = err
        if admin_review and not txt:
            if gemini_saw_quota and openai_keys and not allow_gpt_fallback:
                raise AdminGeminiQuotaError(primary_err or last_error, openai_available=True)
            if allow_gpt_fallback and openai_keys:
                print(f"[AI_HINT][ADMIN_REVIEW] GEMINI lỗi — dùng GPT theo yêu cầu: {primary_err}")
                txt, idx, used_provider, err = try_openai()
                if txt:
                    fallback_note = (
                        f"GEMINI hết quota — đang dùng GPT dự phòng."
                    )
        elif not admin_review and not txt and is_admin() and openai_keys:
            txt, idx, used_provider, err = try_openai()
    else:
        if admin_review and openai_keys:
            txt, idx, used_provider, err = try_openai()
            primary_err = err
            if not txt and gemini_keys:
                txt, idx, used_provider, err = try_gemini()
                if txt:
                    fallback_note = (
                        f"Thử OPENAI trước nhưng lỗi: {primary_err or 'không phản hồi'} "
                        f"— đang dùng GEMINI dự phòng."
                    )
        elif gemini_keys:
            txt, idx, used_provider, err = try_gemini()
            if not txt and is_admin():
                txt, idx, used_provider, err = try_openai()
        else:
            if is_admin():
                txt, idx, used_provider, err = try_openai()

    if txt:
        return txt, idx, used_provider, fallback_note, vision_meta
    return ai_hint_fallback(q, user_answer), 0, "FALLBACK", err or last_error, vision_meta

