@app.route("/login", methods=["GET", "POST"])
def login():
    error = ""
    if request.method == "POST":
        mahs = clean(request.form.get("mahs"))
        password = clean(request.form.get("password"))
        try:
            store = get_store()
            if not local_demo_enabled():
                store.ensure_users_loaded(force=True)
            user = store.users.get(mahs)
            if not user:
                # Không phân biệt hoa thường
                for k, v in store.users.items():
                    if key_norm(k) == key_norm(mahs):
                        user = v
                        mahs = k
                        break
            if not user:
                error = "Không thấy tài khoản trong sheet HOC_VIEN."
            elif user.get("status", "ON").upper() not in USER_ACTIVE_STATUSES:
                error = "Tài khoản đang bị khóa hoặc chưa kích hoạt."
            elif store.is_user_expired(user)[0]:
                error = store.is_user_expired(user)[1]
            elif not _password_match(clean(user.get("password", "")), password):
                error = "Sai mật khẩu."
            else:
                # [A2] Nâng cấp mật khẩu thường -> băm (chỉ khi PASSWORD_HASHING=1).
                try:
                    store.upgrade_password_hash(mahs, password)
                except Exception as e:
                    log_exc("login upgrade_password_hash", e)
                token = stable_hash(f"{mahs}|{time.time()}|{random.random()}", 24)
                store.active_tokens[mahs] = token
                session.clear()
                session.permanent = True
                session.update({
                    "mahs": user.get("mahs"), "hoten": user.get("hoten"), "lop": user.get("lop"),
                    "role": user.get("role"), "session_token": token,
                    "trial_until": user.get("trial_until", ""), "account_until": user.get("account_until", "")
                })
                nxt = safe_next_url(request.form.get("next"))
                return redirect(nxt or url_for("home"))
        except Exception as e:
            err_str = str(e)
            if "GOOGLE_CREDENTIALS" in err_str or "credentials" in err_str.lower() or "gspread" in err_str.lower():
                error = "Không kết nối được Google Sheet. Kiểm tra lại GOOGLE_CREDENTIALS_JSON và GOOGLE_SHEET_ID."
            elif "Worksheet" in err_str and "not found" in err_str:
                error = "Không tìm thấy sheet HOC_VIEN. Vui lòng tạo sheet này hoặc liên hệ admin."
            elif "timed out" in err_str.lower() or "timeout" in err_str.lower():
                error = "Kết nối Google Sheet quá chậm, vui lòng thử lại sau vài giây."
            else:
                error = err_str
    next_url = safe_next_url(request.args.get("next", ""))
    og_title = og_desc = og_url = ""
    if next_url:
        de = parse_de_from_next(next_url)
        if de:
            try:
                store = get_store()
                og_title, og_desc = share_og_context(store, de)
                og_url = request.url_root.rstrip("/") + next_url
            except Exception:
                log_swallow("login:29286")
                pass
    return render_template_string(
        LOGIN_HTML,
        error=error,
        msg=request.args.get("msg", ""),
        next=next_url,
        og_title=og_title,
        og_desc=og_desc,
        og_url=og_url,
        local_demo=local_demo_enabled(),
    )

