def save_dbt_order_one(made: str, names: List[str], orders: Optional[Dict[str, List[str]]] = None) -> Dict[str, List[str]]:
    """Lưu thứ tự một MaDe — file JSON + sheet DBT_ThuTu + cập nhật catalog RAM."""
    made = clean(made)
    names = [clean(x) for x in (names or []) if clean(x) and not _is_bad_dangbaitap_value(x)]
    orders = dict(orders if orders is not None else load_dbt_orders())
    if names:
        orders[made] = names
    elif made in orders:
        del orders[made]
    save_dbt_orders(orders)
    try:
        st = get_store()
        if made and names:
            st.upsert_dbt_order_on_sheet(made, names)
        if st.catalog:
            st.apply_dbt_orders_to_catalog(orders)
    except Exception:
        log_swallow("save_dbt_order_one:29760")
        pass
    return orders


def ordered_dbt_names(
    made: str,
    counts: Dict[str, int],
    orders: Optional[Dict[str, List[str]]] = None,
) -> List[str]:
    """Sắp xếp tên dạng BT: ưu tiên thứ tự ADMIN, phần còn lại theo số câu giảm dần."""
    orders = orders if orders is not None else load_dbt_orders()
    custom = orders.get(clean(made)) or []
    canon: Dict[str, str] = {}
    for k in (counts or {}):
        if k == DBT_FILTER_UNCLASSIFIED or _is_bad_dangbaitap_value(k):
            continue
        canon[key_norm(k)] = clean(k)
    out: List[str] = []
    seen: set = set()
    for name in custom:
        kn = key_norm(name)
        if kn in canon and kn not in seen:
            out.append(canon[kn])
            seen.add(kn)
    rest = sorted(
        [canon[kn] for kn in canon if kn not in seen],
        key=lambda nm: (-(counts.get(nm, 0) or 0), key_norm(nm)),
    )
    out.extend(rest)
    return out


def patch_dbt_order_after_merge(made: str, old_names: List[str], new_name: str) -> None:
    made = clean(made)
    new_name = clean(new_name)
    if not made or not new_name:
        return
    orders = load_dbt_orders()
    lst = list(orders.get(made) or [])
    if not lst:
        return
    old_keys = {key_norm(clean(x)) for x in old_names if clean(x)}
    new_lst: List[str] = []
    replaced = False
    for name in lst:
        if key_norm(name) in old_keys:
            if not replaced:
                new_lst.append(new_name)
                replaced = True
        else:
            new_lst.append(name)
    if replaced:
        save_dbt_order_one(made, new_lst, orders)


def _catalog_item_dbt_values(item: Dict[str, Any]) -> List[str]:
    out: List[str] = []
    fc = (item.get("FilterCounts") or {}).get("dangbaitap") or {}
    if isinstance(fc, dict):
        for k in fc:
            v = clean(k)
            if v and not _is_bad_dangbaitap_value(v):
                out.append(v)
    raw = clean(item.get("DangBaiTap", ""))
    if raw:
        for part in re.split(r"[,;|]+", raw):
            v = clean(part)
            if v and not _is_bad_dangbaitap_value(v):
                out.append(v)
    return out


def _lesson_scope_key(q: Dict[str, Any]) -> str:
    return "|".join([
        key_norm(clean(q.get("Mon", ""))),
        key_norm(clean(q.get("Chuong", ""))),
        key_norm(clean(q.get("BaiHoc", ""))),
    ])


def _dbt_similarity_py(a: str, b: str) -> float:
    a, b = key_norm(a), key_norm(b)
    if not a or not b:
        return 0.0
    if a == b or a in b or b in a:
        return 0.9
    ta, tb = set(a.split()), set(b.split())
    if not ta or not tb:
        return 0.0
    ov = len(ta & tb)
    return ov / min(len(ta), len(tb))


def _nearest_dbt_canonical(name: str, canonicals: List[str]) -> str:
    if not canonicals:
        return name
    best = canonicals[0]
    best_sc = -1.0
    for c in canonicals:
        sc = _dbt_similarity_py(name, c)
        if sc > best_sc:
            best_sc = sc
            best = c
    return best if best_sc >= 0.35 else canonicals[0]


def _consolidate_dangbaitap_per_lesson(
    questions: List[Dict[str, Any]], max_types: int = DBT_MAX_TYPES_PER_LESSON
) -> Dict[str, Any]:
    """Gom tối đa max_types dạng BT/khối bài học — gán lại _AiDangBaiTap cho câu bị loãng."""
    merged_total = 0
    lesson_stats: Dict[str, Any] = {}
    by_lesson: Dict[str, List[Dict[str, Any]]] = {}
    for q in questions:
        by_lesson.setdefault(_lesson_scope_key(q), []).append(q)

    for sk, group in by_lesson.items():
        buckets: Dict[str, Tuple[str, int]] = {}
        for q in group:
            v = clean(q.get("_AiDangBaiTap") or "")
            if not v or _is_bad_dangbaitap_value(v):
                continue
            kn = key_norm(v)
            if kn not in buckets:
                buckets[kn] = (v, 0)
            buckets[kn] = (buckets[kn][0], buckets[kn][1] + 1)

        if len(buckets) <= max_types:
            lesson_stats[sk] = {
                "types": len(buckets),
                "merged": 0,
                "canonical": [buckets[k][0] for k in buckets],
            }
            continue

        remap: Dict[str, str] = {kn: buckets[kn][0] for kn in buckets}

        def dist_names() -> List[str]:
            seen: set = set()
            out: List[str] = []
            for kn in remap:
                dn = key_norm(remap[kn])
                if dn not in seen:
                    seen.add(dn)
                    out.append(remap[kn])
            return out

        while len(dist_names()) > max_types:
            agg: Dict[str, int] = {}
            for kn in remap:
                dn = key_norm(remap[kn])
                agg[dn] = agg.get(dn, 0) + 1
            ranked = sorted(agg.items(), key=lambda x: (x[1], len(x[0])))
            victim_n = ranked[0][0]
            victim_display = next(remap[kn] for kn in remap if key_norm(remap[kn]) == victim_n)
            others_unique: List[str] = []
            seen_o: set = set()
            for kn in remap:
                if key_norm(remap[kn]) == victim_n:
                    continue
                ko = key_norm(remap[kn])
                if ko not in seen_o:
                    seen_o.add(ko)
                    others_unique.append(remap[kn])
            target = _nearest_dbt_canonical(victim_display, others_unique)
            for kn in list(remap.keys()):
                if key_norm(remap[kn]) == victim_n:
                    remap[kn] = target

        canonical = dist_names()[:max_types]
        n_merge = 0
        for q in group:
            v = clean(q.get("_AiDangBaiTap") or "")
            kn = key_norm(v)
            if kn not in remap:
                continue
            new_v = remap[kn]
            if key_norm(new_v) == kn:
                continue
            # Giữ dạng mới do AI/admin chọn — không ép gộp về dạng cũ.
            if q.get("_AiMatchedExisting") is False:
                continue
            q["_AiDangBaiTap"] = new_v
            q["_AiReason"] = (
                clean(q.get("_AiReason", ""))
                + f" (gộp về «{new_v}» — tối đa {max_types} dạng/bài)"
            ).strip()[:180]
            q["_AiMatchedExisting"] = True
            n_merge += 1
            merged_total += 1

        lesson_stats[sk] = {"types": len(canonical), "merged": n_merge, "canonical": canonical}

    return {"merged": merged_total, "lessons": lesson_stats}


def _lesson_dbt_canonical_from_questions(
    questions: List[Dict[str, Any]], max_types: int = DBT_MAX_TYPES_PER_LESSON
) -> Dict[str, List[str]]:
    by_lesson: Dict[str, Dict[str, Tuple[str, int]]] = {}
    for q in questions:
        sk = _lesson_scope_key(q)
        v = clean(q.get("_AiDangBaiTap") or q.get("DangBaiTap") or "")
        if not v or _is_bad_dangbaitap_value(v):
            continue
        kn = key_norm(v)
        bucket = by_lesson.setdefault(sk, {})
        if kn not in bucket:
            bucket[kn] = (v, 0)
        bucket[kn] = (bucket[kn][0], bucket[kn][1] + 1)
    out: Dict[str, List[str]] = {}
    for sk, bucket in by_lesson.items():
        ordered = sorted(bucket.keys(), key=lambda k: (-bucket[k][1], bucket[k][0].lower()))
        out[sk] = [bucket[k][0] for k in ordered[:max_types]]
    return out


def _scoped_dangbaitap_suggestions(store: "SheetStore", q: Dict[str, Any], limit: int = 50) -> Tuple[List[str], str]:
    mon = clean(q.get("Mon", ""))
    chuong = clean(q.get("Chuong", ""))
    bai = clean(q.get("BaiHoc", ""))

    def matches(item: Dict[str, Any], level: str) -> bool:
        if mon and key_norm(item.get("Mon", "")) != key_norm(mon):
            return False
        if level == "mon":
            return True
        if chuong and key_norm(item.get("Chuong", "")) != key_norm(chuong):
            return False
        if level == "chuong":
            return True
        if bai and key_norm(item.get("BaiHoc", "")) != key_norm(bai):
            return False
        return True

    counts: Dict[str, int] = {}
    canon: Dict[str, str] = {}
    level = "none"

    def bump(vals: List[str], weight: int = 1) -> None:
        for v in vals:
            k = key_norm(v)
            counts[k] = counts.get(k, 0) + max(weight, 0) or 1
            if k not in canon:
                canon[k] = v

    for item in store.catalog:
        if matches(item, "bai"):
            bump(_catalog_item_dbt_values(item))
    if counts:
        level = "bai"
    elif chuong:
        for item in store.catalog:
            if matches(item, "chuong"):
                bump(_catalog_item_dbt_values(item))
        if counts:
            level = "chuong"
    if not counts and mon:
        for item in store.catalog:
            if matches(item, "mon"):
                bump(_catalog_item_dbt_values(item))
        if counts:
            level = "mon"

    for qq in store.questions:
        dbt = clean(qq.get("DangBaiTap", ""))
        if not dbt or _is_bad_dangbaitap_value(dbt):
            continue
        if matches(qq, "bai"):
            bump([dbt])
        elif chuong and matches(qq, "chuong"):
            bump([dbt])
        elif mon and matches(qq, "mon"):
            bump([dbt])

    cur = clean(q.get("DangBaiTap", ""))
    if cur and not _is_bad_dangbaitap_value(cur):
        bump([cur], 0)

    ordered = sorted(canon.keys(), key=lambda k: (-counts.get(k, 0), canon[k].lower()))
    return [canon[k] for k in ordered[:limit]], level


def _merge_dangbaitap_suggestions(*lists: Iterable[str], limit: int = 50) -> List[str]:
    seen: set = set()
    out: List[str] = []
    for lst in lists:
        for x in lst or []:
            v = clean(x)
            if not v or _is_bad_dangbaitap_value(v):
                continue
            k = key_norm(v)
            if k in seen:
                continue
            seen.add(k)
            out.append(v)
            if len(out) >= limit:
                return out
    return out


def _resolve_dangbaitap_to_suggestions(
    raw: str,
    suggestions: List[str],
    *,
    allow_fuzzy: bool = False,
) -> Tuple[str, Optional[str], bool]:
    """Chuẩn hóa tên AI về dạng đã có trong ngân hàng.

    Mặc định chỉ khớp nguyên văn (key_norm) để vẫn lưu được dạng mới.
    allow_fuzzy=True chỉ dùng khi AI xác nhận used_existing hoặc ADMIN bật đồng bộ mạnh.
    """
    raw = clean(raw)
    if not raw or not suggestions:
        return raw, None, False
    rn = key_norm(raw)
    for s in suggestions:
        if key_norm(s) == rn:
            return s, s, True
    if not allow_fuzzy:
        return raw, None, False
    best: Optional[str] = None
    best_score = -1
    for s in suggestions:
        sn = key_norm(s)
        if rn in sn or sn in rn:
            score = min(len(rn), len(sn))
            if score > best_score:
                best_score = score
                best = s
    if best:
        return best, best, True
    raw_tokens = set(rn.split())
    if len(raw_tokens) >= 2:
        for s in suggestions:
            st = set(key_norm(s).split())
            overlap = len(raw_tokens & st)
            if overlap >= 2 and overlap >= max(2, int(len(raw_tokens) * 0.55)):
                return s, s, True
    return raw, None, False


def _detect_dangbaitap_prompt(q: Dict[str, Any], dangbaitap_suggestions: Optional[List[str]] = None, scope_level: str = "") -> str:
    sug_limit = DBT_MAX_TYPES_PER_LESSON if scope_level == "bai" else 50
    sug = [clean(x) for x in (dangbaitap_suggestions or []) if clean(x)]
    sug = [x for x in sug if not _is_bad_dangbaitap_value(x)][:sug_limit]
    scope_note = ""
    if scope_level == "bai":
        scope_note = " (ưu tiên cao nhất — cùng Môn + Chương + Bài học)"
    elif scope_level == "chuong":
        scope_note = " (cùng Môn + Chương)"
    elif scope_level == "mon":
        scope_note = " (cùng Môn)"
    if sug:
        sug_block = (
            f"\n\n★ DANH SÁCH DẠNG BÀI TẬP ĐÃ CÓ TRONG NGÂN HÀNG{scope_note} — BẮT BUỘC ƯU TIÊN:\n"
            + "\n".join(f"{i+1}. {x}" for i, x in enumerate(sug))
            + "\n\nQuy tắc đồng bộ tên:\n"
            "- Nếu câu thuộc một dạng trong danh sách trên → trả về ĐÚNG NGUYÊN VĂN tên đó (copy y hệt, không đổi dấu/hoa thường).\n"
            "- Chỉ đặt tên mới khi KHÔNG có dạng nào trong danh sách phù hợp.\n"
            "- Không tạo biến thể gần giống (vd đã có «Xác định li độ» thì không trả «Xác định li độ dao động»).\n"
        )
    else:
        sug_block = "\n\n(Chưa có dạng nào trong phạm vi Môn/Chương/Bài — có thể đặt tên mới ngắn gọn, 4-12 từ.)\n"
    opts = "\n".join([f"{L}. {clean(q.get(L,''))}" for L in "ABCD" if clean(q.get(L,''))])
    cap_note = ""
    if scope_level == "bai":
        cap_note = f"\n- Trong cùng Bài học: tối đa {DBT_MAX_TYPES_PER_LESSON} dạng khác nhau — ưu tiên gom câu cùng phương pháp, tái dùng tên có sẵn.\n"
    return f"""Bạn là giáo viên THPT đang phân loại ngân hàng câu hỏi.
Nhiệm vụ: đặt tên DẠNG BÀI TẬP ngắn gọn, cụ thể, để lưu vào cột DangBaiTap và dùng làm khóa gọi Phương pháp giải.

Yêu cầu:
- Trả về DUY NHẤT một JSON object hợp lệ, không markdown.
- Không trả 'Trắc nghiệm', 'Đúng sai', 'Trả lời ngắn', 'Tự luận' vì đó là DẠNG CÂU, không phải dạng bài tập.
- Tên dạng nên 4-12 từ, đủ cụ thể, dùng được cho nhiều câu cùng phương pháp.{cap_note}
- Ưu tiên tên như: Tiệm cận ngang hàm phân thức; Đọc số nghiệm từ đồ thị; Xác định li độ, vận tốc, gia tốc...
- Không nêu đáp án/đáp số/kết quả cuối; chỉ Soát đề GPT mới được chốt đáp án.{sug_block}

THÔNG TIN CÂU:
Môn: {clean(q.get('Mon'))}
Lớp: {clean(q.get('Lop'))}
Chương: {clean(q.get('Chuong'))}
Bài học: {clean(q.get('BaiHoc'))}
Dạng câu: {clean(q.get('Dang'))}
Mức độ: {clean(q.get('MucDo'))}
Dạng bài tập hiện tại: {clean(q.get('DangBaiTap'))}
Câu hỏi: {clean(q.get('CauHoi'))}
Phương án:
{opts}
(Đáp án/lời giải bị ẩn; chỉ phân loại dạng bài tập, không chốt đáp số.)

Schema:
{{
  "DangBaiTap": "tên dạng — copy nguyên văn từ danh sách nếu khớp",
  "reason": "lý do rất ngắn",
  "used_existing": true hoặc false
}}
"""


@app.route("/api/ai/detect-dangbaitap-update", methods=["POST"])
def api_ai_detect_dangbaitap_update():
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN được gán Dạng bài tập."}), 403
    body = request.get_json(silent=True) or {}
    q = _learning_question_from_body(body)
    client_sug = body.get("dangbaitap_suggestions") or []
    if not isinstance(client_sug, list):
        client_sug = []
    st = get_store()
    st.ensure_questions_loaded()
    scoped_sug, scope_level = _scoped_dangbaitap_suggestions(st, q, limit=50)
    meta_sug: List[str] = []
    try:
        meta_sug = ((st.meta() or {}).get("filters") or {}).get("DangBaiTap") or []
    except Exception:
        log_swallow("api_ai_detect_dangbaitap_update:30164")
        meta_sug = []
    suggestions = _merge_dangbaitap_suggestions(scoped_sug, client_sug, meta_sug, limit=50)
    save_sheet = body.get("save", True)
    if save_sheet is False or str(save_sheet).lower() in ("0", "false", "no"):
        save_sheet = False
    else:
        save_sheet = True
    prompt = _detect_dangbaitap_prompt(q, suggestions, scope_level=scope_level)
    try:
        force, allow = admin_ai_body_params(body)
        raw, provider, model = _learning_ai_call(
            prompt, force_provider=force, allow_gpt_fallback=allow
        )
    except AdminGeminiQuotaError as e:
        return admin_ai_quota_json(e)
    obj = _extract_ai_json_object(raw)
    ai_raw = clean((obj or {}).get("DangBaiTap") or (obj or {}).get("dangbaitap") or "")
    if not ai_raw or _is_bad_dangbaitap_value(ai_raw):
        return jsonify({"error": "GPT chưa trả Dạng bài tập hợp lệ.", "raw": raw[:2000]}), 500
    ai_used_existing = bool((obj or {}).get("used_existing"))
    val, synced_from, matched_existing = _resolve_dangbaitap_to_suggestions(
        ai_raw, suggestions, allow_fuzzy=ai_used_existing
    )
    row = int(body.get("row") or q.get("_row") or 0)
    qid = clean(body.get("id") or body.get("ID") or q.get("ID") or "")
    res = {
        "ok": True,
        "DangBaiTap": val,
        "ai_raw": ai_raw,
        "synced_from": synced_from or "",
        "matched_existing": bool(matched_existing),
        "scope_level": scope_level,
        "suggestion_count": len(suggestions),
        "reason": clean((obj or {}).get("reason", "")),
        "provider_used": provider,
        "model": model,
        "saved": False,
    }
    if save_sheet and row >= 2:
        upd = st.update_question(row, {"DangBaiTap": val}, qid)
        res.update({"row": upd.get("row", row), "fields": upd.get("fields", [])})
        res["saved"] = True
    elif not save_sheet:
        sync_note = f" (đồng bộ từ «{synced_from}»)" if synced_from and synced_from != ai_raw else ""
        res.update({"message": f"GPT gợi ý Dạng bài tập{sync_note}, chưa lưu Sheet."})
    else:
        res.update({"warning": "Chưa có dòng Sheet nên chỉ trả gợi ý, chưa lưu."})
    return jsonify(res)

