@app.route("/api/admin/question-similar", methods=["POST"])
def api_admin_question_similar():
    """ADMIN: tạo câu tương tự từ câu đang sửa → điền form Thêm mới rồi Lưu Sheet."""
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN được tạo câu tương tự để lưu."}), 403
    refresh_session_role_from_store()
    data = request.get_json(silent=True) or {}
    q_in = data.get("question") or data.get("q") or {}
    if not isinstance(q_in, dict):
        return jsonify({"error": "Thiếu question."}), 400
    q = {f: clean(q_in.get(f, "")) for f in QUESTION_FIELDS}
    if not clean(q.get("CauHoi")):
        return jsonify({"error": "Câu gốc chưa có nội dung (CauHoi)."}), 400
    q["Dang"] = effective_dang(q) if clean(q.get("Dang")) else clean(q_in.get("Dang", "Trắc nghiệm"))
    peer_briefs: List[str] = []
    raw_peers = data.get("peer_briefs") or []
    if isinstance(raw_peers, list):
        for p in raw_peers:
            t = clean(p)
            if t:
                peer_briefs.append(t[:220])
            if len(peer_briefs) >= 5:
                break
    if not peer_briefs and clean(q.get("DangBaiTap")):
        try:
            st = get_store()
            st.ensure_questions_loaded()
            q_dang = key_norm(q.get("DangBaiTap"))
            src_id = clean(q.get("ID"))
            for oq in st.questions:
                if key_norm(oq.get("DangBaiTap")) != q_dang:
                    continue
                if src_id and clean(oq.get("ID")) == src_id:
                    continue
                t = clean(oq.get("CauHoi", ""))
                if not t:
                    continue
                peer_briefs.append(t[:220])
                if len(peer_briefs) >= 5:
                    break
        except Exception:
            log_swallow("api_admin_question_similar:peers")
    text, key_index, provider_used, ai_error = ai_similar_question_from_provider(
        q, peer_briefs=peer_briefs
    )
    body_full = sanitize_hint_math_text(text) or ""
    if not body_full or provider_used == "FALLBACK":
        return jsonify(
            {
                "ok": False,
                "error": ai_error
                or "Chưa tạo được câu tương tự — kiểm tra key AI rồi thử lại.",
                "provider_used": provider_used,
            }
        ), 400
    tips = parse_similar_variant_tips(body_full)
    similar_body = strip_similar_variant_section(body_full) or body_full
    fields = parse_similar_ai_to_question_fields(body_full, q.get("Dang", ""))
    if not clean(fields.get("CauHoi")):
        return jsonify(
            {
                "ok": False,
                "error": "AI trả lời nhưng chưa tách được nội dung câu hỏi.",
                "similar": similar_body,
                "admin_variant_tips": tips,
                "provider_used": provider_used,
            }
        ), 400
    # Giữ metadata phạm vi từ câu gốc — ADMIN chỉ cần kiểm tra nội dung rồi Lưu.
    for meta in (
        "MaDe",
        "Mon",
        "Lop",
        "Chuong",
        "BaiHoc",
        "DangBaiTap",
        "NangLucVatLy",
        "QuyenTruyCap",
        "MucDo",
    ):
        if clean(q.get(meta)) and not clean(fields.get(meta)):
            fields[meta] = clean(q.get(meta))
    if not clean(fields.get("Dang")):
        fields["Dang"] = q.get("Dang") or "Trắc nghiệm"
    return jsonify(
        {
            "ok": True,
            "fields": fields,
            "similar": similar_body,
            "admin_variant_tips": tips,
            "key_index": key_index,
            "provider_used": provider_used,
            "ai_error": ai_error,
            "message": "Đã tạo câu tương tự — kiểm tra form rồi Thêm vào Google Sheet.",
        }
    )


def _chat_message_about_question(message: Any) -> bool:
    """True nếu tin nhắn chat có vẻ hỏi về bài đang mở; False = hỏi ngoài đề."""
    msg = strip_accents(clean(message)).lower()
    if not msg:
        return True
    study_signals = (
        "dap an", "giai", "cong thuc", "buoc", "tai sao", "vi sao",
        "phuong an", "lua chon", "y a", "y b", "y c", "y d",
        "cau hoi", "de bai", "tikz", "latex", "sua de", "kiem tra",
        "tom tat", "tuong tu", "dung sai", "trac nghiem", "tln",
        "thay so", "loi giai", "giai chi tiet", "cau nay", "bai nay",
        "hint", "goi y", "chi tiet", "giai thich",
    )
    off_topic_signals = (
        "hom nay", "thu may", "ngay nao", "may gio", "gio nao",
        "thoi tiet", "bao nhieu tuoi", "ban la ai", "ai la ban",
        "xin chao", "chao ban", "chao thay", "cam on", "thank",
        "what day", "what time", "today", "hello", "who are you",
        "may tuoi", "ten gi", "ban ten",
    )
    if any(k in msg for k in study_signals):
        return True
    if any(k in msg for k in off_topic_signals):
        return False
    if len(msg.split()) <= 8 and not any(c in msg for c in "=$\\"):
        return False
    return True


def _ai_gemini_client_ready() -> bool:
    return callable(solve_problem_with_gemini)


def generate_similar_questions_shared(problem_text: str, q: Dict[str, Any], n: int = 1) -> Dict[str, Any]:
    """[SHARED] Lõi tạo câu tương tự — dùng chung bởi /api/ai/similar và /api/hint/similar."""
    if not _ai_gemini_client_ready():
        return {"ok": False, "error": "Module ai_gemini_client chưa sẵn sàng."}
    keys = load_ai_keys("GEMINI")
    if not keys:
        return {"ok": False, "error": "Chưa có Gemini API key."}
    return generate_similar_with_gemini(problem_text, n=n, api_keys=keys, context=q)


def _similar_shared_result_to_text(result: Dict[str, Any]) -> str:
    """Gộp items[]/text từ kết quả AI thành 1 chuỗi hiển thị cho /api/hint/similar."""
    items = result.get("items") or []
    if items:
        parts = []
        for i, it in enumerate(items, start=1):
            block = f"Câu {i}\n{clean(it.get('question', ''))}"
            if it.get("choices"):
                block += f"\n{clean(it.get('choices'))}"
            if it.get("answer"):
                block += f"\nĐA: {clean(it.get('answer'))}"
            if it.get("solution"):
                block += f"\n{clean(it.get('solution'))}"
            parts.append(block)
        return "\n\n".join(parts)
    return clean(result.get("similar") or result.get("raw_text") or result.get("hint") or "")


def _ai_gemini_resolve_question(data: Dict[str, Any]) -> Tuple[Dict[str, Any], int, str]:
    """Lấy câu hỏi từ sid/index hoặc problem_text/question trong body."""
    sid = clean(data.get("sid"))
    try:
        idx = int(data.get("index", 0))
    except Exception:
        log_swallow("_ai_gemini_resolve_question:30764")
        idx = 0
    if sid:
        restore = quiz_restore_payload_from_body(data)
        ses = get_store().check_quiz_session(sid, restore)
        qs = ses["questions"]
        if not (0 <= idx < len(qs)):
            raise RuntimeError("Số câu không hợp lệ")
        store = get_store()
        q = assistant_question_from_session(store, ses, qs, idx)
        block = build_ai_question_block(
            q,
            data.get("answer", ""),
            include_sheet_answer=is_admin(),
            include_loigiai=is_admin(),
        )
        return q, idx, block
    q_in = data.get("question") or data.get("q") or {}
    if isinstance(q_in, dict) and clean(q_in.get("CauHoi")):
        q = {f: clean(q_in.get(f, "")) for f in QUESTION_FIELDS}
        q["Dang"] = effective_dang(q)
        block = build_ai_question_block(
            q,
            data.get("answer", ""),
            include_sheet_answer=is_admin(),
            include_loigiai=is_admin(),
        )
        return q, -1, block
    pt = clean(data.get("problem_text", data.get("text", "")))
    if pt:
        ctx = data.get("context") if isinstance(data.get("context"), dict) else {}
        q = {f: clean(ctx.get(f, "")) for f in QUESTION_FIELDS}
        q["CauHoi"] = pt
        q["Dang"] = effective_dang(q) if clean(q.get("Dang")) else clean(ctx.get("Dang", "Trắc nghiệm"))
        return q, -1, pt
    raise RuntimeError("Thiếu sid/index hoặc problem_text/question.")


def _ai_gemini_image_payload(q: Dict[str, Any]) -> Optional[Dict[str, str]]:
    vision = prepare_question_vision(q)
    if not vision.get("vision_ready"):
        return None
    b64 = clean(vision.get("image_b64", ""))
    mime = clean(vision.get("image_mime", ""))
    if not b64 or not mime:
        return None
    return {"b64": b64, "mime": mime}


def _ai_gemini_solve_handler():
    if not _ai_gemini_client_ready():
        return jsonify({"error": "Module ai_gemini_client chưa sẵn sàng."}), 500
    bad = require_login_json()
    if bad:
        return bad
    bad_ai = require_ai_hint_json()
    if bad_ai:
        return bad_ai
    refresh_session_role_from_store()
    data = request.get_json(silent=True) or {}
    try:
        q, idx, problem_text = _ai_gemini_resolve_question(data)
    except Exception as e:
        return jsonify({"error": str(e)}), 400
    hard = bool(data.get("hard"))
    keys = load_ai_keys("GEMINI")
    if not keys:
        return jsonify({"error": "Chưa có Gemini API key."}), 400
    image = _ai_gemini_image_payload(q)
    if isinstance(data.get("image"), dict):
        img_in = data["image"]
        b64 = clean(img_in.get("b64", img_in.get("data", "")))
        mime = clean(img_in.get("mime", img_in.get("mime_type", "image/png")))
        if b64 and mime:
            image = {"b64": b64, "mime": mime}

    @copy_current_request_context
    def _worker():
        return solve_problem_with_gemini(
            problem_text,
            image=image,
            hard=hard,
            api_keys=keys,
            context=q,
            admin_mode=is_admin(),
            user_answer=clean(data.get("answer", "")),
        )

    try:
        with ThreadPoolExecutor(max_workers=1) as pool:
            result = pool.submit(_worker).result(timeout=ASSISTANT_HTTP_MAX_SEC)
    except FuturesTimeout:
        return jsonify({"ok": False, "error": f"Quá {ASSISTANT_HTTP_MAX_SEC}s — thử lại hoặc bật hard=false."}), 504
    if not result.get("ok"):
        return jsonify(result), 400
    model_used = clean(result.get("model", ""))
    tier = "pro" if hard else "flash"
    return jsonify({
        **result,
        "index": idx,
        "show_answer": is_admin(),
        "hard": hard,
        "version": APP_VERSION,
        "message": f"Giải bài — {model_used or ('gemini-2.5-' + tier)}.",
    })


