def _strip_html_for_ai_text(raw: Any) -> str:
    t = clean(raw)
    t = re.sub(r"<[^>]+>", " ", t)
    t = re.sub(r"\s+", " ", t).strip()
    return t


def _sanitize_translation_text(txt: Any) -> str:
    t = sanitize_hint_math_text(clean(txt))
    t = re.sub(r"```(?:json)?", "", t, flags=re.I).strip()
    if len(t) > 5000:
        t = t[:5000].rstrip() + "…"
    return t


def _parse_translation_en_response(raw: Any) -> Tuple[str, str, str]:
    """Tách English / Vocabulary / Notes từ phản hồi AI."""
    t = _sanitize_translation_text(raw)
    if not t:
        return "", "", ""
    english = t
    vocab = ""
    notes = ""
    m_en = re.search(r"(?i)^English:\s*\n?(.*?)(?=\n\s*Vocabulary:|\n\s*Notes:|\Z)", t, re.S)
    if m_en:
        english = m_en.group(1).strip()
    m_v = re.search(r"(?i)Vocabulary:\s*\n?(.*?)(?=\n\s*Notes:|\Z)", t, re.S)
    if m_v:
        vocab = m_v.group(1).strip()
    m_n = re.search(r"(?i)Notes:\s*\n?(.*)$", t, re.S)
    if m_n:
        notes = m_n.group(1).strip()
    if not english:
        english = t
    return english, vocab, notes


def _parse_translate_en_abcd_py(text: str) -> Tuple[str, Dict[str, str]]:
    """Tách đề + phương án A–D từ bản dịch EN (chịu cả dạng gộp một dòng)."""
    t = clean(text)
    if not t:
        return "", {}
    t = re.sub(r"\(\s*([ABCD])\s*[.)]\s*\)", r"\n\1. ", t, flags=re.I)
    t = re.sub(r"([^\n\r])([BCD])[.)]\s+", r"\1\n\2. ", t, flags=re.I)
    markers: List[Dict[str, Any]] = []
    for m in re.finditer(r"(?:^|\n)\s*([ABCD])[.)]\s*", t, flags=re.I):
        letter = m.group(1).upper()
        if any(x["letter"] == letter for x in markers):
            continue
        markers.append({"letter": letter, "start": m.start(), "content_start": m.end()})
    opts: Dict[str, str] = {}
    stem = ""
    if not markers:
        return t, {}
    if markers[0]["letter"] != "A":
        before = t[: markers[0]["start"]].strip()
        sm = re.match(
            r"^([\s\S]*?)(?:\n\s*\n|(?:^|\n)\s*(?:Phương án|Options)\s*:?\s*\n)([\s\S]+)$",
            before,
            flags=re.I,
        )
        if sm:
            stem, opts["A"] = sm.group(1).strip(), sm.group(2).strip()
        else:
            qm = re.match(r"^([\s\S]*?\?)\s+([\s\S]+)$", before)
            if qm and qm.group(2).strip():
                stem, opts["A"] = qm.group(1).strip(), qm.group(2).strip()
            else:
                stem = before
    else:
        stem = t[: markers[0]["start"]].strip()
        stem = re.sub(r"\n*(?:Phương án|Options)\s*:?\s*$", "", stem, flags=re.I).strip()
    for i, mk in enumerate(markers):
        end = markers[i + 1]["start"] if i + 1 < len(markers) else len(t)
        opts[mk["letter"]] = t[mk["content_start"] : end].strip()
    a = opts.get("A", "")
    if a and re.search(r"(?:^|[\s(])([BCD])[.)]\s*", a, flags=re.I):
        subs = []
        for mm in re.finditer(r"(?:^|[\s(])([BCD])[.)]\s*", a, flags=re.I):
            ls = mm.start() + mm.group(0).upper().find(mm.group(1).upper())
            subs.append({"letter": mm.group(1).upper(), "start": ls, "content_start": mm.end()})
        if subs:
            opts["A"] = a[: subs[0]["start"]].strip()
            for j, sb in enumerate(subs):
                e = subs[j + 1]["start"] if j + 1 < len(subs) else len(a)
                opts[sb["letter"]] = a[sb["content_start"] : e].strip()
    return stem, opts


def _normalize_translate_en_abcd(english: str, q: Dict[str, Any]) -> str:
    """Chuẩn hóa bản dịch: mỗi phương án A–D một dòng riêng."""
    if not english or not any(clean(q.get(L, "")) for L in "ABCD"):
        return english
    stem, opts = _parse_translate_en_abcd_py(english)
    if not opts:
        return english
    lines: List[str] = []
    if stem:
        lines.append(stem)
    opt_lines = [f"{L}. {opts[L]}" for L in "ABCD" if clean(opts.get(L, ""))]
    if opt_lines:
        if lines:
            lines.append("")
        lines.append("Options:")
        lines.extend(opt_lines)
    return "\n".join(lines).strip() if opt_lines else english


def _translate_sensitive_allowed(answer: Any) -> bool:
    """Đáp án/lời giải chỉ dịch sau khi học sinh đã làm câu (tránh lộ đáp án sớm)."""
    if is_admin():
        return True
    if not can_view_solution_live():
        return False
    if answer is None:
        return False
    if isinstance(answer, (list, tuple)):
        return any(clean(x) for x in answer)
    return bool(clean(str(answer)))


def _build_translate_cauhoi_text(q: Dict[str, Any]) -> str:
    """Ghép đề + phương án A/B/C/D để dịch — nhãn A. B. C. D. khớp câu trên màn hình."""
    stem = clean(q.get("CauHoi", ""))
    opts: List[str] = []
    for L in "ABCD":
        v = clean(q.get(L, ""))
        if v:
            opts.append(f"{L}. {v}")
    if not opts:
        return stem
    return stem + "\n\nPhương án:\n" + "\n".join(opts)


def _build_translate_dapan_text(q: Dict[str, Any]) -> str:
    dapan = clean(q.get("DapAn", ""))
    if not dapan:
        return ""
    dang = effective_dang(q)
    if dang == "Trắc nghiệm":
        letter = norm_letter(dapan)
        bits = [f"Correct answer: {letter}" if letter else f"Answer: {dapan}"]
        if letter and clean(q.get(letter, "")):
            bits.append(f"{letter}. {clean(q.get(letter, ''))}")
        return "\n".join(bits)
    if dang == "Đúng sai":
        disp = format_tf_answer_display(q, dapan)
        stmt_bits = []
        for L in "ABCD":
            stmt = clean(q.get(L, ""))
            if stmt:
                stmt_bits.append(f"{L}. {stmt}")
        head = f"True/False answer key: {disp}" if disp else f"Answer key: {dapan}"
        return head + ("\n" + "\n".join(stmt_bits) if stmt_bits else "")
    return f"Answer: {dapan}"


def build_translate_en_prompt(text: str, loai: str, q: Dict[str, Any]) -> str:
    meta = " · ".join([clean(q.get(k, "")) for k in ["Mon", "Lop", "Chuong", "BaiHoc", "DangBaiTap"] if clean(q.get(k, ""))])
    abcd_rule = ""
    if clean(loai) == "CauHoi" and any(clean(q.get(L, "")) for L in "ABCD"):
        abcd_rule = (
            "QUAN TRỌNG — Câu có phương án A/B/C/D: phần English phải giữ đúng nhãn và thứ tự như đề gốc.\n"
            "Dịch phần đề trước, sau đó MỖI phương án một dòng bắt đầu bằng A. / B. / C. / D. (không đổi thành 1.2.3. hay bullet).\n"
            "Ví dụ:\n"
            "A charged particle moves...\n"
            "A. The velocity doubles\n"
            "B. The momentum is conserved\n"
        )
    return "\n".join([
        "Bạn là trợ lý tiếng Anh học thuật cho học sinh THPT Việt Nam.",
        "Nhiệm vụ: chuyển nội dung sang tiếng Anh rõ, đúng thuật ngữ Toán/Lý, giữ LaTeX/công thức trong $...$ nếu có.",
        "Không giải bài, không chốt đáp án, không thêm lời giải. Chỉ dịch và giải thích từ vựng cần thiết.",
        abcd_rule,
        "Trả lời đúng cấu trúc:",
        "English:",
        "<bản dịch tiếng Anh>",
        "",
        "Vocabulary:",
        "- term: nghĩa tiếng Việt ngắn",
        "",
        "Notes:",
        "- lưu ý cách hiểu/cách đọc đơn vị nếu có",
        "",
        f"Loại nội dung: {loai}",
        f"Ngữ cảnh: {meta}",
        "Nội dung cần dịch:",
        text,
    ])


def translate_en_from_provider(text: str, loai: str, q: Dict[str, Any]) -> Tuple[str, int, str, str, str]:
    cfg = ai_runtime_config()
    # ADMIN được dùng OpenAI/ChatGPT theo AI_ADMIN_PROVIDER; người dùng còn lại chỉ Gemini và phải có key riêng.
    if is_admin():
        provider = clean(cfg.get("admin_provider") or os.environ.get("AI_ADMIN_PROVIDER", "OPENAI") or "OPENAI").upper()
        gemini_keys = load_ai_keys("GEMINI")
        openai_keys = load_ai_keys("OPENAI")
    else:
        provider = "GEMINI"
        # VIP/S.VIP tự nhập key để không tốn key hệ thống.
        gemini_keys = load_user_ai_keys("GEMINI")
        openai_keys = []
    if provider not in ("OPENAI", "GEMINI", "AUTO"):
        provider = "GEMINI"
    if not is_admin() and not gemini_keys:
        return "", 0, "GEMINI", "", "VIP/S.VIP muốn dịch tiếng Anh bằng AI cần tự nhập Gemini key."
    model_openai = clean(cfg.get("openai_model") or os.environ.get("OPENAI_HINT_MODEL", DEFAULT_OPENAI_HINT_MODEL)).strip() or DEFAULT_OPENAI_HINT_MODEL
    model_gemini = clean(cfg.get("gemini_model") or os.environ.get("GEMINI_HINT_MODEL", DEFAULT_GEMINI_HINT_MODEL)).strip() or DEFAULT_GEMINI_HINT_MODEL
    sys_prompt = "Bạn dịch sang tiếng Anh học thuật, giữ công thức, không giải bài và không chốt đáp án."
    user_prompt = build_translate_en_prompt(text, loai, q)
    last_error = ""

    def try_openai() -> Tuple[str, int, str, str, str]:
        nonlocal last_error
        for idx, api_key in enumerate(openai_keys, start=1):
            txt, finish, err = _openai_chat_call(api_key, model_openai, sys_prompt, user_prompt, 900, 0.1, timeout=35)
            if err:
                last_error = err
                continue
            txt = _sanitize_translation_text(txt)
            if txt:
                return txt, idx, "OPENAI", model_openai, ""
        return "", 0, "OPENAI", model_openai, last_error

    def try_gemini() -> Tuple[str, int, str, str, str]:
        nonlocal last_error
        models = [model_gemini] + [m for m in GEMINI_HINT_MODEL_FALLBACKS if m != model_gemini]
        for idx, api_key in enumerate(gemini_keys, start=1):
            for gm in models:
                txt, finish, err = _gemini_hint_call(api_key, gm, sys_prompt, user_prompt, 900, 0.1, timeout=28)
                if err:
                    last_error = err
                    continue
                txt = _sanitize_translation_text(txt)
                if txt:
                    return txt, idx, "GEMINI", gm, ""
        return "", 0, "GEMINI", model_gemini, last_error

    # VIP/SVIP: chỉ Gemini key người dùng — không GPT. ADMIN mới được GPT (theo AI_ADMIN_PROVIDER).
    if is_admin():
        if provider == "OPENAI":
            order = [try_openai, try_gemini]
        elif provider == "GEMINI":
            order = [try_gemini, try_openai]
        else:
            order = [try_openai, try_gemini]
    else:
        order = [try_gemini]
    for fn in order:
        txt, idx, used, model, err = fn()
        if txt:
            return txt, idx, used, model, ""
    return "", 0, provider, "", last_error or "AI chưa phản hồi."


@app.route("/api/translate/en", methods=["POST"])
def api_translate_en():
    bad = require_login_json()
    if bad:
        return bad
    refresh_session_role_from_store()
    data = request.get_json(silent=True) or {}
    sid = clean(data.get("sid"))
    try:
        idx = int(data.get("index", 0))
    except Exception:
        log_swallow("api_translate_en:31345")
        idx = 0
    loai = clean(data.get("type") or data.get("loai") or "CauHoi") or "CauHoi"
    text = _strip_html_for_ai_text(data.get("text", ""))
    restore = quiz_restore_payload_from_body(data)
    q: Dict[str, Any] = {}
    try:
        if sid:
            ses = get_store().check_quiz_session(sid, restore)
            qs = ses.get("questions") or []
            if 0 <= idx < len(qs):
                q = qs[idx]
    except Exception:
        log_swallow("api_translate_en:31357")
        q = {}
    if loai in ("DapAn", "LoiGiai") and not _translate_sensitive_allowed(data.get("answer")):
        return jsonify({"error": "Hãy làm và chấm câu này trước khi dịch đáp án / lời giải."}), 403
    if not text and q:
        if loai == "CauHoi":
            text = _build_translate_cauhoi_text(q)
        elif loai == "DapAn":
            text = _build_translate_dapan_text(q)
        elif loai == "LoiGiai":
            text = clean(q.get("LoiGiai", ""))
    if not text:
        return jsonify({"error": "Chưa có văn bản để dịch."}), 400
    if len(text) > 6000:
        text = text[:6000]
    store = get_store()
    cached = store.get_translation_en_cached(
        text=text,
        mon=clean(q.get("Mon", data.get("Mon", ""))),
        lop=clean(q.get("Lop", data.get("Lop", ""))),
        chuong=clean(q.get("Chuong", data.get("Chuong", ""))),
        baihoc=clean(q.get("BaiHoc", data.get("BaiHoc", ""))),
        dangbaitap=clean(q.get("DangBaiTap", data.get("DangBaiTap", ""))),
        loai=loai,
    )
    if cached and clean(cached.get("BanDichAnh", "")):
        en_txt = clean(cached.get("BanDichAnh", ""))
        vocab_txt = clean(cached.get("TuVung", ""))
        notes_txt = clean(cached.get("GhiChu", ""))
        if not vocab_txt and not notes_txt:
            en_txt, vocab_txt, notes_txt = _parse_translation_en_response(en_txt)
        if loai == "CauHoi" and q:
            en_txt = _normalize_translate_en_abcd(en_txt, q)
        return jsonify({"ok": True, "cached": True, "item": cached, "translation": en_txt, "vocabulary": vocab_txt, "notes": notes_txt})
    return jsonify({
        "ok": False,
        "cached": False,
        "use_ai_mode": True,
        "message": "Chưa có bản dịch lưu Sheet Dich_Anh. Bấm 🇬🇧 Dịch để mở AI Internet (Google) — không tốn key GPT/Gemini của app.",
        "error": "Chưa có bản dịch lưu. Dùng nút 🇬🇧 Dịch (AI Internet).",
    }), 404


