def _keys_from_check_body(body: Dict[str, Any], provider: str) -> List[Tuple[str, str]]:
    """Lấy danh sách key từ body test — mỗi dòng một key trong ô nhập."""
    p = clean(provider).upper() or DEFAULT_AI_PROVIDER
    items: List[Tuple[str, str]] = []
    seen: set = set()
    for field in ("api_keys", "gemini_keys", "openai_keys", "anthropic_keys"):
        raw = body.get(field)
        if not str(raw or "").strip():
            continue
        g_keys, o_keys, a_keys = parse_api_keys_2026(raw)
        if p in ("GEMINI", "AUTO"):
            pick = g_keys
        elif p in ("ANTHROPIC", "CLAUDE"):
            raw_s = "" if isinstance(raw, list) else str(raw or "").strip()
            pick = a_keys or ([raw_s] if _is_anthropic_api_key(raw_s) else [])
        else:
            pick = o_keys
        if p == "AUTO" and not pick:
            pick = a_keys or o_keys
        for idx, k in enumerate(pick, start=1):
            if k in seen:
                continue
            seen.add(k)
            src = "Ô nhập" if len(pick) == 1 else f"Ô nhập (dòng {idx})"
            items.append((k, src))
    single = clean_ai_key_2026(body.get("api_key", ""))
    if single and single not in seen:
        items.append((single, "Ô nhập"))
    return items[:MAX_AI_KEYS_PER_PROVIDER]


def _ai_key_check_response(ok: bool, msg: str, provider: str, details: List[Dict[str, Any]]) -> Any:
    return jsonify({
        "ok": ok,
        "message": msg,
        "version": APP_VERSION,
        "provider_used": provider,
        "keys_tested": len(details),
        "keys_ok": sum(1 for d in details if d.get("ok")),
        "details": details,
    })


def _run_ai_key_check(provider: str, body: Dict[str, Any], quick: bool = True) -> Tuple[bool, str, str, List[Dict[str, Any]]]:
    provider = clean(provider or body.get("provider", DEFAULT_AI_PROVIDER)).upper() or DEFAULT_AI_PROVIDER
    if not is_admin() and provider in ["OPENAI", "AUTO"]:
        provider = "GEMINI"
    model = clean(body.get("model", ""))
    if not model and provider in ["GEMINI", "AUTO"]:
        model = clean(body.get("gemini_model", ""))
    if not model and provider in ["OPENAI", "AUTO"]:
        model = (
            clean(body.get("openai_model", ""))
            or clean(os.environ.get("OPENAI_ADMIN_MODEL", DEFAULT_OPENAI_ADMIN_MODEL))
            or DEFAULT_OPENAI_ADMIN_MODEL
        )
    used_provider = provider
    if provider in ["GEMINI", "AUTO"]:
        used_provider = "GEMINI"
    elif provider == "OPENAI":
        used_provider = "OPENAI"
    elif provider in ["ANTHROPIC", "CLAUDE"]:
        used_provider = "ANTHROPIC"

    input_items = _keys_from_check_body(body, provider)
    if len(input_items) >= 1:
        ok, msg, details = test_ai_key_batch(used_provider, input_items, model, quick=quick)
        return ok, msg, used_provider, details

    runtime_items = _runtime_ai_key_items(used_provider)
    if runtime_items:
        ok, msg, details = test_ai_key_batch(used_provider, runtime_items, model, quick=quick)
        return ok, msg, used_provider, details

    key, used_provider = _resolve_runtime_test_key(provider)
    if not key:
        empty_msg = (
            "Chưa có key Gemini. Vào https://aistudio.google.com/apikey → Create API key → copy key AIza... hoặc AQ... → về app mở 🔑 Key AI → dán key → Lưu."
            if used_provider == "GEMINI"
            else (
                "Chưa có Claude key. Vào https://console.anthropic.com/settings/keys → tạo key sk-ant-... → 🔑 Key AI → Lưu."
                if used_provider == "ANTHROPIC"
                else "Chưa có OPENAI_API_KEY trên Render ENV."
            )
        )
        return False, empty_msg, used_provider, []

    ok, msg, details = test_ai_key_batch(used_provider, [(key, "Key đang dùng")], model, quick=quick)
    return ok, msg, used_provider, details


