@app.route("/api/admin/ai-generate-model", methods=["POST"])
def api_admin_ai_generate_model():
    """ADMIN: AI (Gemini/Claude/GPT) tạo mã Python mô hình hóa + công thức để lưu."""
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN được dùng AI tạo mô hình."}), 403
    body = request.get_json(silent=True) or {}
    sub = clean(body.get("sub") or body.get("mon") or "math").lower()
    if sub in ("toan", "toán", "math"):
        sub = "math"
        mon_label = "Toán"
    else:
        sub = "phys"
        mon_label = "Vật lí"
    topic = clean(body.get("topic") or body.get("prompt") or body.get("name") or "")
    lop = clean(body.get("lop") or body.get("Lop") or "")
    if not topic:
        return jsonify({"error": "Nhập chủ đề / tên mô hình cần AI tạo."}), 400
    force, allow = admin_ai_body_params(body)
    ant = clean(body.get("anthropic_key") or "")
    try:
        admin_ai_require_provider_keys(force, ant)
    except Exception as e:
        return jsonify({"error": str(e)}), 400
    lop_hint = lop or "theo chủ đề"
    sys_prompt = (
        "Bạn là giáo viên THPT Việt Nam, chuyên mô hình hóa / mô phỏng số bằng Python. "
        "Chỉ trả đúng 1 JSON object, không markdown ngoài JSON, không giải thích."
    )
    user_prompt = "\n".join(
        [
            f"Tạo MỘT ứng dụng mô hình hóa/mô phỏng môn {mon_label}"
            + (f", lớp {lop}" if lop else "")
            + " chạy ngay trong trình duyệt (Pyodide).",
            f"Chủ đề / yêu cầu: {topic}",
            "",
            'Trả đúng JSON: {"name":"...","desc":"...","formula":"...","lop":"...","code":"..."}',
            "",
            "Quy tắc bắt buộc cho khóa code:",
            "- Chỉ import numpy và matplotlib.pyplot (có thể `import numpy as np` / `import matplotlib.pyplot as plt`).",
            "- CẤM: scipy, pandas, sympy, seaborn, plotly, pygame, tkinter, requests, PIL, animation GUI.",
            "- Đặt tham số số ở ĐẦU file dạng dòng riêng: v0 = 10, alpha = 45, a = 1 (để học sinh chỉnh).",
            "- Vẽ bằng plt.figure / plt.plot / plt.scatter…; có thể gọi plt.show() (app sẽ tự hiện ảnh).",
            "- Không dùng input(), open(), file, mạng.",
            "- Code ngắn gọn, chạy được, có chú thích tiếng Việt ngắn.",
            "- name ≤ 80 ký tự tiếng Việt; desc 1 câu; formula LaTeX trong $...$ hoặc rỗng.",
            f"- lop: 10 hoặc 11 hoặc 12 (ưu tiên {lop_hint}).",
            "- Trong JSON, ký tự trong code phải escape đúng (\\n cho xuống dòng).",
        ]
    )
    try:
        txt, provider, model, _ki = admin_ai_call_text(
            sys_prompt,
            user_prompt,
            max_tokens=6000,
            temp=0.2,
            timeout=85,
            force_provider=force,
            allow_gpt_fallback=allow,
            extra_anthropic_key=ant,
        )
    except AdminGeminiQuotaError as e:
        return admin_ai_quota_json(e)
    except Exception as e:
        return jsonify({"error": str(e) or "AI không tạo được mô hình."}), 400
    if not clean(txt):
        return jsonify({"error": "AI không trả nội dung. Thử lại hoặc đổi Gemini/Claude/GPT."}), 400
    raw = _json_loads_ai_lenient(txt)
    if isinstance(raw, list) and raw and isinstance(raw[0], dict):
        raw = raw[0]
    if not isinstance(raw, dict):
        mobj = re.search(r"\{[\s\S]*\}", str(txt or ""))
        if mobj:
            raw = _json_loads_ai_lenient(mobj.group(0))
            if isinstance(raw, list) and raw and isinstance(raw[0], dict):
                raw = raw[0]
    if not isinstance(raw, dict):
        # Fallback: lấy khối ```python nếu AI không trả JSON
        mcode = re.search(r"```(?:python|py)?\s*([\s\S]+?)```", str(txt or ""), flags=re.I)
        if mcode:
            code_fb = sanitize_pyodide_model_code(mcode.group(1))
            if code_fb:
                raw = {
                    "name": topic[:80],
                    "desc": f"Mô phỏng {topic}",
                    "formula": "",
                    "lop": lop,
                    "code": code_fb,
                }
    if not isinstance(raw, dict):
        return jsonify({
            "error": "AI không trả JSON hợp lệ. Bấm lại hoặc đổi nhà AI (Gemini/Claude).",
            "raw": (txt or "")[:800],
        }), 400
    name = clean(raw.get("name") or topic)[:120]
    desc = clean(raw.get("desc") or raw.get("description") or "")[:300]
    formula = clean(raw.get("formula") or raw.get("cong_thuc") or "")[:800]
    code = extract_model_code_from_ai_obj(raw)
    out_lop = clean(raw.get("lop") or lop) or lop
    if not code:
        return jsonify({
            "error": "AI chưa trả mã Python (khóa code trống). Thử lại / đổi AI.",
            "raw": (txt or "")[:800],
        }), 400
    # Cảnh báo nhẹ nếu thiếu matplotlib/numpy nhưng vẫn cho lưu
    low = code.lower()
    if "matplotlib" not in low and "pyplot" not in low and "plt." not in low:
        # vẫn OK nếu chỉ print số; không chặn
        pass
    item = {
        "name": name,
        "desc": desc or f"Mô phỏng: {name}",
        "formula": formula,
        "lop": out_lop,
        "kind": "python",
        "code": code,
        "quyen": clean(body.get("quyen") or "FREE") or "FREE",
        "url": "",
        "note": f"AI {provider} {model}".strip(),
    }
    return jsonify(
        {
            "ok": True,
            "item": item,
            "provider_used": provider,
            "model": model,
            "sub": sub,
        }
    )


@app.route("/api/admin/dang-similarity", methods=["POST"])
def api_admin_dang_similarity():
    """ADMIN: phân tích độ giống câu hỏi / khung PP trong cùng dạng BT (ngưỡng 70%)."""
    # NOTE: body of this function continues below — this marker was replaced carefully.
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN được phân tích trùng dạng."}), 403
    body = request.get_json(silent=True) or {}
    st = get_store()
    st.ensure_questions_loaded()
    st.ensure_learning_loaded()
    try:
        threshold = float(body.get("threshold") or DANG_CONTENT_SIMILARITY_THRESHOLD)
    except Exception:
        log_swallow("api_admin_dang_similarity:32674")
        threshold = DANG_CONTENT_SIMILARITY_THRESHOLD
    threshold = max(0.5, min(0.95, threshold))
    report = analyze_dang_content_similarity(
        st.questions,
        st.method_items,
        threshold=threshold,
        mon=clean(body.get("Mon") or body.get("mon") or ""),
        lop=clean(body.get("Lop") or body.get("lop") or ""),
        chuong=clean(body.get("Chuong") or body.get("chuong") or ""),
        baihoc=clean(body.get("BaiHoc") or body.get("baihoc") or ""),
        dangbaitap=clean(body.get("DangBaiTap") or body.get("dangbaitap") or ""),
        made=clean(body.get("MaDe") or body.get("made") or ""),
        question_id=clean(body.get("ID") or body.get("id") or body.get("question_id") or ""),
    )
    if body.get("with_ai") and report.get("pair_count"):
        try:
            force, allow = admin_ai_body_params(body)
            report["ai_advice"] = ai_dang_similarity_advice(
                report, force_provider=force, allow_gpt_fallback=allow
            )
        except AdminGeminiQuotaError as e:
            return admin_ai_quota_json(e)
        except Exception as e:
            report["ai_advice_error"] = str(e)
    return jsonify(report)

@app.route("/api/admin/dbt-review-dup-scan", methods=["POST"])
def api_admin_dbt_review_dup_scan():
    """ADMIN: quét trùng ID/nội dung trong danh sách dòng đang duyệt Dạng BT."""
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN."}), 403
    body = request.get_json(silent=True) or {}
    rows_in = body.get("rows") or []
    if not isinstance(rows_in, list):
        return jsonify({"error": "Thiếu danh sách dòng Sheet."}), 400
    row_set = sorted({int(r) for r in rows_in if int(r or 0) > 1})
    if not row_set:
        return jsonify({"marks": {}, "copy_count": 0, "group_count": 0})
    try:
        st = get_store()
        st.ensure_questions_loaded()
        want = set(row_set)
        subset = [q for q in st.questions if int(q.get("_row") or 0) in want]
        plan = plan_sheet_duplicate_removals(subset)
        marks: Dict[str, Any] = {}
        for cluster in plan.get("clusters") or []:
            if len(cluster) < 2:
                continue
            keep = cluster[0]
            for r in cluster:
                if r not in want:
                    continue
                marks[str(r)] = {
                    "dup_type": "content",
                    "dup_keep": r == keep,
                    "dup_rows": cluster,
                }
        copy_count = sum(1 for m in marks.values() if not m.get("dup_keep"))
        group_count = sum(
            1 for c in (plan.get("clusters") or [])
            if len(c) >= 2 and any(r in want for r in c)
        )
        return jsonify({
            "marks": marks,
            "copy_count": copy_count,
            "group_count": group_count,
            "samples": (plan.get("samples") or [])[:8],
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 400

